local runtime = {
    Alive = true,
    Connections = {},
    Drawings = {},
    InfectedTexts = setmetatable({}, {__mode = "k"}),
}

runtime.NextConnectionPruneAt = 96

function runtime.PruneConnections()
    local list = runtime.Connections
    local writeIndex = 1

    for readIndex = 1, #list do
        local connection = list[readIndex]
        local connected = false
        if connection then
            pcall(function() connected = connection.Connected == true end)
        end

        if connected then
            list[writeIndex] = connection
            writeIndex = writeIndex + 1
        end
    end

    for index = #list, writeIndex, -1 do
        list[index] = nil
    end

    runtime.NextConnectionPruneAt = #list + 64
end

function runtime.Track(connection)
    if connection then
        local list = runtime.Connections
        list[#list + 1] = connection
        if #list >= (runtime.NextConnectionPruneAt or 96) then
            runtime.PruneConnections()
        end
    end
    return connection
end

function runtime.TrackDrawing(drawing)
    if drawing then table.insert(runtime.Drawings, drawing) end
    return drawing
end

function runtime.UntrackDrawing(drawing)
    if not drawing then return end
    local list = runtime.Drawings
    for i = #list, 1, -1 do
        if list[i] == drawing then
            list[i] = list[#list]
            list[#list] = nil
            return
        end
    end
end

function runtime.RemoveDrawing(drawing)
    if not drawing then return end
    runtime.UntrackDrawing(drawing)
    pcall(function() drawing:Remove() end)
end

function runtime.TrackInfectedText(textObject)
    if textObject then runtime.InfectedTexts[textObject] = true end
    return textObject
end

function runtime.Cleanup()
    if not runtime.Alive then return end
    runtime.Alive = false
    if runtime.FPSBoostCleanup then pcall(runtime.FPSBoostCleanup) end
    if runtime.GraphicsCleanup then pcall(runtime.GraphicsCleanup) end
    if runtime.CameraFOVCleanup then pcall(runtime.CameraFOVCleanup) end
    if runtime.ESPVisualCleanup then pcall(runtime.ESPVisualCleanup) end
    if runtime.VisualSpoofCleanup then pcall(runtime.VisualSpoofCleanup) end
    if runtime.DeathEffectsCleanup then pcall(runtime.DeathEffectsCleanup) end
    if runtime.ClearTeamCorpseCache then pcall(runtime.ClearTeamCorpseCache) end
    if runtime.SoundCleanup then pcall(runtime.SoundCleanup) end
    if runtime.TextureCleanup then pcall(runtime.TextureCleanup) end
    if runtime.HitboxCleanup then pcall(runtime.HitboxCleanup) end
    if runtime.QuickGunCleanup then pcall(runtime.QuickGunCleanup) end

    for i = #runtime.Connections, 1, -1 do
        local connection = runtime.Connections[i]
        pcall(function() connection:Disconnect() end)
        runtime.Connections[i] = nil
    end

    for i = #runtime.Drawings, 1, -1 do
        local drawing = runtime.Drawings[i]
        pcall(function() drawing:Remove() end)
        runtime.Drawings[i] = nil
    end

    for textObject in pairs(runtime.InfectedTexts) do
        pcall(function() textObject:SetAttribute("AstraInfectado", nil) end)
        runtime.InfectedTexts[textObject] = nil
    end

    if runtime.UninstallAimHooks then
        pcall(runtime.UninstallAimHooks, true)
    end

    if runtime.AimState and runtime.AimState.Owner == runtime then
        runtime.AimState.Target = nil
        runtime.AimState.RoundActive = false
        runtime.AimState.Wanted = false
        runtime.AimState.Owner = nil
    end

    if runtime.GhostCleanup then
        pcall(runtime.GhostCleanup)
    end

    if runtime.AvatarThumbnailSpoofCleanup then
        pcall(runtime.AvatarThumbnailSpoofCleanup)
    end

    if runtime.AppearanceCleanup then
        pcall(runtime.AppearanceCleanup)
    end

    if runtime.AppearanceSyncCleanup then
        pcall(runtime.AppearanceSyncCleanup)
    end
    if runtime.DestroyOutfitBrowser then
        pcall(runtime.DestroyOutfitBrowser)
    end

    if runtime.BodySelectorGui then
        pcall(function() runtime.BodySelectorGui:Destroy() end)
        runtime.BodySelectorGui = nil
    end

    if runtime.AppearanceStudioGui then
        if runtime.AppearanceStudio and runtime.AppearanceStudio.BaseAvatarTemplate then
            pcall(function() runtime.AppearanceStudio.BaseAvatarTemplate:Destroy() end)
        end
        pcall(function() runtime.AppearanceStudioGui:Destroy() end)
        runtime.AppearanceStudioGui = nil
        runtime.AppearanceStudio = nil
    end

    if runtime.StartupGui then
        pcall(function() runtime.StartupGui:Destroy() end)
        runtime.StartupGui = nil
    end

    if runtime.NotificationGui then
        pcall(function() runtime.NotificationGui:Destroy() end)
        runtime.NotificationGui = nil
    end

    if runtime.ScreenGui then
        pcall(function() runtime.ScreenGui:Destroy() end)
        runtime.ScreenGui = nil
    end
end

runtimeEnv.__ILUNX_RUNTIME = runtime

runtime.TeamCorpseCache = setmetatable({}, {__mode = "k"})

runtime.DeathEffectAlliedCharacters = setmetatable({}, {__mode = "k"})
runtime.RecentRoundDeaths = {}
runtime.TeamCorpseGeneration = 0
runtime.TeamCorpseProtectionUntil = 0
runtime.TeamCorpseProtectionSerial = 0

runtime.ClearTeamCorpseCache = function()
    runtime.TeamCorpseGeneration = (runtime.TeamCorpseGeneration or 0) + 1
    runtime.TeamCorpseProtectionSerial = (runtime.TeamCorpseProtectionSerial or 0) + 1
    runtime.TeamCorpseProtectionUntil = 0
    runtime.TeamCorpseProtectionExemptUserId = nil
    runtime.CorpseProtectionProxy = nil

    for model, entry in pairs(runtime.TeamCorpseCache or {}) do
        if entry then
            for _, conn in ipairs(entry.Connections or {}) do
                pcall(function() conn:Disconnect() end)
            end

            for sound, volume in pairs(entry.MutedSounds or {}) do
                if sound and sound.Parent then
                    pcall(function() sound.Volume = volume end)
                end
            end
        end
        runtime.TeamCorpseCache[model] = nil
    end

    table.clear(runtime.RecentRoundDeaths)
end

local ROUND_CORPSE_BLOCK_CLASSES = {
    ParticleEmitter = true,
    Beam = true,
    Trail = true,
    Smoke = true,
    Fire = true,
    Sparkles = true,
    Highlight = true,
    Sound = true,
}

local ROUND_CORPSE_PART_PROPS = {"Color", "Material", "Transparency", "Reflectance", "Size"}
local ROUND_CORPSE_MESH_PROPS = {"MeshId", "TextureId", "Scale", "VertexColor"}
local ROUND_CORPSE_IMAGE_PROPS = {"Texture", "Transparency", "Color3"}

local function roundCorpseLooksLikeBody(model)
    if not model or not model:IsA("Model") or not model.Parent then return false end

    local bodyParts = 0
    local totalParts = 0
    for _, obj in ipairs(model:GetDescendants()) do
        if obj:IsA("BasePart") then
            totalParts += 1
            local n = string.lower(obj.Name)
            if n == "head" or n == "humanoidrootpart" or n == "torso"
                or n == "uppertorso" or n == "lowertorso"
                or string.find(n, "arm", 1, true)
                or string.find(n, "leg", 1, true)
                or string.find(n, "hand", 1, true)
                or string.find(n, "foot", 1, true) then
                bodyParts += 1
            end
        end
    end

    return bodyParts >= 3 and totalParts >= 4
end

local function roundCorpsePosition(model)
    if not model then return nil end
    local root = model:FindFirstChild("HumanoidRootPart", true)
        or model:FindFirstChild("UpperTorso", true)
        or model:FindFirstChild("Torso", true)
        or model:FindFirstChild("Head", true)

    if root and root:IsA("BasePart") then return root.Position end

    local ok, pivot = pcall(function() return model:GetPivot() end)
    return ok and pivot.Position or nil
end

runtime.RegisterTeamCorpse = function(model, userId)
    if not runtime.Alive or not model or not model:IsA("Model") or not model.Parent then
        return nil
    end

    userId = tonumber(userId)
    if not userId then return nil end

    local existing = runtime.TeamCorpseCache[model]
    if existing then
        existing.UserId = userId
        if tonumber(userId) ~= tonumber(runtime.TeamCorpseProtectionExemptUserId) then
            existing.ActiveUntil = math.max(
                existing.ActiveUntil or 0,
                runtime.TeamCorpseProtectionUntil or 0
            )
        end
        return existing
    end

    local entry = {
        Model = model,
        UserId = userId,
        Generation = runtime.TeamCorpseGeneration or 0,
        ActiveUntil = (
            tonumber(userId) ~= tonumber(runtime.TeamCorpseProtectionExemptUserId)
            and (runtime.TeamCorpseProtectionUntil or 0)
            or 0
        ),
        Parts = setmetatable({}, {__mode = "k"}),
        Meshes = setmetatable({}, {__mode = "k"}),
        Images = setmetatable({}, {__mode = "k"}),
        Sounds = setmetatable({}, {__mode = "k"}),
        MutedSounds = setmetatable({}, {__mode = "k"}),
        Restoring = setmetatable({}, {__mode = "k"}),
        Connections = {},
    }

    local function active()
        if not runtime.Alive
            or entry.Generation ~= (runtime.TeamCorpseGeneration or 0) then
            return false
        end

        local visual = runtime.CorpseProtectionProxy
        if visual and visual.Parent then return true end
        local globalUntil = runtime.TeamCorpseProtectionUntil or 0
        if tonumber(entry.UserId) == tonumber(runtime.TeamCorpseProtectionExemptUserId) then
            globalUntil = 0
        end

        return os.clock() <= math.max(entry.ActiveUntil or 0, globalUntil)
    end

    local function withRestoreLock(obj, fn)
        if entry.Restoring[obj] then return end
        entry.Restoring[obj] = true
        pcall(fn)
        entry.Restoring[obj] = nil
    end

    local function restorePart(part, data)
        if not active() or not part or not part.Parent or entry.Restoring[part] then return end
        withRestoreLock(part, function()
            part.Color = data.Color
            part.Material = data.Material
            part.Transparency = data.Transparency
            part.Reflectance = data.Reflectance
            part.Size = data.Size
            if part:IsA("MeshPart") and data.TextureID ~= nil then
                part.TextureID = data.TextureID
            end
        end)
    end

    local function restoreMesh(mesh, data)
        if not active() or not mesh or not mesh.Parent or entry.Restoring[mesh] then return end
        withRestoreLock(mesh, function()
            mesh.MeshId = data.MeshId
            mesh.TextureId = data.TextureId
            mesh.Scale = data.Scale
            mesh.VertexColor = data.VertexColor
        end)
    end

    local function restoreImage(obj, data)
        if not active() or not obj or not obj.Parent or entry.Restoring[obj] then return end
        withRestoreLock(obj, function()
            obj.Texture = data.Texture
            obj.Transparency = data.Transparency
            obj.Color3 = data.Color3
        end)
    end

    local function watchSound(sound)
        if not sound or not sound:IsA("Sound") or entry.Sounds[sound] ~= nil then return end

        local originalVolume = 1
        pcall(function() originalVolume = sound.Volume end)
        entry.Sounds[sound] = originalVolume

        if active() then
            local playing = false
            pcall(function() playing = sound.Playing or sound.IsPlaying end)
            if not playing then
                entry.MutedSounds[sound] = originalVolume
                pcall(function() sound.Volume = 0 end)
            end
        end

        entry.Connections[#entry.Connections + 1] = sound.Played:Connect(function()
            if not active() or not sound.Parent then return end

            if entry.MutedSounds[sound] == nil then
                entry.MutedSounds[sound] = entry.Sounds[sound] or originalVolume
            end

            pcall(function()
                sound.Volume = 0
                sound.Looped = false
                sound:Stop()
            end)
        end)

        entry.Connections[#entry.Connections + 1] =
            sound:GetPropertyChangedSignal("Volume"):Connect(function()
                if active() and sound.Parent and not entry.Restoring[sound] then
                    if entry.MutedSounds[sound] == nil then
                        entry.MutedSounds[sound] = entry.Sounds[sound] or originalVolume
                    end
                    if sound.Volume ~= 0 then
                        entry.Restoring[sound] = true
                        pcall(function() sound.Volume = 0 end)
                        entry.Restoring[sound] = nil
                    end
                end
            end)
    end

    local function capture(obj)
        if obj:IsA("BasePart") then
            if entry.Parts[obj] == nil then
                local data = {}
                pcall(function()
                    data.Color = obj.Color
                    data.Material = obj.Material
                    data.Transparency = obj.Transparency
                    data.Reflectance = obj.Reflectance
                    data.Size = obj.Size
                    if obj:IsA("MeshPart") then data.TextureID = obj.TextureID end
                end)
                entry.Parts[obj] = data

                for _, prop in ipairs(ROUND_CORPSE_PART_PROPS) do
                    entry.Connections[#entry.Connections + 1] =
                        obj:GetPropertyChangedSignal(prop):Connect(function()
                            restorePart(obj, data)
                        end)
                end
                if obj:IsA("MeshPart") then
                    entry.Connections[#entry.Connections + 1] =
                        obj:GetPropertyChangedSignal("TextureID"):Connect(function()
                            restorePart(obj, data)
                        end)
                end
            end

        elseif obj:IsA("SpecialMesh") then
            if entry.Meshes[obj] == nil then
                local data = {}
                pcall(function()
                    data.MeshId = obj.MeshId
                    data.TextureId = obj.TextureId
                    data.Scale = obj.Scale
                    data.VertexColor = obj.VertexColor
                end)
                entry.Meshes[obj] = data

                for _, prop in ipairs(ROUND_CORPSE_MESH_PROPS) do
                    entry.Connections[#entry.Connections + 1] =
                        obj:GetPropertyChangedSignal(prop):Connect(function()
                            restoreMesh(obj, data)
                        end)
                end
            end

        elseif obj:IsA("Decal") or obj:IsA("Texture") then
            if entry.Images[obj] == nil then
                local data = {}
                pcall(function()
                    data.Texture = obj.Texture
                    data.Transparency = obj.Transparency
                    data.Color3 = obj.Color3
                end)
                entry.Images[obj] = data

                for _, prop in ipairs(ROUND_CORPSE_IMAGE_PROPS) do
                    entry.Connections[#entry.Connections + 1] =
                        obj:GetPropertyChangedSignal(prop):Connect(function()
                            restoreImage(obj, data)
                        end)
                end
            end

        elseif obj:IsA("Sound") then
            watchSound(obj)
        end
    end

    for _, obj in ipairs(model:GetDescendants()) do
        capture(obj)
    end

    entry.Connections[#entry.Connections + 1] = model.DescendantAdded:Connect(function(obj)
        if not runtime.Alive or not obj or not obj.Parent then return end

        if active() and ROUND_CORPSE_BLOCK_CLASSES[obj.ClassName] then
            if obj:IsA("Sound") then
                pcall(function()
                    obj.Volume = 0
                    obj.Looped = false
                    obj:Stop()
                end)
            end
            pcall(function() obj:Destroy() end)
            return
        end

        capture(obj)
    end)

    entry.Connections[#entry.Connections + 1] = model.AncestryChanged:Connect(function(_, parent)
        if parent == nil then
            for _, conn in ipairs(entry.Connections) do
                pcall(function() conn:Disconnect() end)
            end

            for sound, volume in pairs(entry.MutedSounds) do
                if sound and sound.Parent then
                    pcall(function() sound.Volume = volume end)
                end
            end

            runtime.TeamCorpseCache[model] = nil
        end
    end)

    runtime.TeamCorpseCache[model] = entry
    return entry
end

runtime.NoteRoundDeath = function(targetPlayer, character, deathPosition)
    if not runtime.Alive or not targetPlayer or targetPlayer == player then return end

    if character and character.Parent then
        runtime.RegisterTeamCorpse(character, targetPlayer.UserId)
    end

    local list = runtime.RecentRoundDeaths
    local now = os.clock()
    local write = 1

    for i = 1, #list do
        local item = list[i]
        if item and now - (item.At or 0) <= 1.60 then
            list[write] = item
            write += 1
        end
    end
    for i = #list, write, -1 do list[i] = nil end

    list[#list + 1] = {
        Player = targetPlayer,
        UserId = targetPlayer.UserId,
        Character = character,
        Position = deathPosition or roundCorpsePosition(character),
        At = now,
    }
end

runtime.TryCacheRoundCorpse = function(model)
    if not runtime.Alive or not model or not model:IsA("Model") or not model.Parent then
        return nil
    end

    local cached = runtime.TeamCorpseCache[model]
    if cached then return cached end
    if model:GetAttribute("XeroDeathVisualProxy") == true then return nil end

    local hum = model:FindFirstChildOfClass("Humanoid")
    if hum and hum.Health > 0 then return nil end
    if not model:FindFirstChild("Head") then return nil end
    if not roundCorpseLooksLikeBody(model) then return nil end

    local okAttrs, attrs = pcall(function() return model:GetAttributes() end)
    if okAttrs and type(attrs) == "table" then
        for key, value in pairs(attrs) do
            local k = string.lower(tostring(key))
            if k == "userid" or k == "playerid" or k == "ownerid" then
                local userId = tonumber(value)
                if userId and Players:GetPlayerByUserId(userId) then
                    return runtime.RegisterTeamCorpse(model, userId)
                end
            end
        end
    end

    local modelName = string.lower(tostring(model.Name))
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= player then
            local username = string.lower(tostring(p.Name))
            local display = string.lower(tostring(p.DisplayName))
            if modelName == username then
                return runtime.RegisterTeamCorpse(model, p.UserId)
            end
        end
    end

    return runtime.RegisterTeamCorpse(model, 0)
end

runtime.ArmRoundCorpseProtection = function(duration, exemptUserId)
    duration = math.max(0.25, tonumber(duration) or 2.70)
    exemptUserId = tonumber(exemptUserId)

    local now = os.clock()
    local untilAt = now + duration
    runtime.TeamCorpseProtectionUntil = math.max(
        runtime.TeamCorpseProtectionUntil or 0,
        untilAt
    )
    runtime.TeamCorpseProtectionSerial = (runtime.TeamCorpseProtectionSerial or 0) + 1
    runtime.TeamCorpseProtectionExemptUserId = exemptUserId
    local serial = runtime.TeamCorpseProtectionSerial

    for model, entry in pairs(runtime.TeamCorpseCache or {}) do
        if model and model.Parent and entry
            and entry.Generation == (runtime.TeamCorpseGeneration or 0)
            and (not exemptUserId or tonumber(entry.UserId) ~= exemptUserId) then

            entry.ActiveUntil = math.max(entry.ActiveUntil or 0, untilAt)

            for sound, originalVolume in pairs(entry.Sounds) do
                if sound and sound.Parent then
                    local playing = false
                    pcall(function() playing = sound.Playing or sound.IsPlaying end)
                    if not playing then
                        if entry.MutedSounds[sound] == nil then
                            entry.MutedSounds[sound] = originalVolume
                        end
                        pcall(function() sound.Volume = 0 end)
                    end
                end
            end
        end
    end

    local function releaseProtection()
        if not runtime.Alive then return end
        if serial ~= runtime.TeamCorpseProtectionSerial then return end
        local visual = runtime.CorpseProtectionProxy
        if visual and visual.Parent then
            task.delay(.50, releaseProtection)
            return
        end

        if serial ~= runtime.TeamCorpseProtectionSerial then return end
        if os.clock() < (runtime.TeamCorpseProtectionUntil or 0) then return end

        runtime.TeamCorpseProtectionUntil = 0
        runtime.TeamCorpseProtectionExemptUserId = nil

        for model, entry in pairs(runtime.TeamCorpseCache or {}) do
            if model and model.Parent and entry then
                entry.ActiveUntil = 0
                for sound, volume in pairs(entry.MutedSounds) do
                    if sound and sound.Parent then
                        pcall(function() sound.Volume = volume end)
                    end
                    entry.MutedSounds[sound] = nil
                end
            end
        end
    end
    task.delay(duration + .06, releaseProtection)
end

function AstraRequest(ruta)
    local req = (syn and syn.request) or (http and http.request) or http_request or request
    if req then
        local success, response = pcall(function()
            return req({
                Url = "https://hub.onyx-scripts.com" .. ruta,
                Method = "GET",
                Headers = {
                    ["Astra-Auth"] = "OnyxHub!",
                    ["User-Agent"] = "Roblox/iLunXHub"
                }
            })
        end)
        if success and response then return response.Body end
    end
    return nil
end

