local function xeroColorToConfig(color)
    if typeof(color) ~= "Color3" then return nil end
    return {
        R = math.floor(color.R * 255 + 0.5),
        G = math.floor(color.G * 255 + 0.5),
        B = math.floor(color.B * 255 + 0.5),
    }
end

local function xeroColorFromConfig(value, fallback)
    if typeof(value) == "Color3" then return value end
    if type(value) ~= "table" then return fallback end
    local r, g, b = tonumber(value.R), tonumber(value.G), tonumber(value.B)
    if not r or not g or not b then return fallback end

    if r <= 1 and g <= 1 and b <= 1 then
        return Color3.new(math.clamp(r, 0, 1), math.clamp(g, 0, 1), math.clamp(b, 0, 1))
    end
    return Color3.fromRGB(
        math.clamp(math.floor(r + 0.5), 0, 255),
        math.clamp(math.floor(g + 0.5), 0, 255),
        math.clamp(math.floor(b + 0.5), 0, 255)
    )
end

local function xeroBindColorpickerVisual(picker, colorGetter)
    if type(picker) ~= "table" or picker.__XeroColorVisualBound then return picker end
    picker.__XeroColorVisualBound = true

    local originalApplyTheme = picker.ApplyTheme
    if type(originalApplyTheme) == "function" then
        picker.ApplyTheme = function(self, ...)
            originalApplyTheme(self, ...)
            local okColor, selectedColor = pcall(colorGetter)
            if okColor and typeof(selectedColor) == "Color3" and type(self.Set) == "function" then

                pcall(function() self:Set(selectedColor, true) end)
            end
        end
    end

    picker.RefreshXeroColor = function(self)
        local okColor, selectedColor = pcall(colorGetter)
        if okColor and typeof(selectedColor) == "Color3" and type(self.Set) == "function" then
            pcall(function() self:Set(selectedColor, true) end)
        end
    end
    return picker
end

local function xeroRefreshKnownColorpickers()
    local items = {
        {xeroBasePicker, function() return XeroPersonalization.BaseColor end},
        {xeroAccentPicker, function() return XeroPersonalization.AccentColor end},
        {xeroTextPicker, function() return XeroPersonalization.TextColor end},
        {xeroGradientAPicker, function() return XeroPersonalization.GradientColorA end},
        {xeroGradientBPicker, function() return XeroPersonalization.GradientColorB end},
        {UIElements and UIElements.ColEsp, function() return espColor end},
    }
    for _, item in ipairs(items) do
        local picker, getter = item[1], item[2]
        if type(picker) == "table" then
            if type(picker.RefreshXeroColor) == "function" then
                pcall(function() picker:RefreshXeroColor() end)
            elseif type(picker.Set) == "function" then
                local okColor, color = pcall(getter)
                if okColor and typeof(color) == "Color3" then
                    pcall(function() picker:Set(color, true) end)
                end
            end
        end
    end
end

local function xeroSerializePersonalization()
    return {
        BackgroundURL = tostring(XeroPersonalization.BackgroundURL or ""),
        BackgroundActive = XeroPersonalization.BackgroundActive == true,
        ColorsActive = XeroPersonalization.ColorsActive == true,
        BackgroundOpacity = tonumber(XeroPersonalization.BackgroundOpacity) or 94,
        BackgroundShade = tonumber(XeroPersonalization.BackgroundShade) or 36,
        BaseColor = xeroColorToConfig(XeroPersonalization.BaseColor),
        AccentColor = xeroColorToConfig(XeroPersonalization.AccentColor),
        TextColor = xeroColorToConfig(XeroPersonalization.TextColor),
        GradientActive = XeroPersonalization.GradientActive == true,
        GradientColorA = xeroColorToConfig(XeroPersonalization.GradientColorA),
        GradientColorB = xeroColorToConfig(XeroPersonalization.GradientColorB),
        GradientRotation = tonumber(XeroPersonalization.GradientRotation) or 45,
    }
end

