local function xeroLoadPersonalization(data)
    if type(data) ~= "table" then return end

    XeroPersonalization.BackgroundURL = tostring(data.BackgroundURL or "")
    XeroPersonalization.BackgroundOpacity = math.clamp(tonumber(data.BackgroundOpacity) or 94, 0, 100)
    XeroPersonalization.BackgroundShade = math.clamp(tonumber(data.BackgroundShade) or 36, 0, 80)
    XeroPersonalization.BaseColor = xeroColorFromConfig(data.BaseColor, XeroPersonalization.BaseColor)
    XeroPersonalization.AccentColor = xeroColorFromConfig(data.AccentColor, XeroPersonalization.AccentColor)
    XeroPersonalization.TextColor = xeroColorFromConfig(data.TextColor, XeroPersonalization.TextColor)
    XeroPersonalization.GradientColorA = xeroColorFromConfig(data.GradientColorA, XeroPersonalization.GradientColorA)
    XeroPersonalization.GradientColorB = xeroColorFromConfig(data.GradientColorB, XeroPersonalization.GradientColorB)
    XeroPersonalization.GradientRotation = math.clamp(tonumber(data.GradientRotation) or 45, 0, 360)
    XeroPersonalization.GradientActive = data.GradientActive == true
    XeroPersonalization.ColorsActive = data.ColorsActive == true
    XeroPersonalization.BackgroundActive = data.BackgroundActive == true

    pcall(function() if xeroBackgroundInput.Set then xeroBackgroundInput:Set(XeroPersonalization.BackgroundURL) end end)
    pcall(function() xeroBasePicker:Set(XeroPersonalization.BaseColor, true) end)
    pcall(function() xeroAccentPicker:Set(XeroPersonalization.AccentColor, true) end)
    pcall(function() xeroTextPicker:Set(XeroPersonalization.TextColor, true) end)
    pcall(function() if xeroGradientToggle and xeroGradientToggle.Set then xeroGradientToggle:Set(XeroPersonalization.GradientActive) end end)
    pcall(function() if xeroGradientAPicker then xeroGradientAPicker:Set(XeroPersonalization.GradientColorA, true) end end)
    pcall(function() if xeroGradientBPicker then xeroGradientBPicker:Set(XeroPersonalization.GradientColorB, true) end end)
    pcall(function() if xeroGradientRotationSlider and xeroGradientRotationSlider.Set then xeroGradientRotationSlider:Set(XeroPersonalization.GradientRotation) end end)

    if XeroPersonalization.ColorsActive and Window.SetCustomColors then
        Window:SetCustomColors({
            Base = XeroPersonalization.BaseColor,
            Accent = XeroPersonalization.AccentColor,
            Text = XeroPersonalization.TextColor,
        }, true)
        if XeroPersonalization.GradientActive and Window.SetCustomGradient then
            Window:SetCustomGradient({
                ColorA = XeroPersonalization.GradientColorA,
                ColorB = XeroPersonalization.GradientColorB,
                Rotation = XeroPersonalization.GradientRotation,
            }, true)
        elseif Window.ResetCustomGradient then
            Window:ResetCustomGradient(true)
        end
        xeroRefreshKnownColorpickers()
    end

    if XeroPersonalization.BackgroundActive
        and XeroPersonalization.BackgroundURL ~= ""
        and Window.SetCustomBackground then
        task.spawn(function()
            local okBackground = Window:SetCustomBackground(XeroPersonalization.BackgroundURL, true)
            if okBackground then
                Window:SetCustomBackgroundOpacity(XeroPersonalization.BackgroundOpacity)
                Window:SetCustomBackgroundShade(XeroPersonalization.BackgroundShade)
            else
                XeroPersonalization.BackgroundActive = false
            end
        end)
    end
end

for _, tab in pairs(Tabs) do
    pcall(function()
        local originalToggle = tab.Toggle
        if type(originalToggle) == "function" then
            tab.Toggle = function(self, options)
                options = options or {}
                local originalCallback = options.Callback
                local title = tostring(options.Title or "Función")
                local ready = false

                options.Callback = function(state, ...)
                    local serialBefore = runtime.NotificationSerial or 0
                    if originalCallback then originalCallback(state, ...) end

                    if ready and not runtime.SuppressNotifications
                        and (runtime.NotificationSerial or 0) == serialBefore then
                        local enabled = state == true
                        sendNotification(
                            title .. (enabled and " activado" or " desactivado"),
                            {
                                title = "XeroHub · Ajuste",
                                icon = enabled and "✓" or "–",
                                accent = enabled and Color3.fromHex("#78D98B") or Color3.fromHex("#8E8E93"),
                                key = "toggle:" .. title,
                            }
                        )
                    end
                end

                local toggle = originalToggle(self, options)
                task.defer(function() ready = true end)
                return toggle
            end
        end
    end)
end

 do
local state = {Desired = false, Selected = "Frostbite", Generation = 0, Syncing = false}
local choices = {"1x1x1x1Effect", "Batstorm", "BlackheartEffect", "BlackholeEffect", "BloodmoonEffect", "BlueFire", "BlueSmoke", "BunnyBoys", "CandyCane", "ClanEmblemEffect", "CloverMadness", "DefaultEffect", "DragonBlossom", "DreamwalkerEffect", "DuskRoseEffect", "Egged", "Eggsplosion", "Featherlight", "FireEffect", "Freeze", "Frostbite", "Ghosted", "Gifted", "GothEffect", "GrassEffect", "GreenIce", "Heartache", "HeartbreakerEffect", "HexaKill", "KitsuneEffect", "LightningStrike", "LoveExplosion", "MagicSparksEffect", "MoneyMaker", "NiceHat", "PhoenixEffect", "PineappleEffect", "PortalEffect", "PurpleFire", "PurpleGrass", "PurpleIce", "PurpleSmoke", "RedFire", "RedIce", "RedNature", "RedSmoke", "RocketEffect", "SakuraEffect", "SandEffect", "SantaClaus", "ShadowcrestEffect", "SlimeEffect", "SmokeEffect", "SnowMan", "SpiderEffect", "SpiritOverload", "SplashEffect", "StarwingEffect", "Sunburn", "YellowFire", "YellowIce", "YellowSmoke"}
local dropdown, toggle
local XERO_DFX_PACKED = [==[

]==]
local XERO_DFX_KEY = "XeroKev_DFX_v3_2026"
local XERO_DFX_FACTORY

local createEngine = function(host)
    local bridge = (getgenv and getgenv()) or _G
    bridge.__XERO_DFX_RUNTIME = runtime
    bridge.__XERO_DFX_RUNSERVICE = RunService
    bridge.__XERO_DFX_CONTENTPROVIDER = ContentProvider

    if not XERO_DFX_FACTORY then

        local packedText = XERO_DFX_PACKED:gsub("%s+", "")

        local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local decodeMap = {}
        for i = 1, #alphabet do
            decodeMap[alphabet:sub(i, i)] = i - 1
        end

        local out = {}
        local outIndex = 0
        local byteIndex = 0
        local keyLength = #XERO_DFX_KEY

        local function emit(value)
            byteIndex += 1
            outIndex += 1
            local keyByte = XERO_DFX_KEY:byte(((byteIndex - 1) % keyLength) + 1)
            out[outIndex] = string.char(bit32.bxor(value, keyByte))
        end

        for i = 1, #packedText, 4 do
            local ca = packedText:sub(i, i)
            local cb = packedText:sub(i + 1, i + 1)
            local cc = packedText:sub(i + 2, i + 2)
            local cd = packedText:sub(i + 3, i + 3)

            local a = decodeMap[ca] or 0
            local b = decodeMap[cb] or 0
            local c = cc ~= "=" and decodeMap[cc] or nil
            local d = cd ~= "=" and decodeMap[cd] or nil

            local packed = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
            emit(math.floor(packed / 65536) % 256)
            if c ~= nil then emit(math.floor(packed / 256) % 256) end
            if d ~= nil then emit(packed % 256) end
        end

        packedText = nil
        local source = table.concat(out)
        table.clear(out)

        local chunk, compileError = loadstring(source)
        source = nil
        if not chunk then
            error(" " .. tostring(compileError), 0)
        end

        local okFactory, factory = pcall(chunk)
        if not okFactory then
            error(" " .. tostring(factory), 0)
        end
        if type(factory) ~= "function" then
            error("", 0)
        end

        XERO_DFX_FACTORY = factory
    end

    local okEngine, result = pcall(XERO_DFX_FACTORY, host)
    if not okEngine then
        error("[DFX ENGINE] " .. tostring(result), 0)
    end
    return result
end
local function notify(message)
    if runtime.Alive then sendNotification(message, {title = "XeroHub · Efectos", key = "death-effects"}) end
end

local function syncEffectControls(enabled, refreshChoices)
    state.Syncing = true

    if refreshChoices and dropdown then
        pcall(function()
            if type(dropdown.Refresh) == "function" then
                dropdown:Refresh(choices)
            end
        end)
    end

    if dropdown then
        pcall(function()
            if type(dropdown.Set) == "function" then
                dropdown:Set(state.Selected)
            elseif type(dropdown.Select) == "function" then
                dropdown:Select(state.Selected)
            end
        end)
    end

    if toggle then
        pcall(function()
            toggle:Set(enabled == true)
        end)
    end

    state.Syncing = false
end

local function stop()
    state.Generation += 1
    state.Desired = false
    if state.API then pcall(state.API.Destroy); state.API = nil end
    if state.Cleanup then pcall(state.Cleanup); state.Cleanup = nil end
end
local function setEnabled(value)
    if not value then stop(); return end
    if state.Desired then return end
    state.Desired = true
    state.Generation += 1
    local generation = state.Generation
    local function alive() return runtime.Alive and state.Desired and generation == state.Generation end
    notify("Preparando efectos; se activarán cuando termine la carga.")
    task.spawn(function()
        local ownedCleanup
        local ok, result = pcall(function()
            local api = createEngine({Alive = alive, RegisterCleanup = function(cleanup)
                ownedCleanup = cleanup
                if alive() then state.Cleanup = cleanup end
            end})
            if not alive() then api.Destroy(); return end

            while alive() do
                local name = state.Selected
                local ready, err = api.Select(name)
                if not ready then error(err) end
                if name == state.Selected then break end
            end
            if not alive() then api.Destroy(); return end
            api.Enable()
            state.API = api
            return api
        end)
        if not alive() then if ownedCleanup then pcall(ownedCleanup) end; return end
        if not ok then
            stop()
            syncEffectControls(false, false)
            local shortError = tostring(result)
            if #shortError > 190 then shortError = shortError:sub(1, 190) .. "…" end
            notify("No se pudieron cargar los efectos · " .. shortError)
            warn("[XeroHub Efectos] " .. tostring(result))
            return
        end
        if result then
            choices = result.Effects

            syncEffectControls(state.Desired, true)
            notify("Efectos listos · " .. state.Selected)
        end
    end)
end
local function selectEffect(value)
    if state.Syncing then return end
    local name = type(value) == "table" and value[1] or value
    if not table.find(choices, name) then return end
    state.Selected = name
    if not state.API or state.Selecting then return end
    state.Selecting = true
    task.spawn(function()
        local api = state.API
        while api and api == state.API and state.Desired do
            local selected = state.Selected
            local ok, ready = pcall(api.Select, selected)
            if not ok or not ready then
                notify("No se pudo preparar ese efecto; se conserva el anterior.")
                break
            end
            if selected == state.Selected then break end
        end
        state.Selecting = false
    end)
end
Tabs.Efectos:Paragraph({Title = "Efectos de muerte", Desc = "Elige un efecto para tus eliminaciones."})
dropdown = Tabs.Efectos:Dropdown({Title = "Efecto", Values = choices, Value = state.Selected, Callback = selectEffect})
toggle = Tabs.Efectos:Toggle({Title = "Cambiar efecto de muerte", Desc = "Aplica el efecto seleccionado a tus eliminaciones.", Value = false, Callback = function(value)
    if not state.Syncing then setEnabled(value == true) end
end})
runtime.DeathEffectsArm = function(character, tool)
    if state.API then return state.API.Arm(character, tool) end
    return false
end
runtime.DeathEffectsCleanup = stop
runtime.SerializeDeathEffectsConfig = function()
    return {Activado = state.Desired, Seleccionado = state.Selected}
end
runtime.LoadDeathEffectsConfig = function(config)
    if type(config) ~= "table" then return end

    stop()

    local savedSelected = tostring(config.Seleccionado or "")
    if savedSelected ~= "" then
        state.Selected = savedSelected
    end

    local enabled = config.Activado == true

    syncEffectControls(enabled, false)

    setEnabled(enabled)
end
end

