local function onRelevantSoundAdded(object)
    if not runtime.RegisterSoundInstance(object) then return end
    if soundState.Enabled or soundState.MuteGunshot then watchCandidateSound(object) end
    if killSoundState.Enabled then watchCandidateKillSound(object) end
end

runtime.SoundWatcherConnections = {}
local function soundWatchersWanted()
    return soundState.Enabled or soundState.DesiredEnabled or soundState.MuteGunshot
        or killSoundState.Enabled or killSoundState.DesiredEnabled
end

local function stopSoundWatchers()
    local list = runtime.SoundWatcherConnections
    for i = #list, 1, -1 do
        pcall(function() list[i]:Disconnect() end)
        list[i] = nil
    end

    runtime.SoundRegistryPrimed = false
end

local function startSoundWatchers()
    local list = runtime.SoundWatcherConnections
    if list[1] and list[1].Connected then return end
    stopSoundWatchers()
    list[#list + 1] = workspace.DescendantAdded:Connect(onRelevantSoundAdded)
    list[#list + 1] = SoundService.DescendantAdded:Connect(onRelevantSoundAdded)
    local backpack = player:FindFirstChildOfClass("Backpack")
    if backpack then
        list[#list + 1] = backpack.DescendantAdded:Connect(onRelevantSoundAdded)
    end
end

runtime.RefreshSoundWatchers = function()
    if not runtime.Alive then
        stopSoundWatchers()
        return
    end
    if soundWatchersWanted() then startSoundWatchers() else stopSoundWatchers() end
end

runtime.RefreshSoundWatchers()

runtime.SoundCleanup = function()
    soundState.LoadToken = soundState.LoadToken + 1
    soundState.PreviewToken = soundState.PreviewToken + 1
    killSoundState.LoadToken = killSoundState.LoadToken + 1
    disableSoundChanger(false)
    disableGunshotMute(false)
    disableKillSoundChanger(false)
    stopSoundWatchers()
    if soundState.PreviewSound then
        pcall(function() soundState.PreviewSound:Destroy() end)
        soundState.PreviewSound = nil
    end
end

refreshSoundCatalog(false)
end

do
Tabs.Texturas = MainSection:Tab({Title = "Texturas Armas", Icon = "palette"})

local textureEnv = (getgenv and getgenv()) or _G
local textureAssetLoader = getcustomasset
    or getsynasset
    or (syn and (syn.getcustomasset or syn.getsynasset))

local TextureCatalogCore = {
    CACHE_FOLDER = "XeroHub/Textures",
    URLS = {
        knife = "https://api.github.com/repos/xero-scripts-repo/xero-scripts/contents/textures/default/knife?ref=main",
        gun = "https://api.github.com/repos/xero-scripts-repo/xero-scripts/contents/textures/default/gun?ref=main",
    },
    OriginalTexture = {
        knife = "121944805",
        gun = "91723031",
    },
    OriginalMesh = {
        knife = "121944778",
        gun = "10881397417",
    },
    WeaponTitles = {
        knife = "Cuchillo default",
        gun = "Pistola default",
    }
}

local textureState = {
    CurrentWeaponKey = "knife",
    Catalog = {knife = {}, gun = {}},
    ByLabel = {knife = {}, gun = {}},
    SelectedLabel = {knife = nil, gun = nil},
    CustomIds = {knife = "", gun = ""},
    Active = {
        knife = {Enabled = false, Source = nil, Asset = nil, Label = nil, Entry = nil},
        gun = {Enabled = false, Source = nil, Asset = nil, Label = nil, Entry = nil},
    },
    Saved = setmetatable({}, {__mode = "k"}),
    Connections = {},
    SyncingWeaponDropdown = false,
    SyncingSkinDropdown = false,
    PendingConfig = nil,
}
runtime.TextureState = textureState

local textureWeaponDropdown
local textureSkinDropdown
local textureCustomInput

local function textureAssetDigits(value)
    return tostring(value or ""):match("(%d+)") or ""
end

local function textureTrim(value)
    return tostring(value or ""):match("^%s*(.-)%s*$") or ""
end

local function texturePrettyName(fileName)
    local name = tostring(fileName or "")
    name = name:gsub("%.[%w]+$", "")
    name = name:gsub("%s*%(%d+%)%s*$", "")
    name = name:gsub("[_%-]+", " "):gsub("%s+", " ")
    name = textureTrim(name)
    name = name:gsub("%S+", function(word)
        return word:sub(1, 1):upper() .. word:sub(2):lower()
    end)
    return name ~= "" and name or "Skin sin nombre"
end

local function textureEntryKey(entry)
    entry = type(entry) == "table" and entry or {}
    return tostring(entry.name or "") .. "@" .. tostring(entry.sha or "")
end

local function textureCachePath(weaponKey, entry)
    entry = type(entry) == "table" and entry or {}
    local extension = tostring(entry.extension or "png")
    local token = tostring(entry.sha or ""):gsub("[^%w]", ""):sub(1, 12)
    if token == "" then
        token = tostring(entry.name or "skin"):gsub("[^%w]", "_"):sub(1, 40)
    end
    return TextureCatalogCore.CACHE_FOLDER .. "/" .. tostring(weaponKey) .. "_" .. token .. "." .. extension
end

local function textureRequest(url)
    local req = (syn and syn.request) or (http and http.request) or http_request or request
    if req then
        local ok, response = pcall(function()
            return req({
                Url = url,
                Method = "GET",
                Headers = {
                    ["User-Agent"] = "XeroHub-Textures/1.0",
                    ["Accept"] = "application/vnd.github+json",
                },
            })
        end)
        if ok and type(response) == "table" then
            local status = tonumber(response.StatusCode or response.Status or 0) or 0
            local body = response.Body or response.body
            if status == 0 and response.Success == true then status = 200 end
            if type(body) == "string" and status > 0 then return body, status end
        end
    end

    local ok, body = pcall(function() return game:HttpGet(url) end)
    if ok and type(body) == "string" then return body, 200 end
    return nil, 0
end

local function ensureTextureFolder()
    if type(makefolder) ~= "function" then return false end
    if not isfolder or not isfolder("XeroHub") then pcall(makefolder, "XeroHub") end
    if not isfolder or not isfolder(TextureCatalogCore.CACHE_FOLDER) then
        pcall(makefolder, TextureCatalogCore.CACHE_FOLDER)
    end
    if type(isfolder) == "function" then
        local ok, exists = pcall(isfolder, TextureCatalogCore.CACHE_FOLDER)
        return ok and exists == true
    end
    return true
end

local function parseTextureCatalog(body)
    if type(body) ~= "string" or body == "" then return {} end
    local ok, decoded = pcall(function() return HttpService:JSONDecode(body) end)
    if not ok or type(decoded) ~= "table" then return {} end

    local result, seenLabels = {}, {}
    for _, item in ipairs(decoded) do
        if type(item) == "table" and item.type == "file"
            and type(item.download_url) == "string" and item.download_url ~= "" then
            local extension = string.lower(tostring(item.name or ""):match("%.([%w]+)$") or "")
            if extension == "png" or extension == "jpg" or extension == "jpeg" or extension == "webp" then
                local label = texturePrettyName(item.name)
                seenLabels[label] = (seenLabels[label] or 0) + 1
                table.insert(result, {
                    name = tostring(item.name),
                    label = label,
                    sha = tostring(item.sha or ""),
                    url = item.download_url,
                    extension = extension,
                })
            end
        end
    end

    for _, entry in ipairs(result) do
        entry._sortLabel = string.lower(entry.label)
        entry._sortName = string.lower(entry.name)
    end

    table.sort(result, function(a, b)
        if a._sortLabel == b._sortLabel then return a._sortName < b._sortName end
        return a._sortLabel < b._sortLabel
    end)

    local seen = {}
    for _, entry in ipairs(result) do
        local key = entry._sortLabel
        if (seenLabels[entry.label] or 0) > 1 then
            seen[key] = (seen[key] or 0) + 1
            entry.label = entry.label .. " [" .. tostring(seen[key]) .. "]"
        end
        entry._sortLabel = nil
        entry._sortName = nil
    end

    return result
end

local function downloadTextureAsset(weaponKey, entry)
    if type(textureAssetLoader) ~= "function" or type(writefile) ~= "function" then
        return nil, "unsupported"
    end

    local hasFolders = ensureTextureFolder()
    local localPath = textureCachePath(weaponKey, entry)
    if not hasFolders then
        localPath = "XeroHub_Texture_" .. tostring(weaponKey) .. "_" .. tostring(entry.name or "skin"):gsub("[^%w]", "_")
    end

    local validCache = false
    if type(isfile) == "function" and type(readfile) == "function" and isfile(localPath) then
        local ok, cached = pcall(readfile, localPath)
        validCache = ok and type(cached) == "string" and #cached > 64
    end

    if not validCache then
        local body, status = textureRequest(entry.url)
        if not body or status < 200 or status >= 300 or #body < 64 then
            return nil, "download_failed"
        end
        local ok = pcall(writefile, localPath, body)
        if not ok then return nil, "write_failed" end
    end

    local ok, assetId = pcall(textureAssetLoader, localPath)
    if not ok or type(assetId) ~= "string" or assetId == "" then
        return nil, "asset_failed"
    end
    return assetId, localPath
end

local function fetchTextureCatalog(weaponKey)
    local url = TextureCatalogCore.URLS[weaponKey]
    local body, status = textureRequest(url)
    if status >= 200 and status < 300 then
        return parseTextureCatalog(body)
    end
    return {}
end

local function setTextureWeaponDropdownSilently(label)
    if not textureWeaponDropdown then return end
    textureState.SyncingWeaponDropdown = true
    pcall(function() textureWeaponDropdown:Select(label) end)
    textureState.SyncingWeaponDropdown = false
end

local function setTextureSkinDropdownSilently(label)
    if not textureSkinDropdown then return end
    textureState.SyncingSkinDropdown = true
    pcall(function() textureSkinDropdown:Select(label) end)
    textureState.SyncingSkinDropdown = false
end

local function updateSkinDropdownForWeapon(weaponKey)
    local values, byLabel = {}, textureState.ByLabel[weaponKey]
    for _, entry in ipairs(textureState.Catalog[weaponKey]) do
        values[#values + 1] = entry.label
    end
    if #values == 0 then values = {"Sin skins disponibles"} end

    local selected = textureState.SelectedLabel[weaponKey]
    if not byLabel[selected] then selected = values[1] end
    textureState.SelectedLabel[weaponKey] = byLabel[selected] and selected or nil

    if textureSkinDropdown then
        pcall(function()
            textureSkinDropdown:Refresh(values)
            if textureState.SelectedLabel[weaponKey] then
                setTextureSkinDropdownSilently(textureState.SelectedLabel[weaponKey])
            else
                setTextureSkinDropdownSilently(values[1])
            end
        end)
    end
end

local function saveTextureOriginal(obj, weaponKey)
    if not obj then return end
    local saved = textureState.Saved[obj]
    if saved and saved.Key == weaponKey then return end

    if obj:IsA("SpecialMesh") then
        textureState.Saved[obj] = {Class = "SpecialMesh", Key = weaponKey, TextureId = obj.TextureId}
    elseif obj:IsA("MeshPart") then
        textureState.Saved[obj] = {Class = "MeshPart", Key = weaponKey, TextureID = obj.TextureID}
    elseif obj:IsA("SurfaceAppearance") then
        textureState.Saved[obj] = {Class = "SurfaceAppearance", Key = weaponKey, ColorMap = obj.ColorMap}
    end
end

local function restoreTextureWeapon(weaponKey, activeAsset)
    local originalTexture = TextureCatalogCore.OriginalTexture[weaponKey]
    local canonicalOriginal = originalTexture and ("rbxassetid://" .. tostring(originalTexture)) or nil

    for obj, data in pairs(textureState.Saved) do
        if data and data.Key == weaponKey then
            if obj and obj.Parent then
                pcall(function()
                    if data.Class == "SpecialMesh" then
                        local value = data.TextureId or ""

                        if canonicalOriginal and activeAsset and value == activeAsset then
                            value = canonicalOriginal
                        end
                        obj.TextureId = value
                    elseif data.Class == "MeshPart" then
                        local value = data.TextureID or ""
                        if canonicalOriginal and activeAsset and value == activeAsset then
                            value = canonicalOriginal
                        end
                        obj.TextureID = value
                    elseif data.Class == "SurfaceAppearance" then
                        local value = data.ColorMap or ""
                        if canonicalOriginal and activeAsset and value == activeAsset then
                            value = canonicalOriginal
                        end
                        obj.ColorMap = value
                    end
                end)
            end
            textureState.Saved[obj] = nil
        end
    end
end

local function textureShouldTreatAsKnife(obj)
    local name = string.lower(tostring(obj.Name or ""))
    if name:find("knife", 1, true) or name:find("blade", 1, true) then return true end
    local anc = obj:FindFirstAncestorOfClass("Tool")
    if anc then
        local tname = string.lower(anc.Name)
        if tname:find("knife", 1, true) or tname:find("blade", 1, true) then return true end
    end
    return obj:FindFirstAncestor("KnifePartsFolder") ~= nil
end

local function textureShouldTreatAsGun(obj)
    local name = string.lower(tostring(obj.Name or ""))
    if name:find("gun", 1, true) or name:find("pistol", 1, true) or name:find("revolver", 1, true) then return true end
    local anc = obj:FindFirstAncestorOfClass("Tool")
    if anc then
        local tname = string.lower(anc.Name)
        if tname:find("gun", 1, true) or tname:find("pistol", 1, true) or tname:find("revolver", 1, true) then return true end
    end
    return obj:FindFirstAncestor("GunPartsFolder") ~= nil
end

local function isDefaultWeaponObject(weaponKey, obj)
    if not obj then return false end
    if weaponKey == "knife" and textureShouldTreatAsKnife(obj) then return true end
    if weaponKey == "gun" and textureShouldTreatAsGun(obj) then return true end

    if obj:IsA("SpecialMesh") then
        local tex = textureAssetDigits(obj.TextureId)
        local mesh = textureAssetDigits(obj.MeshId)
        return tex == TextureCatalogCore.OriginalTexture[weaponKey]
            or mesh == TextureCatalogCore.OriginalMesh[weaponKey]
    elseif obj:IsA("MeshPart") then
        local tex = textureAssetDigits(obj.TextureID)
        local mesh = textureAssetDigits(obj.MeshId)
        return tex == TextureCatalogCore.OriginalTexture[weaponKey]
            or mesh == TextureCatalogCore.OriginalMesh[weaponKey]
    elseif obj:IsA("SurfaceAppearance") then
        if weaponKey == "knife" then return textureShouldTreatAsKnife(obj) end
        if weaponKey == "gun" then return textureShouldTreatAsGun(obj) end
    end
    return false
end

local function restoreTextureCopiesWithActiveAsset(weaponKey, activeAsset)
    if type(activeAsset) ~= "string" or activeAsset == "" then return 0 end

    local originalTexture = TextureCatalogCore.OriginalTexture[weaponKey]
    if not originalTexture then return 0 end
    local canonicalOriginal = "rbxassetid://" .. tostring(originalTexture)
    local restored = 0

    local function restoreOne(obj)
        if not obj or not obj.Parent or not isDefaultWeaponObject(weaponKey, obj) then return end

        pcall(function()
            if obj:IsA("SpecialMesh") and obj.TextureId == activeAsset then
                obj.TextureId = canonicalOriginal
                restored = restored + 1
            elseif obj:IsA("MeshPart") and obj.TextureID == activeAsset then
                obj.TextureID = canonicalOriginal
                restored = restored + 1
            elseif obj:IsA("SurfaceAppearance") and obj.ColorMap == activeAsset then
                obj.ColorMap = canonicalOriginal
                restored = restored + 1
            end
        end)
    end

    local function restoreRoot(root)
        if not root then return end
        restoreOne(root)
        for _, obj in ipairs(root:GetDescendants()) do
            restoreOne(obj)
        end
    end

    restoreRoot(player.Character)
    restoreRoot(player:FindFirstChild("Backpack"))

    return restored
end

local function applyTextureToObject(weaponKey, obj)
    local active = textureState.Active[weaponKey]
    if not active or not active.Enabled or not active.Asset or not obj then return false end
    if not isDefaultWeaponObject(weaponKey, obj) then return false end

    local changed = false
    pcall(function()
        if obj:IsA("SpecialMesh") then
            saveTextureOriginal(obj, weaponKey)
            if obj.TextureId ~= active.Asset then
                obj.TextureId = active.Asset
                changed = true
            end
        elseif obj:IsA("MeshPart") then
            saveTextureOriginal(obj, weaponKey)
            if obj.TextureID ~= active.Asset then
                obj.TextureID = active.Asset
                changed = true
            end
        elseif obj:IsA("SurfaceAppearance") then
            saveTextureOriginal(obj, weaponKey)
            if obj.ColorMap ~= active.Asset then
                obj.ColorMap = active.Asset
                changed = true
            end
        end
    end)
    return changed
end

local function processTextureRoot(root)
    if not root then return end
    for weaponKey, active in pairs(textureState.Active) do
        if active.Enabled then
            applyTextureToObject(weaponKey, root)
        end
    end
    for _, d in ipairs(root:GetDescendants()) do
        for weaponKey, active in pairs(textureState.Active) do
            if active.Enabled then
                applyTextureToObject(weaponKey, d)
            end
        end
    end
end

local function scanTextureAll()
    local character = player.Character
    if character then processTextureRoot(character) end
    local backpack = player:FindFirstChild("Backpack")
    if backpack then processTextureRoot(backpack) end
end

local function disconnectTextureConnections()
    for i = #textureState.Connections, 1, -1 do
        pcall(function() textureState.Connections[i]:Disconnect() end)
        textureState.Connections[i] = nil
    end
end

local function trackTextureConnection(conn)
    if conn then textureState.Connections[#textureState.Connections + 1] = conn end
    return conn
end

local function anyTextureActive()
    return textureState.Active.knife.Enabled or textureState.Active.gun.Enabled
end

local function rebuildTextureHooks()
    disconnectTextureConnections()
    if not anyTextureActive() then return end

    local function onAdded(obj)

        if not obj then return end
        local className = obj.ClassName
        if className ~= "SpecialMesh" and className ~= "MeshPart"
            and className ~= "SurfaceAppearance" then
            return
        end

        task.defer(function()
            if not runtime.Alive or not anyTextureActive() or not obj.Parent then return end
            for weaponKey, active in pairs(textureState.Active) do
                if active.Enabled then applyTextureToObject(weaponKey, obj) end
            end
        end)
    end

    trackTextureConnection(player.CharacterAdded:Connect(function(char)
        task.wait(0.15)
        processTextureRoot(char)
        trackTextureConnection(char.DescendantAdded:Connect(onAdded))
    end))

    local char = player.Character
    if char then trackTextureConnection(char.DescendantAdded:Connect(onAdded)) end

    local backpack = player:FindFirstChild("Backpack")
    if backpack then trackTextureConnection(backpack.DescendantAdded:Connect(onAdded)) end
    trackTextureConnection(player.ChildAdded:Connect(function(obj)
        if obj.Name == "Backpack" then
            task.wait(0.05)
            trackTextureConnection(obj.DescendantAdded:Connect(onAdded))
            processTextureRoot(obj)
        end
    end))
end

local function applyTextureNotification(label)
    showBottomMessage("Skin aplicada: " .. tostring(label or "Personalizada"), {
        title = "XeroHub · Texturas",
        key = "textures:apply:" .. tostring(label or "custom"),
    })
end

local function activateTextureWeapon(weaponKey, source, payload, announce)
    local asset, label, entry
    if source == "github" then
        entry = payload
        if type(entry) ~= "table" then return false end
        asset = textureEnv["XERO_TEXTURE_ASSET_" .. weaponKey .. "_" .. textureEntryKey(entry)]
        if type(asset) ~= "string" or asset == "" then
            local loadedAsset = select(1, downloadTextureAsset(weaponKey, entry))
            if type(loadedAsset) ~= "string" or loadedAsset == "" then
                return false
            end
            asset = loadedAsset
            textureEnv["XERO_TEXTURE_ASSET_" .. weaponKey .. "_" .. textureEntryKey(entry)] = asset
        end
        label = entry.label
        textureState.SelectedLabel[weaponKey] = entry.label
    elseif source == "custom" then
        local digits = textureAssetDigits(payload)
        if digits == "" then return false end
        asset = "rbxassetid://" .. digits
        label = "Personalizada"
        textureState.CustomIds[weaponKey] = digits
    else
        return false
    end

    local previousAsset = textureState.Active[weaponKey] and textureState.Active[weaponKey].Asset or nil
    restoreTextureWeapon(weaponKey, previousAsset)
    restoreTextureCopiesWithActiveAsset(weaponKey, previousAsset)
    textureState.Active[weaponKey] = {
        Enabled = true,
        Source = source,
        Asset = asset,
        Label = label,
        Entry = entry,
    }

    scanTextureAll()
    rebuildTextureHooks()
    if announce then applyTextureNotification(label) end
    return true
end

local function restoreTextureSelected(weaponKey, announce)
    local previousAsset = textureState.Active[weaponKey] and textureState.Active[weaponKey].Asset or nil
    textureState.Active[weaponKey] = {Enabled = false, Source = nil, Asset = nil, Label = nil, Entry = nil}
    restoreTextureWeapon(weaponKey, previousAsset)
    restoreTextureCopiesWithActiveAsset(weaponKey, previousAsset)
    rebuildTextureHooks()
    if announce then
        showBottomMessage("Textura original restaurada.", {title = "XeroHub · Texturas", key = "textures:restore:" .. weaponKey})
    end
end

local function refreshTextureCatalog(weaponKey, updateUiAfter)
    task.spawn(function()
        local catalog = fetchTextureCatalog(weaponKey)
        textureState.Catalog[weaponKey] = catalog
        textureState.ByLabel[weaponKey] = {}
        for _, entry in ipairs(catalog) do
            textureState.ByLabel[weaponKey][entry.label] = entry
        end
        if updateUiAfter and textureState.CurrentWeaponKey == weaponKey then
            updateSkinDropdownForWeapon(weaponKey)
        end

        local pending = textureState.PendingConfig
        if pending and textureState.Catalog.knife and textureState.Catalog.gun then
            local knifeDone = pending._knifeDone
            local gunDone = pending._gunDone
            if weaponKey == "knife" then pending._knifeDone = true else pending._gunDone = true end
            if (weaponKey == "knife" and gunDone) or (weaponKey == "gun" and knifeDone) or (pending._knifeDone and pending._gunDone) then
                textureState.PendingConfig = nil
                runtime.LoadTextureConfig(pending)
            end
        end
    end)
end

function runtime.SerializeTextureConfig()
    return {
        CurrentWeapon = textureState.CurrentWeaponKey,
        Knife = {
            Seleccionado = textureState.SelectedLabel.knife,
            Activo = textureState.Active.knife.Enabled == true,
            Fuente = textureState.Active.knife.Source,
            Archivo = textureState.Active.knife.Entry and textureState.Active.knife.Entry.name or nil,
            CustomId = textureState.CustomIds.knife,
        },
        Gun = {
            Seleccionado = textureState.SelectedLabel.gun,
            Activo = textureState.Active.gun.Enabled == true,
            Fuente = textureState.Active.gun.Source,
            Archivo = textureState.Active.gun.Entry and textureState.Active.gun.Entry.name or nil,
            CustomId = textureState.CustomIds.gun,
        },
    }
end

local function findTextureEntryByConfig(weaponKey, section)
    if type(section) ~= "table" then return nil end
    local fileName = type(section.Archivo) == "string" and section.Archivo or nil
    if fileName and fileName ~= "" then
        for _, entry in ipairs(textureState.Catalog[weaponKey]) do
            if entry.name == fileName then return entry end
        end
    end
    local label = type(section.Seleccionado) == "string" and section.Seleccionado or nil
    if label and label ~= "" then return textureState.ByLabel[weaponKey][label] end
    return nil
end

function runtime.LoadTextureConfig(data)
    if type(data) ~= "table" then return false end

    if #textureState.Catalog.knife == 0 or #textureState.Catalog.gun == 0 then
        textureState.PendingConfig = data
        return true
    end

    local currentWeapon = tostring(data.CurrentWeapon or "knife")
    if currentWeapon ~= "knife" and currentWeapon ~= "gun" then currentWeapon = "knife" end
    textureState.CurrentWeaponKey = currentWeapon
    setTextureWeaponDropdownSilently(TextureCatalogCore.WeaponTitles[currentWeapon])

    local knife = type(data.Knife) == "table" and data.Knife or {}
    local gun = type(data.Gun) == "table" and data.Gun or {}

    local knifeEntry = findTextureEntryByConfig("knife", knife)
    if knifeEntry then
        textureState.SelectedLabel.knife = knifeEntry.label
    end
    local gunEntry = findTextureEntryByConfig("gun", gun)
    if gunEntry then
        textureState.SelectedLabel.gun = gunEntry.label
    end

    textureState.CustomIds.knife = textureAssetDigits(knife.CustomId)
    textureState.CustomIds.gun = textureAssetDigits(gun.CustomId)

    updateSkinDropdownForWeapon(currentWeapon)

    restoreTextureSelected("knife", false)
    restoreTextureSelected("gun", false)

    if knife.Activo == true then
        if knife.Fuente == "custom" and textureState.CustomIds.knife ~= "" then
            activateTextureWeapon("knife", "custom", textureState.CustomIds.knife, false)
        elseif knifeEntry then
            activateTextureWeapon("knife", "github", knifeEntry, false)
        end
    end

    if gun.Activo == true then
        if gun.Fuente == "custom" and textureState.CustomIds.gun ~= "" then
            activateTextureWeapon("gun", "custom", textureState.CustomIds.gun, false)
        elseif gunEntry then
            activateTextureWeapon("gun", "github", gunEntry, false)
        end
    end

    return true
end

