end
local fpsLabel = metric("FPS", 10)
local pingLabel = metric("PING / ms", 102)
local showStatsEnabled = false
local fpsFrames, statsElapsed = 0, 0
local statsRenderConnection = nil

local function stopStatsRenderConnection()
    if not statsRenderConnection then return end
    pcall(function() statsRenderConnection:Disconnect() end)
    statsRenderConnection = nil
    runtime.PruneConnections()
end

local function startStatsRenderConnection()
    if statsRenderConnection then
        local connected = false
        pcall(function() connected = statsRenderConnection.Connected == true end)
        if connected then return end
        statsRenderConnection = nil
    end

    statsRenderConnection = runtime.Track(RunService.RenderStepped:Connect(function(deltaTime)
        fpsFrames = fpsFrames + 1
        statsElapsed = statsElapsed + deltaTime
        if statsElapsed < 1 then return end

        fpsLabel.Text = tostring(math.floor(fpsFrames / statsElapsed + 0.5))
        local ok, pingValue = pcall(function()
            return math.floor(Stats.Network.ServerStatsItem["Data Ping"]:GetValue())
        end)
        pingLabel.Text = ok and tostring(pingValue) or "--"
        fpsFrames, statsElapsed = 0, 0
    end))
end

Tabs.Inicio:Toggle({
    Title = "Mostrar FPS y Ping",
    Callback = function(Value)
        showStatsEnabled = Value == true
        statsContainer.Visible = showStatsEnabled
        fpsFrames, statsElapsed = 0, 0
        fpsLabel.Text, pingLabel.Text = "--", "--"
        if showStatsEnabled then
            startStatsRenderConnection()
        else
            stopStatsRenderConnection()
        end
    end,
})
end

local fpsBoostEnabled = false
local FPS_SCAN_BUDGET = 0.0035
local FPS_SCAN_CHECK_EVERY = 64

runtime.FPSBoost = {
    Cache = {},
    LightingState = nil,
    TerrainState = nil,
    RenderingState = nil,
    Connections = {},
    ScanGeneration = 0,
    PendingQueue = {},
    PendingHead = 1,
    PendingTail = 0,
    PendingSet = setmetatable({}, {__mode = "k"}),
    PendingWorkerGeneration = nil,
    Stats = {Parts = 0, Meshes = 0, Visuals = 0, Failures = 0},
}

function runtime.FPSBoostIsPlayerDescendant(v)
    local node = v
    while node and node ~= workspace do
        if node:IsA("Model") then
            local ok, owner = pcall(function()
                return Players:GetPlayerFromCharacter(node)
            end)
            if ok and owner then return true end
        end
        node = node.Parent
    end
    return false
end

function runtime.FPSBoostRemember(data, v, prop)
    data.Values = data.Values or {}
    if data.Values[prop] ~= nil then return end

    local ok, value = pcall(function()
        return v[prop]
    end)
    if ok then
        data.Values[prop] = {Value = value}
    else
        data.Values[prop] = false
    end
end

function runtime.FPSBoostSet(data, v, prop, value)
    runtime.FPSBoostRemember(data, v, prop)
    local ok = pcall(function()
        v[prop] = value
    end)
    if not ok then
        runtime.FPSBoost.Stats.Failures = (runtime.FPSBoost.Stats.Failures or 0) + 1
    end
    return ok
end

function runtime.ApplyLowGraphics(v, force)
    if not fpsBoostEnabled or not v or not v.Parent then return end
    if runtime.FPSBoostIsPlayerDescendant(v) then return end

    local className = v.ClassName
    local supported =
        v:IsA("BasePart")
        or className == "Decal" or className == "Texture"
        or className == "SpecialMesh" or className == "SurfaceAppearance"
        or className == "PointLight" or className == "SpotLight" or className == "SurfaceLight"
        or className == "BloomEffect" or className == "BlurEffect"
        or className == "ColorCorrectionEffect" or className == "ColorGradingEffect"
        or className == "DepthOfFieldEffect" or className == "SunRaysEffect"
        or className == "ParticleEmitter" or className == "Trail" or className == "Beam"
        or className == "Smoke" or className == "Fire" or className == "Sparkles"
        or className == "Highlight"
        or className == "SurfaceGui" or className == "BillboardGui"
        or className == "Atmosphere" or className == "Clouds"

    if not supported then return end

    local cache = runtime.FPSBoost.Cache
    local data = cache[v]
    if not data then
        data = {Values = {}}
        cache[v] = data
    elseif not force then
        return
    end

    if v:IsA("BasePart") then
        runtime.FPSBoostSet(data, v, "Material", Enum.Material.Plastic)
        runtime.FPSBoostSet(data, v, "MaterialVariant", "")
        runtime.FPSBoostSet(data, v, "Reflectance", 0)
        runtime.FPSBoostSet(data, v, "CastShadow", false)

        if not data.CountedPart then
            data.CountedPart = true
            runtime.FPSBoost.Stats.Parts = (runtime.FPSBoost.Stats.Parts or 0) + 1
        end

        if className == "MeshPart" then
            runtime.FPSBoostSet(data, v, "TextureID", "")
            runtime.FPSBoostSet(data, v, "RenderFidelity", Enum.RenderFidelity.Performance)
            if not data.CountedMesh then
                data.CountedMesh = true
                runtime.FPSBoost.Stats.Meshes = (runtime.FPSBoost.Stats.Meshes or 0) + 1
            end
        elseif className == "UnionOperation" then
            runtime.FPSBoostSet(data, v, "UsePartColor", true)
            runtime.FPSBoostSet(data, v, "RenderFidelity", Enum.RenderFidelity.Performance)
        end

    elseif className == "SpecialMesh" then
        runtime.FPSBoostSet(data, v, "TextureId", "")

    elseif className == "SurfaceAppearance" then
        if data.Parent == nil then data.Parent = v.Parent end
        local ok = pcall(function() v.Parent = nil end)
        if not ok then
            runtime.FPSBoostSet(data, v, "ColorMap", "")
            runtime.FPSBoostSet(data, v, "MetalnessMap", "")
            runtime.FPSBoostSet(data, v, "NormalMap", "")
            runtime.FPSBoostSet(data, v, "RoughnessMap", "")
        end

    elseif className == "Decal" or className == "Texture" then
        runtime.FPSBoostSet(data, v, "Transparency", 1)

    elseif className == "PointLight" or className == "SpotLight" or className == "SurfaceLight"
        or className == "BloomEffect" or className == "BlurEffect"
        or className == "ColorCorrectionEffect" or className == "ColorGradingEffect"
        or className == "DepthOfFieldEffect" or className == "SunRaysEffect"
        or className == "ParticleEmitter" or className == "Trail" or className == "Beam"
        or className == "Smoke" or className == "Fire" or className == "Sparkles"
        or className == "Highlight"
        or className == "SurfaceGui" or className == "BillboardGui" then

        runtime.FPSBoostSet(data, v, "Enabled", false)

    elseif className == "Atmosphere" then
        runtime.FPSBoostSet(data, v, "Density", 0)
        runtime.FPSBoostSet(data, v, "Haze", 0)
        runtime.FPSBoostSet(data, v, "Glare", 0)

    elseif className == "Clouds" then
        runtime.FPSBoostSet(data, v, "Cover", 0)
        runtime.FPSBoostSet(data, v, "Density", 0)
    end

    if not data.CountedVisual and not v:IsA("BasePart") then
        data.CountedVisual = true
        runtime.FPSBoost.Stats.Visuals = (runtime.FPSBoost.Stats.Visuals or 0) + 1
    end
end

function runtime.FPSBoostScan(root, force, generation)
    local ok, descendants = pcall(function()
        return root:GetDescendants()
    end)
    if not ok or type(descendants) ~= "table" then return end

    local nextYieldAt = os.clock() + FPS_SCAN_BUDGET
    for i = 1, #descendants do
        if not fpsBoostEnabled or generation ~= runtime.FPSBoost.ScanGeneration then break end
        pcall(runtime.ApplyLowGraphics, descendants[i], force == true)

        if i % FPS_SCAN_CHECK_EVERY == 0 and os.clock() >= nextYieldAt then
            task.wait()
            nextYieldAt = os.clock() + FPS_SCAN_BUDGET
        end
    end
    table.clear(descendants)
end

function runtime.FPSBoostResetPendingQueue()
    local state = runtime.FPSBoost
    table.clear(state.PendingQueue)
    state.PendingHead = 1
    state.PendingTail = 0
    state.PendingSet = setmetatable({}, {__mode = "k"})
    state.PendingWorkerGeneration = nil
end

function runtime.FPSBoostEnsurePendingWorker()
    local state = runtime.FPSBoost
    local generation = state.ScanGeneration
    if state.PendingWorkerGeneration == generation then return end
    if state.PendingHead > state.PendingTail then return end

    state.PendingWorkerGeneration = generation
    task.spawn(function()
        while runtime.Alive and fpsBoostEnabled and generation == state.ScanGeneration do
            if state.PendingHead > state.PendingTail then break end

            local deadline = os.clock() + FPS_SCAN_BUDGET
            local processed = 0
            while state.PendingHead <= state.PendingTail do
                local head = state.PendingHead
                local object = state.PendingQueue[head]
                state.PendingQueue[head] = nil
                state.PendingHead = head + 1
                processed += 1

                if object then
                    state.PendingSet[object] = nil
                    if object.Parent then
                        pcall(runtime.ApplyLowGraphics, object, false)
                    end
                end

                if processed % FPS_SCAN_CHECK_EVERY == 0 and os.clock() >= deadline then
                    break
                end
            end

            if state.PendingHead > state.PendingTail then
                table.clear(state.PendingQueue)
                state.PendingHead = 1
                state.PendingTail = 0
                break
            end

            RunService.Heartbeat:Wait()
        end

        if state.PendingWorkerGeneration == generation then
            state.PendingWorkerGeneration = nil
            if fpsBoostEnabled and generation == state.ScanGeneration
                and state.PendingHead <= state.PendingTail then
                runtime.FPSBoostEnsurePendingWorker()
            end
        end
    end)
end

function runtime.QueueFPSBoostObject(v)
    if not fpsBoostEnabled or not v or not v.Parent then return end

    local state = runtime.FPSBoost
    if state.PendingSet[v] then return end
    state.PendingSet[v] = true
    state.PendingTail += 1
    state.PendingQueue[state.PendingTail] = v
    runtime.FPSBoostEnsurePendingWorker()
end

function runtime.FPSBoostCaptureAndSet(container, instance, prop, value)
    container.Values = container.Values or {}
    if container.Values[prop] == nil then
        local ok, current = pcall(function() return instance[prop] end)
        container.Values[prop] = ok and {Value = current} or false
    end
    pcall(function() instance[prop] = value end)
end

function runtime.FPSBoostRestoreState(container, instance)
    if not container or not container.Values or not instance then return end
    for prop, saved in pairs(container.Values) do
        if type(saved) == "table" then
            pcall(function() instance[prop] = saved.Value end)
        end
    end
end

function runtime.RestoreLowGraphics()
    for v, data in pairs(runtime.FPSBoost.Cache) do
        if v then
            if data.Values then
                for prop, saved in pairs(data.Values) do
                    if type(saved) == "table" then
                        pcall(function() v[prop] = saved.Value end)
                    end
                end
            end
            if data.Parent and data.Parent.Parent then
                pcall(function() v.Parent = data.Parent end)
            end
        end
    end
    table.clear(runtime.FPSBoost.Cache)
end

function runtime.FPSBoostDisconnect()
    for i = #runtime.FPSBoost.Connections, 1, -1 do
        local connection = runtime.FPSBoost.Connections[i]
        pcall(function() connection:Disconnect() end)
        runtime.FPSBoost.Connections[i] = nil
    end
end

function runtime.FPSBoostVerify()
    local partsChecked, partsChanged = 0, 0
    local visualsChecked, visualsDisabled = 0, 0

    for v, data in pairs(runtime.FPSBoost.Cache) do
        if v and data then
            if data.CountedPart and v.Parent then
                partsChecked += 1
                local ok, material = pcall(function() return v.Material end)
                if ok and material == Enum.Material.Plastic then
                    partsChanged += 1
                end
            elseif data.CountedVisual then
                local enabledSaved = data.Values and data.Values.Enabled
                if enabledSaved ~= nil then
                    visualsChecked += 1
                    local ok, enabled = pcall(function() return v.Enabled end)
                    if ok and enabled == false then
                        visualsDisabled += 1
                    end
                end
            end
        end
    end

    return partsChanged, partsChecked, visualsDisabled, visualsChecked
end

function runtime.FPSBoostRestoreWorld()
    local Lighting = game:GetService("Lighting")
    local Terrain = workspace:FindFirstChildOfClass("Terrain")

    runtime.FPSBoostRestoreState(runtime.FPSBoost.LightingState, Lighting)
    if Terrain then
        runtime.FPSBoostRestoreState(runtime.FPSBoost.TerrainState, Terrain)
    end

    if runtime.FPSBoost.RenderingState and runtime.FPSBoost.RenderingState.QualityLevel ~= nil then
        pcall(function()
            settings().Rendering.QualityLevel = runtime.FPSBoost.RenderingState.QualityLevel
        end)
    end

    runtime.FPSBoost.LightingState = nil
    runtime.FPSBoost.TerrainState = nil
    runtime.FPSBoost.RenderingState = nil
end

runtime.FPSBoostCleanup = function()
    fpsBoostEnabled = false
    runtime.FPSBoost.ScanGeneration = (runtime.FPSBoost.ScanGeneration or 0) + 1
    runtime.FPSBoostDisconnect()
    runtime.FPSBoostResetPendingQueue()
    runtime.RestoreLowGraphics()
    runtime.FPSBoostRestoreWorld()
end

UIElements.ToggleFPS = Tabs.Graficos:Toggle({
    Title = "FPS Boost",
    Desc = "Simplifica todo el mapa cargado, texturas, PBR, luces y efectos.",
    Value = false,
    Callback = function(state)
        if state and runtime.GraphicsCleanup then runtime.GraphicsCleanup() end

        if not state then
            runtime.FPSBoostCleanup()
            showBottomMessage("Gráficos originales restaurados.")
            return
        end

        fpsBoostEnabled = true
        runtime.FPSBoost.ScanGeneration = (runtime.FPSBoost.ScanGeneration or 0) + 1
        local generation = runtime.FPSBoost.ScanGeneration

        runtime.FPSBoostDisconnect()
        runtime.RestoreLowGraphics()
        runtime.FPSBoostRestoreWorld()
        runtime.FPSBoost.Stats = {Parts = 0, Meshes = 0, Visuals = 0, Failures = 0}

        local Lighting = game:GetService("Lighting")
        local Terrain = workspace:FindFirstChildOfClass("Terrain")

        runtime.FPSBoost.LightingState = {Values = {}}
        runtime.FPSBoostCaptureAndSet(runtime.FPSBoost.LightingState, Lighting, "GlobalShadows", false)
        runtime.FPSBoostCaptureAndSet(runtime.FPSBoost.LightingState, Lighting, "ShadowSoftness", 0)
        runtime.FPSBoostCaptureAndSet(runtime.FPSBoost.LightingState, Lighting, "EnvironmentDiffuseScale", 0)
        runtime.FPSBoostCaptureAndSet(runtime.FPSBoost.LightingState, Lighting, "EnvironmentSpecularScale", 0)
        runtime.FPSBoostCaptureAndSet(runtime.FPSBoost.LightingState, Lighting, "FogEnd", 9e9)

        if Terrain then
            runtime.FPSBoost.TerrainState = {Values = {}}
            runtime.FPSBoostCaptureAndSet(runtime.FPSBoost.TerrainState, Terrain, "WaterWaveSize", 0)
            runtime.FPSBoostCaptureAndSet(runtime.FPSBoost.TerrainState, Terrain, "WaterWaveSpeed", 0)
            runtime.FPSBoostCaptureAndSet(runtime.FPSBoost.TerrainState, Terrain, "WaterReflectance", 0)
            runtime.FPSBoostCaptureAndSet(runtime.FPSBoost.TerrainState, Terrain, "WaterTransparency", 1)
            runtime.FPSBoostCaptureAndSet(runtime.FPSBoost.TerrainState, Terrain, "Decoration", false)
        end

        runtime.FPSBoost.RenderingState = {}
        pcall(function()
            runtime.FPSBoost.RenderingState.QualityLevel = settings().Rendering.QualityLevel
            settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
        end)

        runtime.FPSBoostResetPendingQueue()
        runtime.FPSBoost.Connections[#runtime.FPSBoost.Connections + 1] =
            workspace.DescendantAdded:Connect(runtime.QueueFPSBoostObject)

        runtime.FPSBoost.Connections[#runtime.FPSBoost.Connections + 1] =
            Lighting.DescendantAdded:Connect(runtime.QueueFPSBoostObject)

        task.spawn(function()
            runtime.FPSBoostScan(workspace, false, generation)
            runtime.FPSBoostScan(Lighting, false, generation)

            task.wait(0.75)
            if fpsBoostEnabled and generation == runtime.FPSBoost.ScanGeneration then
                runtime.FPSBoostScan(workspace, true, generation)
                runtime.FPSBoostScan(Lighting, true, generation)
            end

            if fpsBoostEnabled and generation == runtime.FPSBoost.ScanGeneration then
                local s = runtime.FPSBoost.Stats
                local partsChanged, partsChecked, visualsDisabled, visualsChecked = runtime.FPSBoostVerify()
                showBottomMessage(string.format(
                    "FPS Boost: %d/%d partes cambiadas · %d meshes · %d/%d efectos apagados.",
                    partsChanged,
                    partsChecked,
                    s.Meshes or 0,
                    visualsDisabled,
                    visualsChecked
                ))
            end
        end)
    end
})

Tabs.Inicio:Button({
    Title = "Cambiar de Servidor",
    Callback = function()
        showBottomMessage("Buscando servidor vacío...")
        local TPS = game:GetService("TeleportService")
        local Api = "https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Asc&limit=100"

        task.spawn(function()
            local success, err = pcall(function()
                local req = request or http_request or (syn and syn.request)
                if req then
                    local res = req({Url = Api, Method = "GET"})
                    if res.StatusCode == 200 then
                        local data = HttpService:JSONDecode(res.Body)
                        local servers = {}
                        if data and data.data then for _, v in pairs(data.data) do if v.playing < v.maxPlayers and v.id ~= game.JobId then table.insert(servers, v.id) end end end
                        if #servers > 0 then
                            local randomServer = servers[math.random(1, #servers)]
                            showBottomMessage("¡Servidor encontrado!...")
                            TPS:TeleportToPlaceInstance(game.PlaceId, randomServer, player)
                        else showBottomMessage("No hay servidores vacíos disponibles.") end
                    else showBottomMessage("Error de conexión con el Proxy.") end
                else showBottomMessage("Tu ejecutor no soporta HTTP Requests.") end
            end)
            if not success then warn("Error en Server Hop:", err) end
        end)
    end,
})

