local forbiddenKeywords = {"knife", "cuchillo", "blade", "sword", "dagger", "kunai", "toy", "juguete", "balloon", "food", "drink", "pizza", "burger", "teddy", "combat", "punch", "fist", "wallet", "phone", "boombox", "radio"}
local weaponClassificationCache = setmetatable({}, {__mode = "k"})

local weaponHandleCache = setmetatable({}, {__mode = "k"})

local function getWeaponHandleCached(item)
    if not item or not item:IsA("Tool") then return nil end
    local cached = weaponHandleCache[item]
    if cached and cached.Parent == item then return cached end
    local handle = item:FindFirstChild("Handle")
    weaponHandleCache[item] = handle
    return handle
end

function esLaPistola(item)
    if not item:IsA("Tool") then return false end
    local cached = weaponClassificationCache[item]
    if cached ~= nil then return cached end

    if item:FindFirstChild("Throw") or item:FindFirstChild("KnifeClient") or item:FindFirstChild("KnifeServer") then
        weaponClassificationCache[item] = false
        return false
    end

    local n = string.lower(item.Name)
    for i = 1, #forbiddenKeywords do
        if string.find(n, forbiddenKeywords[i]) then
            weaponClassificationCache[item] = false
            return false
        end
    end

    weaponClassificationCache[item] = true
    return true
end

function obtenerPistola()
    local char = player.Character
    local backpack = player:FindFirstChild("Backpack")
    if char then for _, item in ipairs(char:GetChildren()) do if esLaPistola(item) then return item end end end
    if backpack then for _, item in ipairs(backpack:GetChildren()) do if esLaPistola(item) then return item end end end
    return nil
end

local isTeamLobby = false
local hasForceField = false

local function updateTeamCache()
    if player.Team then
        local tName = string.lower(player.Team.Name)
        if string.find(tName, "lobby") or string.find(tName, "spectat") or string.find(tName, "espectador") or string.find(tName, "menu") or string.find(tName, "dead") then
            isTeamLobby = true
        else
            isTeamLobby = false
        end
    else
        isTeamLobby = false
    end

    if isTeamLobby and runtime.RefreshAimHooks then
        runtime.RefreshAimHooks(false)
    end
end

runtime.Track(player:GetPropertyChangedSignal("Team"):Connect(updateTeamCache))
updateTeamCache()

runtime.BindForceFieldCache = function(char)
    if runtime.ForceFieldAddedConnection then
        pcall(function() runtime.ForceFieldAddedConnection:Disconnect() end)
        runtime.ForceFieldAddedConnection = nil
    end
    if runtime.ForceFieldRemovedConnection then
        pcall(function() runtime.ForceFieldRemovedConnection:Disconnect() end)
        runtime.ForceFieldRemovedConnection = nil
    end

    hasForceField = char and char:FindFirstChildOfClass("ForceField") ~= nil or false
    if not char then
        runtime.PruneConnections()
        return
    end

    runtime.ForceFieldAddedConnection = runtime.Track(char.ChildAdded:Connect(function(child)
        if child:IsA("ForceField") then
            hasForceField = true
            if runtime.RefreshAimHooks then runtime.RefreshAimHooks(false) end
        end
    end))
    runtime.ForceFieldRemovedConnection = runtime.Track(char.ChildRemoved:Connect(function(child)
        if child:IsA("ForceField") then
            hasForceField = false
            if runtime.RefreshAimHooks then task.defer(runtime.RefreshAimHooks) end
        end
    end))
    runtime.PruneConnections()
end

runtime.Track(player.CharacterAdded:Connect(function(char)
    runtime.BindForceFieldCache(char)
end))
runtime.BindForceFieldCache(player.Character)

function estaEnLobby()
    local char = player.Character
    if not char then return true end

    if hasForceField or isTeamLobby then return true end

    local hrp = char:FindFirstChild("HumanoidRootPart")
    if hrp then
        local myPos = hrp.Position
        for i = 1, #ZONAS_SEGURAS do
            local zona = ZONAS_SEGURAS[i]
            local delta = myPos - zona.Centro
            if delta:Dot(delta) <= zona.RadioSq then
                return true
            end
        end
    end

    return false
end

function runtime.IsCombatRound()
    local char = player.Character
    if not char or not char.Parent then return false end

    local humanoid = char:FindFirstChildOfClass("Humanoid")
    if not humanoid or humanoid.Health <= 0 then return false end

    local okLobby, lobbyResult = pcall(estaEnLobby)
    if not okLobby or lobbyResult == true then return false end

    return true
end

function ejecutarAccionMacro()

    if estaEnLobby() then return end

    local hayEnemigos = false
    for i = 1, #listaJugadores do
    local p = listaJugadores[i]
        if p ~= player then
            local pChar = p.Character
            if pChar and pChar:FindFirstChild("Humanoid") and pChar.Humanoid.Health > 0 then
                if player.Team == nil or p.Team == nil or player.Team ~= p.Team then
                    hayEnemigos = true
                    break
                end
            end
        end
    end

    if not hayEnemigos then return end

    local char = player.Character if not char then return end
    local hum = char:FindFirstChild("Humanoid") if not hum then return end
    local herramientaEnMano = char:FindFirstChildOfClass("Tool")
    if herramientaEnMano and not esLaPistola(herramientaEnMano) then return end

    local pistola = obtenerPistola()
    if not pistola then return end

    if runtime.QuickGunEquipEnabled and runtime.CancelQuickGunEquip then
        runtime.CancelQuickGunEquip(true)
    end
    if runtime.MacroBusy then return end
    runtime.MacroBusy = true

    task.spawn(function()
        pcall(function()
            hum:UnequipTools()
            task.wait()
            hum:EquipTool(pistola)

            task.wait(macroEquipDelay)

            if pistola.Parent == char then
                pistola:Activate()

                task.wait(macroShootDelay)

                pistola:Deactivate()
                hum:UnequipTools()
            end
        end)
        runtime.MacroBusy = false
    end)
end

local toquesPantalla = {}

runtime.Track(UserInputService.InputChanged:Connect(function(input, processed)
    if input.UserInputType == Enum.UserInputType.Touch and toquesPantalla[input] then
        if (toquesPantalla[input].posicion - input.Position).Magnitude > 10 then
            toquesPantalla = {}
        end
    end
end))

runtime.Track(UserInputService.InputBegan:Connect(function(input, processed)
    if processed or not macroActivo then return end

    if input.UserInputType == Enum.UserInputType.MouseButton1 then
        ejecutarAccionMacro()
    elseif input.UserInputType == Enum.UserInputType.Touch then
        local pos = input.Position
        local dzPos = deadZoneFrame.AbsolutePosition
        local dzSize = deadZoneFrame.AbsoluteSize
        local tocoZonaMuerta = (pos.X >= dzPos.X) and (pos.X <= dzPos.X + dzSize.X) and (pos.Y >= dzPos.Y) and (pos.Y <= dzPos.Y + dzSize.Y)

        if not tocoZonaMuerta then
            toquesPantalla[input] = {posicion = input.Position, tiempo = tick()}
        end
    end
end))

runtime.Track(UserInputService.InputEnded:Connect(function(input, processed)
    if not macroActivo then return end

    if input.UserInputType == Enum.UserInputType.Touch and toquesPantalla[input] then
        local datosToque = toquesPantalla[input]
        local posicionFinal = input.Position
        local distanciaMovida = (datosToque.posicion - posicionFinal).Magnitude
        local tiempoPresionado = tick() - datosToque.tiempo

        toquesPantalla[input] = nil

        if distanciaMovida < 10 and tiempoPresionado < 0.35 and tiempoPresionado > 0.03 then
            ejecutarAccionMacro()
        end
    end
end))

local TEAMMATE_MARKER_NAME = "TeammateIconPart"
local enemyCache = {}

local teamRoundState = {
    InRound = false,
    Generation = 0,
    MarkerSystemSeen = false,
    KnownTeammates = {},
    PendingExitAt = nil,
    EnteredAt = 0,
    LastCombatTrueAt = 0,
    SoloFallbackReadyAt = 0,
    TeammateLeftThisRound = false,
}
runtime.TeamRoundState = teamRoundState

local function clearTeamRoundMemory(inRound)
    local entering = inRound == true
    local now = os.clock()

    teamRoundState.Generation += 1
    teamRoundState.InRound = entering
    teamRoundState.MarkerSystemSeen = false
    teamRoundState.PendingExitAt = nil
    teamRoundState.TeammateLeftThisRound = false
    table.clear(teamRoundState.KnownTeammates)
    enemyCache = {}

    if entering then
        teamRoundState.EnteredAt = now
        teamRoundState.LastCombatTrueAt = now

        teamRoundState.SoloFallbackReadyAt = now + 1.15
    else
        teamRoundState.EnteredAt = 0
        teamRoundState.LastCombatTrueAt = 0
        teamRoundState.SoloFallbackReadyAt = 0
    end

    if runtime.ClearTeamCorpseCache then
        runtime.ClearTeamCorpseCache()
    end
end

local function syncTeamRoundState(inRoundOverride)
    local inRound = inRoundOverride
    if inRound == nil then
        inRound = false
        if runtime.IsCombatRound then
            local ok, result = pcall(runtime.IsCombatRound)
            inRound = ok and result == true
        end
    else
        inRound = inRound == true
    end

    local now = os.clock()

    if inRound then
        teamRoundState.PendingExitAt = nil
        teamRoundState.LastCombatTrueAt = now
        if not teamRoundState.InRound then
            clearTeamRoundMemory(true)
        end
        return true
    end

    if not teamRoundState.InRound then
        return false
    end

    local hardLobby = isTeamLobby == true
    if not hardLobby then
        local char = player.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if root then
            local pos = root.Position
            for i = 1, #ZONAS_SEGURAS do
                local zona = ZONAS_SEGURAS[i]
                local delta = pos - zona.Centro
                if delta:Dot(delta) <= zona.RadioSq then
                    hardLobby = true
                    break
                end
            end
        end
    end

    if hardLobby then
        clearTeamRoundMemory(false)
        return false
    end

    if not teamRoundState.PendingExitAt then
        teamRoundState.PendingExitAt = now
        return true
    end

    if now - teamRoundState.PendingExitAt >= 1.0 then
        clearTeamRoundMemory(false)
        return false
    end

    return true
end
runtime.SyncTeamRoundState = syncTeamRoundState

function updateMyTeam()
    enemyCache = {}
end

function updateEnemy(p)
    enemyCache[p] = nil
end

local function getTeammateMarker(targetPlayer)
    if not targetPlayer then return nil end
    local char = targetPlayer.Character
    if not char then return nil end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil end
    return hrp:FindFirstChild(TEAMMATE_MARKER_NAME)
end

local function rememberTeammate(targetPlayer)
    if not targetPlayer or targetPlayer == player then return false end
    teamRoundState.MarkerSystemSeen = true
    teamRoundState.KnownTeammates[targetPlayer.UserId] = true
    if targetPlayer.Character then
        runtime.DeathEffectAlliedCharacters[targetPlayer.Character] = true
    end
    enemyCache[targetPlayer] = false

    return true
end

local function rememberVisibleTeammates()
    local found = false
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= player and getTeammateMarker(p) then
            rememberTeammate(p)
            found = true
        end
    end
    return found
end

local function isRememberedTeammate(targetPlayer)
    return targetPlayer ~= nil
        and teamRoundState.KnownTeammates[targetPlayer.UserId] == true
end

local function teammateMarkerSystemActive()

    if teamRoundState.MarkerSystemSeen then return true end
    return rememberVisibleTeammates()
end

local function aliveCombatOthers(targetPlayer, context)
    if not targetPlayer or targetPlayer == player then return false, 0 end

    if context and context.NearbyCombatReady then
        return context.NearbyCombatPlayers[targetPlayer] == true, context.NearbyCombatCount or 0
    end

    local myChar = player.Character
    local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
    if not myRoot then return false, 0 end

    local count = 0
    local targetEligible = false
    local nearby = context and context.NearbyCombatPlayers or nil
    if nearby then table.clear(nearby) end

    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= player then
            local char = p.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local root = char and char:FindFirstChild("HumanoidRootPart")

            if char and hum and hum.Health > 0 and root
                and not char:FindFirstChildOfClass("ForceField") then

                local safe = false
                local pos = root.Position

                for i = 1, #ZONAS_SEGURAS do
                    local zona = ZONAS_SEGURAS[i]
                    local delta = pos - zona.Centro
                    if delta:Dot(delta) <= zona.RadioSq then
                        safe = true
                        break
                    end
                end

                if not safe then
                    local delta = root.Position - myRoot.Position
                    if delta:Dot(delta) <= 176400 then
                        count += 1
                        if nearby then nearby[p] = true end
                        if p == targetPlayer then targetEligible = true end
                    end
                end
            end
        end
    end

    if context then
        context.NearbyCombatCount = count
        context.NearbyCombatReady = true
        targetEligible = nearby[targetPlayer] == true
    end
    return targetEligible, count
end

local function fallbackEnemyRelation(targetPlayer, context)
    if player.Team ~= nil and targetPlayer.Team ~= nil then
        return player.Team ~= targetPlayer.Team
    end

    local pAttr = player:GetAttribute("Team") or player:GetAttribute("team")
    local tAttr = targetPlayer:GetAttribute("Team") or targetPlayer:GetAttribute("team")
    if pAttr ~= nil and tAttr ~= nil then
        return pAttr ~= tAttr
    end

    local myColor = player.TeamColor and player.TeamColor.Name or ""
    local theirColor = targetPlayer.TeamColor and targetPlayer.TeamColor.Name or ""
    local myColorUseful = myColor ~= "" and myColor ~= "White" and myColor ~= "Medium stone grey"
    local theirColorUseful = theirColor ~= "" and theirColor ~= "White" and theirColor ~= "Medium stone grey"
    if myColorUseful and theirColorUseful then
        return player.TeamColor ~= targetPlayer.TeamColor
    end

    local roundActive = context and context.RoundActive
    if roundActive == nil then roundActive = syncTeamRoundState() end
    if not roundActive then
        return false
    end

    local eligible, nearbyCount = aliveCombatOthers(targetPlayer, context)
    if not eligible then
        return false
    end

    if nearbyCount == 1 then
        return true
    end

    if not (context and context.MarkersScanned) then rememberVisibleTeammates() end
    if isRememberedTeammate(targetPlayer) then
        return false
    end
    if teamRoundState.MarkerSystemSeen then
        return true
    end

    if teamRoundState.TeammateLeftThisRound
        or os.clock() >= (teamRoundState.SoloFallbackReadyAt or math.huge) then
        return true
    end

    return false
end

