runtime.EnemyEventConnections = setmetatable({}, {__mode = "k"})

runtime.ClearEnemyPlayerEvents = function(p)
    local bundle = runtime.EnemyEventConnections[p]
    if not bundle then return end
    runtime.EnemyEventConnections[p] = nil
    for i = 1, #bundle do
        pcall(function() bundle[i]:Disconnect() end)
    end
end

function setupPlayerEvents(p)
    runtime.ClearEnemyPlayerEvents(p)

    local bundle = {}
    runtime.EnemyEventConnections[p] = bundle

    local function bind(connection)
        if connection then
            bundle[#bundle + 1] = connection
            runtime.Track(connection)
        end
        return connection
    end

    local boundRoots = setmetatable({}, {__mode = "k"})

    local function bindRoot(root)
        if not root or not root:IsA("BasePart") or boundRoots[root] then return end
        boundRoots[root] = true

        if root:FindFirstChild(TEAMMATE_MARKER_NAME) then
            rememberTeammate(p)
            updateMyTeam()
        end

        bind(root.ChildAdded:Connect(function(child)
            if child.Name == TEAMMATE_MARKER_NAME then
                rememberTeammate(p)

                updateMyTeam()
            end
        end))

        bind(root.ChildRemoved:Connect(function(child)
            if child.Name == TEAMMATE_MARKER_NAME then

                updateEnemy(p)
            end
        end))

        updateEnemy(p)
    end

    local function bindCharacter(char)
        updateEnemy(p)
        if not char then return end

        local root = char:FindFirstChild("HumanoidRootPart")
        if root then bindRoot(root) end

        bind(char.ChildAdded:Connect(function(child)
            if child.Name == "HumanoidRootPart" and child:IsA("BasePart") then
                bindRoot(child)
            end
        end))

        bind(char.ChildRemoved:Connect(function(child)
            if child.Name == "HumanoidRootPart" then

                updateEnemy(p)
            end
        end))
    end

    bind(p:GetPropertyChangedSignal("Team"):Connect(function() updateEnemy(p) end))
    bind(p:GetPropertyChangedSignal("TeamColor"):Connect(function() updateEnemy(p) end))
    bind(p:GetPropertyChangedSignal("Neutral"):Connect(function() updateEnemy(p) end))
    bind(p:GetAttributeChangedSignal("Team"):Connect(function() updateEnemy(p) end))
    bind(p:GetAttributeChangedSignal("team"):Connect(function() updateEnemy(p) end))
    bind(p.CharacterAdded:Connect(function(char)
        bindCharacter(char)
        task.defer(rememberVisibleTeammates)
    end))
    bind(p.CharacterRemoving:Connect(function()

        updateEnemy(p)
    end))

    bindCharacter(p.Character)
end

for _, p in ipairs(listaJugadores) do
    if p ~= player then setupPlayerEvents(p) end
end

runtime.Track(Players.PlayerAdded:Connect(function(p)
    setupPlayerEvents(p)
    updateMyTeam()
end))

runtime.Track(Players.PlayerRemoving:Connect(function(p)

    if teamRoundState.InRound
        and (teamRoundState.KnownTeammates[p.UserId] == true or getTeammateMarker(p) ~= nil) then
        teamRoundState.MarkerSystemSeen = true
        teamRoundState.TeammateLeftThisRound = true
    end

    runtime.ClearEnemyPlayerEvents(p)
    enemyCache[p] = nil

    teamRoundState.KnownTeammates[p.UserId] = nil
    runtime.PruneConnections()
end))

runtime.EnemyQueryContext = {
    RoundActive = nil,
    MarkersScanned = false,
    MarkerSystemActive = false,
    NearbyCombatReady = false,
    NearbyCombatCount = 0,
    NearbyCombatPlayers = {},
}

function runtime.PrepareEnemyQueryContext()
    local context = runtime.EnemyQueryContext
    context.RoundActive = teamCheckEnabled and syncTeamRoundState() or nil
    context.MarkersScanned = teamRoundState.MarkerSystemSeen == true
    context.MarkerSystemActive = teamRoundState.MarkerSystemSeen == true
    context.NearbyCombatReady = false
    context.NearbyCombatCount = 0

    return context
end

function isEnemy(targetPlayer, context)
    if not teamCheckEnabled then
        return targetPlayer ~= player
    end
    if not targetPlayer or targetPlayer == player then
        return false
    end

    if not context then syncTeamRoundState() end

    if isRememberedTeammate(targetPlayer) then
        return false
    end

    local cached = enemyCache[targetPlayer]
    if cached ~= nil then
        return cached
    end

    local char = targetPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local hrp = char and char:FindFirstChild("HumanoidRootPart")

    if not char or not hum or hum.Health <= 0 or not hrp then
        return false
    end

    if hrp:FindFirstChild(TEAMMATE_MARKER_NAME) then
        rememberTeammate(targetPlayer)
        return false
    end

    local markerSystemActive
    if context then
        if not context.MarkersScanned then
            context.MarkersScanned = true
            if not teamRoundState.MarkerSystemSeen then rememberVisibleTeammates() end
            context.MarkerSystemActive = teamRoundState.MarkerSystemSeen == true
        end
        markerSystemActive = context.MarkerSystemActive == true
    else
        markerSystemActive = teammateMarkerSystemActive()
    end

    if markerSystemActive then
        enemyCache[targetPlayer] = true
        return true
    end

    local result = fallbackEnemyRelation(targetPlayer, context)
    if result == true then
        enemyCache[targetPlayer] = true
    end
    return result
end

runtime.IsEnemyShared = isEnemy

