    grid.SortOrder = Enum.SortOrder.LayoutOrder
    grid.Parent = scroll

    local function updateGrid()
        if not panel.Parent then return end
        local width = scroll.AbsoluteSize.X
        if width < 460 then
            grid.CellSize = UDim2.new(1, -8, 0, 156)
        elseif width < 700 then
            grid.CellSize = UDim2.new(0.5, -7, 0, 174)
        else
            grid.CellSize = UDim2.new(0.333333, -8, 0, 178)
        end
