function runtime.RenderOutfitBrowser()
    local state = runtime.OutfitBrowser
    local scroll = state.Scroll
    if not scroll then return end

    state.RenderSerial += 1
    local serial = state.RenderSerial
    local query = string.lower(tostring(state.SearchBox and state.SearchBox.Text or ""))

    for _, child in ipairs(scroll:GetChildren()) do
        if child:IsA("GuiObject") then child:Destroy() end
    end

    local visibleCount = 0
    for index, outfit in ipairs(state.CurrentOutfits or {}) do
        local nameLower = string.lower(outfit.Name)
        if query == "" or string.find(nameLower, query, 1, true) then
            visibleCount += 1

            local card = Instance.new("TextButton")
            card.Name = "Outfit_" .. tostring(outfit.Id)
            card.LayoutOrder = index
            card.BackgroundColor3 = Color3.fromRGB(13, 13, 16)
            card.BorderSizePixel = 0
            card.Text = ""
            card.AutoButtonColor = false
            card.ZIndex = 503
            card.Parent = scroll
            Instance.new("UICorner", card).CornerRadius = UDim.new(0, 14)
            local cardStroke = Instance.new("UIStroke", card)
            cardStroke.Color = Color3.fromRGB(45, 45, 51)
            cardStroke.Transparency = 0.28

            local image = Instance.new("ImageLabel")
            image.Position = UDim2.fromOffset(8, 8)
            image.Size = UDim2.new(1, -16, 1, -58)
            image.BackgroundColor3 = Color3.fromRGB(7, 7, 9)
            image.BorderSizePixel = 0
            image.Image = "rbxthumb://type=Outfit&id=" .. tostring(outfit.Id) .. "&w=150&h=150"
            image.ScaleType = Enum.ScaleType.Fit
            image.ZIndex = 504
            image.Parent = card
            Instance.new("UICorner", image).CornerRadius = UDim.new(0, 10)

            local name = Instance.new("TextLabel")
            name.Position = UDim2.new(0, 10, 1, -43)
            name.Size = UDim2.new(1, -20, 0, 18)
            name.BackgroundTransparency = 1
            name.Text = outfit.Name
            name.TextColor3 = Color3.fromRGB(240, 240, 244)
            name.Font = Enum.Font.GothamSemibold
            name.TextSize = 11
            name.TextXAlignment = Enum.TextXAlignment.Left
            name.TextTruncate = Enum.TextTruncate.AtEnd
            name.ZIndex = 504
            name.Parent = card

            local hint = Instance.new("TextLabel")
            hint.Position = UDim2.new(0, 10, 1, -24)
            hint.Size = UDim2.new(1, -20, 0, 14)
            hint.BackgroundTransparency = 1
            hint.Text = "TOCAR PARA CLONAR"
            hint.TextColor3 = Color3.fromRGB(110, 110, 120)
            hint.Font = Enum.Font.GothamMedium
            hint.TextSize = 8
            hint.TextXAlignment = Enum.TextXAlignment.Left
            hint.ZIndex = 504
            hint.Parent = card

            card.MouseEnter:Connect(function()
                cardStroke.Color = Color3.fromRGB(105, 105, 116)
            end)
            card.MouseLeave:Connect(function()
                cardStroke.Color = Color3.fromRGB(45, 45, 51)
            end)

            card.Activated:Connect(function()
                if serial ~= state.RenderSerial then return end
                task.spawn(function()
                    showBottomMessage("Cargando outfit · " .. outfit.Name .. "...")
                    local ok, err = runtime.CloneAvatarFromOutfitId(
                        outfit.Id,
                        outfit.Name,
                        state.CurrentUserId,
                        state.CurrentUserName,
                        true
                    )
                    if ok then
                        state.Overlay.Visible = false
                        runtime.RestoreOutfitBrowserGuiOrder()
                        showBottomMessage("Skin clonada · " .. outfit.Name)
                    else
                        warn("[XeroHub] Outfit:", err)
                        showBottomMessage("No se pudo clonar ese outfit: " .. tostring(err or "error"))
                    end
                end)
            end)
        end
    end

    if state.Count then
        local total = #(state.CurrentOutfits or {})
        if query ~= "" then
            state.Count.Text = tostring(visibleCount) .. " de " .. tostring(total) .. " outfits"
        else
            state.Count.Text = tostring(total) .. (total == 1 and " outfit" or " outfits")
        end
    end
end

function runtime.OpenUserOutfits(forceRefresh)
    local userId, username, resolveError = runtime.ResolveOutfitBrowserUser()
    if not userId then
        showBottomMessage(resolveError)
        return false
    end

    local state = runtime.EnsureOutfitBrowser()
    state.CurrentUserId = userId
    state.CurrentUserName = username
    state.Title.Text = "Skins de @" .. tostring(username)
    state.Count.Text = "Cargando outfits..."
    state.SearchBox.Text = ""
    runtime.BringOutfitBrowserToFront()
    state.Overlay.Visible = true

    task.spawn(function()
        local outfits, err = runtime.FetchUserOutfits(userId, forceRefresh == true)
        if not runtime.Alive or not state.Gui or not state.Gui.Parent then return end
        if state.CurrentUserId ~= userId then return end

        if not outfits then
            state.Count.Text = "No se pudieron cargar"
            showBottomMessage(tostring(err or "No se pudieron cargar los outfits"))
            return
        end

        state.CurrentOutfits = outfits
        runtime.RenderOutfitBrowser()
        if #outfits == 0 then
            showBottomMessage("Ese usuario no tiene outfits guardados públicos.")
        end
    end)

    return true
end

local appearanceLayoutOrder = 100

local function placeAppearanceElement(element, order)
    if element and element.ElementFrame then
        element.ElementFrame.LayoutOrder = order
    end
    return element
end

local function nextAppearanceOrder(step)
    local current = appearanceLayoutOrder
    appearanceLayoutOrder = appearanceLayoutOrder + (step or 10)
    return current
end

local introAppearance = Tabs.Apariencia:Paragraph({
    Title = "Equipa accesorios visuales",
    Desc = "Activa tus accesorios visuales y, si quieres ajustarlos fino, abre el editor visual."
})
placeAppearanceElement(introAppearance, nextAppearanceOrder())

runtime.SetupAvatarCloneUI = function()
    local cloneSection = Tabs.Apariencia:Section({Title = "Clonador de avatar"})
    placeAppearanceElement(cloneSection, nextAppearanceOrder())

    local function getAvatarClonePlayerValues()
        local values = {}
        for _, target in ipairs(Players:GetPlayers()) do
            if target ~= player then
                table.insert(values, target.Name)
            end
        end
        table.sort(values, function(a, b)
            return string.lower(a) < string.lower(b)
        end)
        if #values == 0 then
            values[1] = "Sin jugadores"
        end
        return values
    end

    local initialClonePlayers = getAvatarClonePlayerValues()
    runtime.Appearance.AvatarClone.SelectedServerPlayer =
        initialClonePlayers[1] ~= "Sin jugadores" and initialClonePlayers[1] or nil

    local avatarCloneDropdown = Tabs.Apariencia:Dropdown({
        Title = "Jugador del servidor",
        Values = initialClonePlayers,
        Value = initialClonePlayers[1],
        Callback = function(value)
            if value ~= "Sin jugadores" then
                runtime.Appearance.AvatarClone.SelectedServerPlayer = value
            else
                runtime.Appearance.AvatarClone.SelectedServerPlayer = nil
            end
        end,
    })
    placeAppearanceElement(avatarCloneDropdown, nextAppearanceOrder())
    UIElements.DropAvatarClonePlayer = avatarCloneDropdown

    local function refreshAvatarClonePlayers()
        if not avatarCloneDropdown then return end
        local values = getAvatarClonePlayerValues()
        local selected = runtime.Appearance.AvatarClone.SelectedServerPlayer

        local stillExists = false
        for _, name in ipairs(values) do
            if name == selected then
                stillExists = true
                break
            end
        end

        if not stillExists then
            runtime.Appearance.AvatarClone.SelectedServerPlayer =
                values[1] ~= "Sin jugadores" and values[1] or nil
        end

        pcall(function() avatarCloneDropdown:Refresh(values) end)
    end

    runtime.Track(Players.PlayerAdded:Connect(function()
        task.defer(refreshAvatarClonePlayers)
    end))
    runtime.Track(Players.PlayerRemoving:Connect(function()
        task.defer(refreshAvatarClonePlayers)
    end))

    local cloneServerButton = Tabs.Apariencia:Button({
        Title = "Clonar jugador seleccionado",
        Desc = "Copia el avatar.",
        Callback = function()
            local selected = runtime.Appearance.AvatarClone.SelectedServerPlayer
            local target = selected and Players:FindFirstChild(selected) or nil
            if not target or target == player then
                showBottomMessage("Selecciona un jugador válido.")
                return
            end

            task.spawn(function()
                showBottomMessage("Cargando avatar de " .. target.Name .. "...")
                local ok, err = runtime.CloneAvatarFromPlayer(target, true)
                if ok then
                    showBottomMessage("Avatar clonado: " .. target.Name)
                else
                    warn("iLunX AvatarClone:", err)
                    showBottomMessage("No se pudo clonar: " .. tostring(err or "error desconocido"))
                end
            end)
        end,
    })
    placeAppearanceElement(cloneServerButton, nextAppearanceOrder())

    local avatarUsernameInput = Tabs.Apariencia:Input({
        Title = "Clonar por username",
        Placeholder = "Ej: builderman",
        Callback = function(text)
            runtime.Appearance.AvatarClone.UsernameInput = tostring(text or "")
        end,
    })
    placeAppearanceElement(avatarUsernameInput, nextAppearanceOrder())
    UIElements.InputAvatarCloneUsername = avatarUsernameInput

    local cloneUsernameButton = Tabs.Apariencia:Button({
        Title = "Cargar avatar por username",
        Desc = "Funciona aunque el usuario no esté en tu servidor.",
        Callback = function()
            local username = runtime.Appearance.AvatarClone.UsernameInput
            if not username or username:gsub("%s+", "") == "" then
                showBottomMessage("Escribe un username.")
                return
            end

            task.spawn(function()
                showBottomMessage("Buscando @" .. username .. "...")
                local ok, err = runtime.CloneAvatarByUsername(username, true)
                if ok then
                    local targetName = runtime.Appearance.AvatarClone.TargetName or username
                    showBottomMessage("Avatar clonado: " .. targetName)
                else
                    warn("iLunX AvatarClone:", err)
                    showBottomMessage(tostring(err or "No se pudo cargar ese avatar."))
                end
            end)
        end,
    })
    placeAppearanceElement(cloneUsernameButton, nextAppearanceOrder())

    local browseOutfitsButton = Tabs.Apariencia:Button({
        Title = "Ver skins del usuario",
        Desc = "Muestra sus outfits guardados con miniatura y te deja clonar cualquiera.",
        Callback = function()
            runtime.OpenUserOutfits(false)
        end,
    })
    placeAppearanceElement(browseOutfitsButton, nextAppearanceOrder())

    local refreshOutfitsButton = Tabs.Apariencia:Button({
        Title = "Actualizar skins guardadas",
        Desc = "Actualiza skins del usuario",
        Callback = function()
            runtime.OpenUserOutfits(true)
        end,
    })
    placeAppearanceElement(refreshOutfitsButton, nextAppearanceOrder())

    local keepCloneToggle = Tabs.Apariencia:Toggle({
        Title = "Mantener clon al respawnear",
        Desc = "Reaplica el avatar clonado después de morir.",
        Value = true,
        Callback = function(state)
            runtime.Appearance.AvatarClone.KeepOnRespawn = state == true
        end,
    })
    placeAppearanceElement(keepCloneToggle, nextAppearanceOrder())
    UIElements.TogKeepAvatarClone = keepCloneToggle

    local restoreOwnAvatarButton = Tabs.Apariencia:Button({
        Title = "Restaurar mi avatar",
        Desc = "Vuelve a tu avatar y mantiene limiteds que estén activos.",
        Callback = function()
            if not runtime.Appearance.AvatarClone.Active then
                showBottomMessage("No tienes un avatar clonado activo.")
                return
            end

            task.spawn(function()
                local ok, err = runtime.RestoreAvatarClone(true)
                if ok then
                    showBottomMessage("Tu avatar original fue restaurado.")
                else
                    warn("iLunX AvatarClone restore:", err)
                    showBottomMessage("No se pudo restaurar tu avatar.")
                end
            end)
        end,
    })
    placeAppearanceElement(restoreOwnAvatarButton, nextAppearanceOrder())
end

