local aimHookState = {
    Version = runtime.AimLifecycleVersion,
    Target = nil,
    Mouse = mouse,
    Owner = runtime,
    Wanted = false,
    RoundActive = false,
    LegacyPermanent = false,
    Installed = false,
    OldNamecall = nil,
    OldIndex = nil,
}
runtimeEnv.__ILUNX_AIM_HOOK_STATE = aimHookState

aimHookState.DirectGunTool = nil
aimHookState.DirectGunShoot = nil
aimHookState.DirectGunLastPart = nil
aimHookState.DirectGunLastPosition = nil
aimHookState.DirectGunReady = false
aimHookState.DirectGunResolveFailures = 0

runtime.DirectGetUpvalueFn = (debug and type(debug.getupvalue) == "function" and debug.getupvalue)
    or (type(getupvalue) == "function" and getupvalue) or false
runtime.DirectSetupUpvalueFn = (debug and type(debug.setupvalue) == "function" and debug.setupvalue)
    or (type(setupvalue) == "function" and setupvalue) or false
runtime.DirectGetUpvaluesFn = (debug and type(debug.getupvalues) == "function" and debug.getupvalues)
    or (type(getupvalues) == "function" and getupvalues) or false

function runtime.DirectGetUpvalue(fn, index)
    local getter = runtime.DirectGetUpvalueFn
    if getter == false or type(fn) ~= "function" then return nil end

    local ok, a, b = pcall(getter, fn, index)
    if not ok then return nil end

    if b ~= nil then return b end
    return a
end

function runtime.DirectSetupUpvalue(fn, index, value)
    local setter = runtime.DirectSetupUpvalueFn
    if setter == false or type(fn) ~= "function" then return false end
    return pcall(setter, fn, index, value)
end

function runtime.DirectFnName(fn)
    if type(fn) ~= "function" then return "" end
    local name = ""
    if debug and type(debug.info) == "function" then
        pcall(function() name = debug.info(fn, "n") or "" end)
    elseif debug and type(debug.getinfo) == "function" then
        pcall(function()
            local info = debug.getinfo(fn)
            name = (info and info.name) or ""
        end)
    end
    return tostring(name)
end

function runtime.DirectConnectionFunction(connection)
    if not connection then return nil end
    local fn = nil
    pcall(function() fn = connection.Function end)
    if type(fn) ~= "function" then
        pcall(function() fn = connection.Callback end)
    end
    return type(fn) == "function" and fn or nil
end

function runtime.RestoreDirectGunPatch()
    local state = aimHookState
    local callback = state.DirectGunActivatedCallback
    local originalShoot = state.DirectGunShoot
    if callback and originalShoot and state.DirectGunPatched then

        runtime.DirectSetupUpvalue(callback, 4, originalShoot)
    end
    state.DirectGunActivatedCallback = nil
    state.DirectGunWrapper = nil
    state.DirectGunPatched = false
end

function runtime.ClearDirectGunCache()
    local state = aimHookState
    runtime.RestoreDirectGunPatch()
    state.DirectGunTool = nil
    state.DirectGunShoot = nil
    state.DirectGunLastPart = nil
    state.DirectGunLastPosition = nil
    state.DirectGunReady = false
end

function runtime.DirectReadKnownUpvalue(fn, index)

    local bulk = runtime.DirectGetUpvaluesFn
    if bulk ~= false and type(fn) == "function" then
        local ok, values = pcall(bulk, fn)
        if ok and type(values) == "table" then
            local value = values[index]
            if value ~= nil then return value end
        end
    end
    return runtime.DirectGetUpvalue(fn, index)
end

function runtime.ResolveDirectGunShoot(tool)
    local state = aimHookState
    if state.Owner ~= runtime or not runtime.Alive or not tool or not tool.Parent then
        return nil
    end

    if state.DirectGunReady
        and state.DirectGunTool == tool
        and type(state.DirectGunShoot) == "function"
        and state.DirectGunPatched
        and type(state.DirectGunWrapper) == "function" then
        return state.DirectGunShoot
    end

    runtime.ClearDirectGunCache()
    state.Target = nil

    if type(getconnections) ~= "function" then
        state.DirectGunResolveFailures = (state.DirectGunResolveFailures or 0) + 1
        return nil
    end

    local ok, connections = pcall(getconnections, tool.Activated)
    if not ok or type(connections) ~= "table" then
        state.DirectGunResolveFailures = (state.DirectGunResolveFailures or 0) + 1
        return nil
    end

    for i = 1, #connections do
        local callback = runtime.DirectConnectionFunction(connections[i])
        if callback then

            local shoot = runtime.DirectReadKnownUpvalue(callback, 4)
            if type(shoot) == "function" then
                local destination = runtime.DirectReadKnownUpvalue(shoot, 5)
                local beamFn = runtime.DirectReadKnownUpvalue(shoot, 6)
                local parentTool = runtime.DirectReadKnownUpvalue(shoot, 7)
                local shootName = runtime.DirectFnName(shoot)
                local beamName = runtime.DirectFnName(beamFn)

                local namesOK = (shootName == "" or shootName == "Shoot")
                    and (type(beamFn) ~= "function" or beamName == "" or beamName == "ShootLocalBeam")

                if namesOK
                    and typeof(destination) == "Vector3"
                    and parentTool == tool then

                    local wrapper = function(...)
                        local target = state.Target
                        if runtime.Alive
                            and state.DirectGunTool == tool
                            and (autoShootEnabled or silentAimPistolaEnabled or runtime.QuickGunFiring == true)
                            and state.RoundActive
                            and target and target.Parent then
                            runtime.DirectSetupUpvalue(shoot, 5, target.Position)
                        end
                        return shoot(...)
                    end

                    local patched = runtime.DirectSetupUpvalue(callback, 4, wrapper)
                    if patched then
                        state.DirectGunTool = tool
                        state.DirectGunShoot = shoot
                        state.DirectGunActivatedCallback = callback
                        state.DirectGunWrapper = wrapper
                        state.DirectGunPatched = true
                        state.DirectGunReady = true
                        state.DirectGunResolveFailures = 0
                        return shoot
                    end
                end
            end
        end
    end

    state.DirectGunResolveFailures = (state.DirectGunResolveFailures or 0) + 1
    return nil
end

function runtime.ApplyDirectGunTarget(tool, targetPart)
    local state = aimHookState
    if state.Owner ~= runtime or not runtime.Alive
        or not tool or not tool.Parent
        or not targetPart or not targetPart.Parent then
        return false
    end

    if not (state.DirectGunReady and state.DirectGunTool == tool and state.DirectGunPatched) then
        if not runtime.ResolveDirectGunShoot(tool) then return false end
    end

    state.RoundActive = true

    state.Target = targetPart
    state.DirectGunLastPart = targetPart
    return true
end

local function wrapAimHook(fn)
    if type(newcclosure) == "function" then
        local ok, wrapped = pcall(newcclosure, fn)
        if ok and wrapped then return wrapped end
    end
    return fn
end

function runtime.InstallAimHooks()
    local state = aimHookState
    if not runtime.Alive or state.Owner ~= runtime then return false end
    if state.LegacyPermanent then
        state.Installed = true
        return true
    end
    if state.Installed then return true end
    if type(hookmetamethod) ~= "function" then return false end

    local namecallHook = wrapAimHook(function(self, ...)
        local knifeWanted = autoShootCuchilloEnabled or silentAimCuchilloEnabled
        local target = knifeWanted and state.RoundActive and state.Wanted and state.Target or nil
        if not checkcaller() and target then
            if target.Parent then
                local method = getnamecallmethod()
                if self == workspace then
                    if method == "Raycast" then
                        local origin, direction, p3 = ...
                        if typeof(direction) == "Vector3" and direction:Dot(direction) > 25 then
                            local currentCamera = workspace.CurrentCamera
                            local cameraDelta = origin - currentCamera.CFrame.Position
                            if cameraDelta:Dot(cameraDelta) > 1 then
                                local newDir = (target.Position - origin).Unit * 5000
                                return state.OldNamecall(self, origin, newDir, p3)
                            end
                        end
                    elseif method == "FindPartOnRay" or method == "FindPartOnRayWithIgnoreList" then
                        local ray, p2, p3, p4 = ...
                        if typeof(ray) == "Ray" and ray.Direction:Dot(ray.Direction) > 25 then
                            local currentCamera = workspace.CurrentCamera
                            local cameraDelta = ray.Origin - currentCamera.CFrame.Position
                            if cameraDelta:Dot(cameraDelta) > 1 then
                                local newRay = Ray.new(ray.Origin, (target.Position - ray.Origin).Unit * 5000)
                                return state.OldNamecall(self, newRay, p2, p3, p4)
                            end
                        end
                    end
                end
            else
                state.Target = nil
            end
        end
        return state.OldNamecall(self, ...)
    end)

    local okNamecall, oldNamecall = pcall(hookmetamethod, game, "__namecall", namecallHook)
    if not okNamecall or type(oldNamecall) ~= "function" then
        state.OldNamecall = nil
        return false
    end

    state.OldNamecall = oldNamecall
    state.OldIndex = nil
    state.Installed = true
    return true
end

function runtime.UninstallAimHooks(force)
    local state = aimHookState
    state.Target = nil

    if state.LegacyPermanent then
        state.Wanted = false
        state.RoundActive = false
        if force then runtime.ClearDirectGunCache() end
        return false
    end

    if state.Installed then
        local oldNamecall = state.OldNamecall
        state.Installed = false
        state.OldIndex = nil
        state.OldNamecall = nil
        if oldNamecall then pcall(hookmetamethod, game, "__namecall", oldNamecall) end
    end

    if force then
        state.Wanted = false
        state.RoundActive = false
        runtime.ClearDirectGunCache()
    end
    return true
end

function runtime.RefreshAimHooks(inMatchOverride)
    local state = aimHookState
    if state.Owner ~= runtime or not runtime.Alive then return end

    local wanted = autoShootCuchilloEnabled or silentAimCuchilloEnabled

    local inMatch = inMatchOverride
    if inMatch == nil then
        local ok, result = pcall(runtime.IsCombatRound)
        inMatch = ok and result == true or false
    else
        inMatch = inMatch == true
    end

    state.Wanted = wanted == true
    state.RoundActive = inMatch

    if state.Wanted and state.RoundActive then
        runtime.InstallAimHooks()
    else
        runtime.UninstallAimHooks(false)
        state.RoundActive = inMatch
        state.Wanted = wanted == true
    end
end

function runtime.EnsureAimHooksReady()
    local state = aimHookState
    if state.Owner ~= runtime or not runtime.Alive then return false end
    if state.Installed and state.RoundActive and state.Wanted then return true end
    runtime.RefreshAimHooks()
    return state.Installed and state.RoundActive and state.Wanted
end

runtime.Track(player:GetPropertyChangedSignal("Team"):Connect(function()
    task.defer(runtime.RefreshAimHooks)
end))
runtime.Track(player:GetPropertyChangedSignal("Neutral"):Connect(function()
    task.defer(runtime.RefreshAimHooks)
end))

runtime.AimState = aimHookState

local activeESPs = {}
local MAX_ESP_DISTANCE = 1500
runtime.ESPGlowVisibleCount = 0

local function setESPGlowEnabled(espObj, enabled)
    if not espObj then return end
    local highlight = espObj.Highlight
    if not highlight or not highlight.Parent then return end
    enabled = enabled == true
    if highlight.Enabled == enabled then return end

    highlight.Enabled = enabled
    if enabled then
        runtime.ESPGlowVisibleCount = (runtime.ESPGlowVisibleCount or 0) + 1
    else
        runtime.ESPGlowVisibleCount = math.max(0, (runtime.ESPGlowVisibleCount or 0) - 1)
    end
end

function cleanESP(targetPlayer)
    local espObj = activeESPs[targetPlayer]
    if not espObj then return end

    local highlight = espObj.Highlight
    if highlight then
        if highlight.Enabled then
            runtime.ESPGlowVisibleCount = math.max(0, (runtime.ESPGlowVisibleCount or 0) - 1)
        end
        pcall(function() highlight:Destroy() end)
    end
    activeESPs[targetPlayer] = nil
end

local function hideESP(targetPlayer)
    local espObj = activeESPs[targetPlayer]
    if not espObj then return end
    setESPGlowEnabled(espObj, false)
end

local ESP_GLOW_PARENT = ReplicatedStorage
local ESP_GLOW_FILL_TRANSPARENCY = 0.45

local function getESPHighlightParent()
    return ESP_GLOW_PARENT
end

function runtime.SyncESPGlow(targetPlayer, char, visible)
    local espObj = activeESPs[targetPlayer]

    if espObj and (espObj.Char ~= char
        or not espObj.Highlight
        or not espObj.Highlight.Parent) then
        cleanESP(targetPlayer)
        espObj = nil
    end

    if not visible or not char then
        hideESP(targetPlayer)
        return
    end

    if not espObj then
        local highlight = Instance.new("Highlight")
        highlight.Name = "XeroESPGlow"
        highlight.FillColor = espColor
        highlight.FillTransparency = ESP_GLOW_FILL_TRANSPARENCY

        highlight.OutlineTransparency = 1
        highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        highlight.Adornee = char
        highlight.Enabled = false
        highlight.Parent = getESPHighlightParent()

        espObj = {
            Highlight = highlight,
            Char = char,
        }
        activeESPs[targetPlayer] = espObj
    end

    local highlight = espObj.Highlight
    local desiredParent = getESPHighlightParent()
    if highlight.Parent ~= desiredParent then highlight.Parent = desiredParent end
    if highlight.Adornee ~= char then highlight.Adornee = char end
    if highlight.FillColor ~= espColor then highlight.FillColor = espColor end
    setESPGlowEnabled(espObj, true)
end

function runtime.HideAllESPGlow()
    if (runtime.ESPGlowVisibleCount or 0) <= 0 then return end
    for targetPlayer in pairs(activeESPs) do
        hideESP(targetPlayer)
    end
    runtime.ESPGlowVisibleCount = 0
end

runtime.ESPVisualCleanup = function()
    for targetPlayer in pairs(activeESPs) do
        cleanESP(targetPlayer)
    end
    runtime.ESPGlowVisibleCount = 0
end

