    hbLegacyScanned = setmetatable({}, {__mode = "k"}),
    hbCreateQueue = {},
    hbCreatePending = setmetatable({}, {__mode = "k"}),
    hbCleanupQueue = {},
    hbCleanupPending = setmetatable({}, {__mode = "k"}),
    hbSpikeWorkerRunning = false,
