    aimVisibilityMoveSq = 0.5625,
}
mState.pHB.FilterType = Enum.RaycastFilterType.Exclude
mState.pAS.FilterType = Enum.RaycastFilterType.Exclude
mState.pSA.FilterType = Enum.RaycastFilterType.Exclude

function runtime.GetAimRayParams(localChar, enemyChar)
    if not localChar or not enemyChar then return nil end
    local cache = mState.aimRayParamsCache
    local entry = cache[enemyChar]
    if entry and entry.LocalChar == localChar then return entry.Params end

    local params = RaycastParams.new()
    params.FilterType = Filter_Exclude
    params.FilterDescendantsInstances = {localChar, enemyChar}
    cache[enemyChar] = {LocalChar = localChar, Params = params}
    return params
end

function runtime.AimPartVisibleCached(part, enemyChar, localChar, origin, partPosition, params, now)
    if not part or not part.Parent or not enemyChar or not enemyChar.Parent then return false end

    now = now or os.clock()
    local cache = mState.aimVisibilityCache
    local entry = cache[part]
    if entry and entry.EnemyChar == enemyChar and entry.LocalChar == localChar
        and now - (entry.At or 0) <= mState.aimVisibilityTTL then
        local originDelta = origin - entry.Origin
        local targetDelta = partPosition - entry.Target
        local moveSq = mState.aimVisibilityMoveSq
        if originDelta:Dot(originDelta) <= moveSq and targetDelta:Dot(targetDelta) <= moveSq then
            return entry.Visible == true
        end
    end

    local visible = not ws_Raycast(workspace, origin, partPosition - origin, params)
    if entry then
        entry.EnemyChar = enemyChar
        entry.LocalChar = localChar
        entry.Origin = origin
        entry.Target = partPosition
        entry.Visible = visible
        entry.At = now
    else
        cache[part] = {
            EnemyChar = enemyChar,
            LocalChar = localChar,
            Origin = origin,
            Target = partPosition,
            Visible = visible,
            At = now,
        }
    end
    return visible
end

function runtime.DisconnectCharCoreSignals(core)
    if not core then return end
    local keys = {"ForceFieldAddedConnection", "ForceFieldRemovedConnection", "AncestryConnection"}
    for i = 1, #keys do
        local connection = core[keys[i]]
        if connection then
            pcall(function() connection:Disconnect() end)
            core[keys[i]] = nil
        end
    end
end

local function getCharCore(char)
    if not char then return nil end
    local core = mState.charCore[char]
    if core and core.Humanoid and core.Humanoid.Parent == char and core.HRP and core.HRP.Parent == char then
        if not core.Head or core.Head.Parent ~= char then core.Head = ffc(char, "Head") end
        if not core.LeftFoot or core.LeftFoot.Parent ~= char then core.LeftFoot = ffc(char, "LeftFoot") or ffc(char, "LeftLeg") end
        if not core.RightFoot or core.RightFoot.Parent ~= char then core.RightFoot = ffc(char, "RightFoot") or ffc(char, "RightLeg") end
        return core
    end

    if core then runtime.DisconnectCharCoreSignals(core) end
    core = {
        Humanoid = ffc(char, "Humanoid") or char:FindFirstChildOfClass("Humanoid"),
        HRP = ffc(char, "HumanoidRootPart"),
        Head = ffc(char, "Head"),
        LeftFoot = ffc(char, "LeftFoot") or ffc(char, "LeftLeg"),
        RightFoot = ffc(char, "RightFoot") or ffc(char, "RightLeg"),
        HasForceField = char:FindFirstChildOfClass("ForceField") ~= nil,
    }

    core.ForceFieldAddedConnection = runtime.Track(char.ChildAdded:Connect(function(child)
        if child:IsA("ForceField") then core.HasForceField = true end
        if child:IsA("BasePart") and runtime.InvalidateTargetPartCache then
            runtime.InvalidateTargetPartCache(char)
        end
    end))
    core.ForceFieldRemovedConnection = runtime.Track(char.ChildRemoved:Connect(function(child)
        if child:IsA("ForceField") then
            core.HasForceField = char:FindFirstChildOfClass("ForceField") ~= nil
        end
        if child:IsA("BasePart") and runtime.InvalidateTargetPartCache then
            runtime.InvalidateTargetPartCache(char)
        end
    end))
    core.AncestryConnection = runtime.Track(char.AncestryChanged:Connect(function(_, parent)
        if parent then return end
        if mState.charCore[char] == core then mState.charCore[char] = nil end
        runtime.DisconnectCharCoreSignals(core)
        task.defer(function()
            if runtime.Alive then runtime.PruneConnections() end
        end)
    end))

    mState.charCore[char] = core
    return core
end

local function enemigoEnLobby(enemyChar, enemyHrp, knownCore)
    if not enemyChar then return true end
    local core = knownCore or getCharCore(enemyChar)
    if core and core.HasForceField then return true end
    local eHrp = enemyHrp or (core and core.HRP)
    if eHrp then
        for i = 1, #ZONAS_SEGURAS do
            local zona = ZONAS_SEGURAS[i]
            local delta = eHrp.Position - zona.Centro
            if delta:Dot(delta) <= zona.RadioSq then return true end
        end
    end
    return false
end

runtime.BindEquippedToolCache = function(char)
    if mState.toolAddedConnection then
        pcall(function() mState.toolAddedConnection:Disconnect() end)
        mState.toolAddedConnection = nil
    end
    if mState.toolRemovedConnection then
        pcall(function() mState.toolRemovedConnection:Disconnect() end)
        mState.toolRemovedConnection = nil
    end

    mState.toolChar = char
    mState.equippedTool = char and char:FindFirstChildOfClass("Tool") or nil
    if char then
        mState.toolAddedConnection = runtime.Track(char.ChildAdded:Connect(function(child)
            if child:IsA("Tool") then
                mState.equippedTool = child

                if (autoShootEnabled or silentAimPistolaEnabled) and esLaPistola(child) then
                    task.defer(runtime.ResolveDirectGunShoot, child)
                end
            end
        end))
        mState.toolRemovedConnection = runtime.Track(char.ChildRemoved:Connect(function(child)
            if child == mState.equippedTool then
                mState.equippedTool = char:FindFirstChildOfClass("Tool")
            end
        end))
    end
    runtime.PruneConnections()

    local equipped = mState.equippedTool
    if equipped and (autoShootEnabled or silentAimPistolaEnabled) and esLaPistola(equipped) then
        task.defer(runtime.ResolveDirectGunShoot, equipped)
    end
end
runtime.Track(player.CharacterAdded:Connect(function(char)
    runtime.BindEquippedToolCache(char)
end))
runtime.BindEquippedToolCache(player.Character)

function runtime.GetLocalCombatSnapshot()
    if mState.localCombatSnapshotReady then
        return mState.localCombatSnapshot
    end

    local snapshot = mState.localCombatSnapshot
    local char = player.Character
    local core = char and getCharCore(char) or nil
    local hrp = core and core.HRP or nil
    local head = core and core.Head or nil
    local tool = nil

    if char then
        tool = (mState.toolChar == char) and mState.equippedTool or char:FindFirstChildOfClass("Tool")
        if tool and tool.Parent ~= char then tool = nil end
    end

    local position = hrp and hrp.Position or nil
    snapshot.Character = char
    snapshot.Core = core
    snapshot.HRP = hrp
    snapshot.Head = head
    snapshot.Tool = tool
    snapshot.Position = position
    snapshot.HeadPosition = (head and head.Position) or position

    mState.localCombatSnapshotReady = true
    return snapshot
end

function runtime.GetEnemySnapshot()
    if mState.enemySnapshotReady then
        return mState.enemySnapshot, mState.enemySnapshotCount
    end

    local snapshot = mState.enemySnapshot
    local previousCount = mState.enemySnapshotCount
    local queryContext = runtime.PrepareEnemyQueryContext()
    local count = 0
    for i = 1, #listaJugadores do
        local p = listaJugadores[i]
        if p ~= player then
            count = count + 1
            local entry = snapshot[count]
            if not entry then
                entry = {}
                snapshot[count] = entry
            end

            local char = p.Character
            local core = char and getCharCore(char) or nil
            local hrp = core and core.HRP or nil
            local hum = core and core.Humanoid or nil
            local alive = hrp ~= nil and hum ~= nil and hum.Health > 0
            local position = alive and hrp.Position or nil

            entry.Player = p
            entry.Character = char
            entry.Core = core
            entry.HRP = hrp
            entry.Humanoid = hum
            entry.Head = core and core.Head or nil
            entry.Position = position
            entry.Alive = alive
            entry.Enemy = alive and isEnemy(p, queryContext) or false
            entry.SafeZone = nil
        end
    end

    for i = count + 1, previousCount do
        snapshot[i] = nil
    end
    mState.enemySnapshotCount = count
    mState.enemySnapshotReady = true
    return snapshot, count
end

function runtime.SnapshotEntryInSafeZone(entry)
    if entry.SafeZone == nil then
        entry.SafeZone = entry.Alive and enemigoEnLobby(entry.Character, entry.HRP, entry.Core) or true
    end
    return entry.SafeZone
end

function runtime.QuickGunHasVisibleEnemy(currentCamera)
    local localSnapshot = runtime.GetLocalCombatSnapshot()
    local char = localSnapshot.Character
    local hrp = localSnapshot.HRP
    local origin = localSnapshot.HeadPosition or localSnapshot.Position
    if not char or not hrp or not origin or not currentCamera then return false end

    local enemies, enemyCount = runtime.GetEnemySnapshot()
    local now = os.clock()
    for i = 1, enemyCount do
        local enemy = enemies[i]
        if enemy.Alive and enemy.Enemy and not runtime.SnapshotEntryInSafeZone(enemy) then
            local enemyChar = enemy.Character
            local targetPart = enemy.Head or enemy.HRP
            if enemyChar and targetPart and targetPart.Parent == enemyChar then
                local targetPosition = targetPart.Position
                local delta = targetPosition - localSnapshot.Position
                if delta:Dot(delta) <= 640000 then
                    local screenPoint, onScreen = currentCamera:WorldToViewportPoint(targetPosition)
                    if onScreen and screenPoint.Z > 0 then
                        local params = runtime.GetAimRayParams(char, enemyChar)
                        if params and runtime.AimPartVisibleCached(
                            targetPart, enemyChar, char, origin, targetPosition, params, now
                        ) then
                            return targetPart
                        end
                    end
                end
            end
        end
    end
    return false
end

function runtime.CancelQuickGunEquip(unequipOwnedTool)
    mState.quickGunSerial = (mState.quickGunSerial or 0) + 1
    local tool = mState.quickGunTool
    runtime.QuickGunFiring = false
    mState.quickGunTool = nil
    mState.quickGunBusy = false
    mState.tQuickGun = 0
    mState.quickGunNextAt = 0

    if unequipOwnedTool and tool then
        local char = player.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum and tool.Parent == char then
            pcall(function() hum:UnequipTools() end)
            mState.localCombatSnapshotReady = false
        end
    end
end

function runtime.StartQuickGunEquipPulse(targetPart)
    if mState.quickGunBusy or not runtime.QuickGunEquipEnabled then return false end

    local localSnapshot = runtime.GetLocalCombatSnapshot()
    local char = localSnapshot.Character
    local core = localSnapshot.Core
    local hum = core and core.Humanoid
    if not char or not hum or hum.Health <= 0 then return false end
    if not targetPart or not targetPart.Parent then return false end

    local heldTool = localSnapshot.Tool
    if heldTool and esLaPistola(heldTool) then return false end

    local gun = obtenerPistola()
    if not gun or gun.Parent == char then return false end

    mState.quickGunSerial = (mState.quickGunSerial or 0) + 1
    local serial = mState.quickGunSerial
    mState.quickGunBusy = true
    mState.quickGunTool = gun
    runtime.QuickGunFiring = false

    local equipped = pcall(function()
        hum:UnequipTools()
        hum:EquipTool(gun)
    end)
    mState.localCombatSnapshotReady = false

    if not equipped or gun.Parent ~= char then
        mState.quickGunBusy = false
        mState.quickGunTool = nil
        mState.quickGunNextAt = os.clock() + 0.15
        return false
    end

    task_delay(0.04, function()
        if serial ~= mState.quickGunSerial then return end

        local currentChar = player.Character
        local currentHum = currentChar and currentChar:FindFirstChildOfClass("Humanoid")
        if not runtime.Alive or not runtime.QuickGunEquipEnabled
            or currentChar ~= char or not currentHum or gun.Parent ~= currentChar then
            runtime.CancelQuickGunEquip(true)
            return
        end

        runtime.QuickGunFiring = true
        if targetPart and targetPart.Parent then
            pcall(runtime.ApplyDirectGunTarget, gun, targetPart)
        end

        pcall(function() gun:Activate() end)
        task_delay(0.02, function()
            if serial ~= mState.quickGunSerial then return end
            if gun.Parent == char then pcall(function() gun:Deactivate() end) end
            runtime.QuickGunFiring = false
        end)

        task_delay(0.055, function()
            if serial ~= mState.quickGunSerial then return end

            local finalChar = player.Character
            local finalHum = finalChar and finalChar:FindFirstChildOfClass("Humanoid")
            if finalChar == char and finalHum and gun.Parent == finalChar then
                pcall(function() finalHum:UnequipTools() end)
            end

            if serial == mState.quickGunSerial then
                runtime.QuickGunFiring = false
                mState.quickGunBusy = false
                mState.quickGunTool = nil
                mState.quickGunNextAt = os.clock() + 0.12
                mState.localCombatSnapshotReady = false
            end
        end)
    end)

    return true
end

runtime.QuickGunCleanup = function()
    runtime.QuickGunEquipEnabled = false
    runtime.CancelQuickGunEquip(true)
end

local enLobby = true
local timerLobby = 1

function runtime.GetCachedHitbox(char)
    if not char then return nil end
    local cached = mState.hbByChar[char]
    if cached and cached.Parent == char then return cached end
    mState.hbByChar[char] = nil

    if mState.hbLegacyScanned[char] then return nil end
    mState.hbLegacyScanned[char] = true
    for _, child in ipairs(char:GetChildren()) do
        if child:GetAttribute("EsAstraHitbox") then
            mState.hbByChar[char] = child
            return child
        end
    end
    return nil
end

function runtime.QueueHitboxDestroy(hitbox)
    if not hitbox or mState.hbCleanupPending[hitbox] then return end
    mState.hbCleanupPending[hitbox] = true

    pcall(function()
        local box = mState.hbAdornment[hitbox] or hitbox:FindFirstChild("AstraHitboxBox")
        if box then box.Visible = false end
        if hitbox:IsA("BasePart") then
            hitbox.CanTouch = false
            hitbox.CanQuery = false
            hitbox.CanCollide = false
            hitbox.Transparency = 1
        end
    end)
    mState.hbCleanupQueue[#mState.hbCleanupQueue + 1] = hitbox
    runtime.EnsureHitboxSpikeWorker()
end

function runtime.QueueHitboxCreate(targetPlayer, char, hrp)
    if not targetPlayer or not char or not hrp or mState.hbCreatePending[char] then return end
    if runtime.GetCachedHitbox(char) then return end
    mState.hbCreatePending[char] = true
    mState.hbCreateQueue[#mState.hbCreateQueue + 1] = {Player = targetPlayer, Character = char, HRP = hrp}
    runtime.EnsureHitboxSpikeWorker()
end

function runtime.CreateQueuedHitbox(entry)
    if not entry or not hitboxEnabled or enLobby then return nil end
    local targetPlayer = entry.Player
    local char = entry.Character
    local hrp = entry.HRP
    if not targetPlayer or targetPlayer.Character ~= char or not char or not char.Parent
        or not hrp or hrp.Parent ~= char then return nil end

    local core = getCharCore(char)
    local humanoid = core and core.Humanoid
    if not humanoid or humanoid.Health <= 0 or not isEnemy(targetPlayer) then return nil end

    local existing = runtime.GetCachedHitbox(char)
    if existing then return existing end

    local targetSize = Vector3_new(hitboxSize, hitboxSize, hitboxSize)
    local fakeHitbox = Instance.new("Part")
    fakeHitbox.Name = "Torso"
    fakeHitbox:SetAttribute("EsAstraHitbox", true)
    fakeHitbox.Shape = Enum.PartType.Block
    fakeHitbox.Size = targetSize
    fakeHitbox.CFrame = hrp.CFrame
    fakeHitbox.Massless = true
    fakeHitbox.CanCollide = false
    fakeHitbox.Anchored = false
    fakeHitbox.Transparency = 1
    fakeHitbox.Parent = char

    local weld = Instance.new("WeldConstraint")
    weld.Part0 = hrp
    weld.Part1 = fakeHitbox
    weld.Parent = fakeHitbox

    local box = Instance.new("BoxHandleAdornment")
    box.Name = "AstraHitboxBox"
    box.Adornee = fakeHitbox
    box.AlwaysOnTop = true
    box.ZIndex = 5
    box.Size = targetSize
    box.Color3 = mState.hbBlockedColor
    box.Transparency = hitboxInvisible and 1 or (hitboxTransparency or 0.6)
    box.Visible = not hitboxInvisible
    box.Parent = fakeHitbox

    mState.hbByChar[char] = fakeHitbox
    mState.hbAdornment[fakeHitbox] = box
    return fakeHitbox
end

function runtime.EnsureHitboxSpikeWorker()
    if mState.hbSpikeWorkerRunning then return end
    mState.hbSpikeWorkerRunning = true

    task.spawn(function()
        while runtime.Alive and (#mState.hbCleanupQueue > 0 or #mState.hbCreateQueue > 0) do
            RunService.Heartbeat:Wait()
            if not runtime.Alive then break end

            for _ = 1, 2 do
                local index = #mState.hbCleanupQueue
                if index == 0 then break end
                local hitbox = mState.hbCleanupQueue[index]
                mState.hbCleanupQueue[index] = nil
                mState.hbCleanupPending[hitbox] = nil
                mState.hbAdornment[hitbox] = nil
                if hitbox and hitbox.Parent then pcall(function() hitbox:Destroy() end) end
            end

            if #mState.hbCreateQueue > 0 and not mState.autoShootHeavyDue
                and not ((autoShootEnabled or autoShootCuchilloEnabled) and mState.tAS >= 0.12) then
                local index = #mState.hbCreateQueue
                local entry = mState.hbCreateQueue[index]
                mState.hbCreateQueue[index] = nil
                if entry and entry.Character then mState.hbCreatePending[entry.Character] = nil end
                runtime.CreateQueuedHitbox(entry)
            end

        end

        for i = 1, #mState.hbCreateQueue do
            local entry = mState.hbCreateQueue[i]
            if entry and entry.Character then mState.hbCreatePending[entry.Character] = nil end
        end
        table.clear(mState.hbCreateQueue)
        table.clear(mState.hbCleanupQueue)
        mState.hbSpikeWorkerRunning = false

        if runtime.Alive and (#mState.hbCleanupQueue > 0 or #mState.hbCreateQueue > 0) then
            runtime.EnsureHitboxSpikeWorker()
        end
    end)
end

do

local function installHitboxDeathCleanup(runtime, mState, Players, player, listaJugadores)

    mState.hbLifePlayers = setmetatable({}, {__mode = "k"})
    mState.hbLifeChars = setmetatable({}, {__mode = "k"})

    function runtime.CleanupHitboxCharacter(char)
        if not char then return end

        mState.hbCreatePending[char] = nil

        local cached = mState.hbByChar[char]
        if cached and cached.Parent then
            runtime.QueueHitboxDestroy(cached)
        end
        mState.hbByChar[char] = nil

        for _, child in ipairs(char:GetChildren()) do
            local isHitbox = false
            pcall(function()
                isHitbox = child:GetAttribute("EsAstraHitbox") == true
            end)
            if isHitbox then
                runtime.QueueHitboxDestroy(child)
            end
        end
    end

    function runtime.UnbindHitboxCharacterLifecycle(char)
        local bundle = char and mState.hbLifeChars[char]
        if not bundle then return end
        mState.hbLifeChars[char] = nil
        for _, connection in pairs(bundle) do
            if connection then pcall(function() connection:Disconnect() end) end
        end
    end

    function runtime.BindHitboxCharacterLifecycle(char)
        if not char or mState.hbLifeChars[char] then return end

        local bundle = {}
        mState.hbLifeChars[char] = bundle
        local boundHumanoid = nil

        local function bindHumanoid(humanoid)
            if not humanoid or not humanoid:IsA("Humanoid") or humanoid == boundHumanoid then return end
            boundHumanoid = humanoid

            if bundle.Died then pcall(function() bundle.Died:Disconnect() end) end
            if bundle.HealthChanged then pcall(function() bundle.HealthChanged:Disconnect() end) end

            bundle.Died = runtime.Track(humanoid.Died:Connect(function()
                runtime.CleanupHitboxCharacter(char)
            end))
            bundle.HealthChanged = runtime.Track(humanoid.HealthChanged:Connect(function(health)
                if health <= 0 then
                    runtime.CleanupHitboxCharacter(char)
                end
            end))
        end

        bindHumanoid(char:FindFirstChildOfClass("Humanoid"))

        bundle.ChildAdded = runtime.Track(char.ChildAdded:Connect(function(child)
            if child:IsA("Humanoid") then bindHumanoid(child) end
        end))

        bundle.AncestryChanged = runtime.Track(char.AncestryChanged:Connect(function(_, parent)
            if parent == nil then
                runtime.CleanupHitboxCharacter(char)
                runtime.UnbindHitboxCharacterLifecycle(char)
            end
        end))
    end

    function runtime.BindHitboxPlayerLifecycle(targetPlayer)
        if not targetPlayer or targetPlayer == player or mState.hbLifePlayers[targetPlayer] then return end

        local bundle = {}
        mState.hbLifePlayers[targetPlayer] = bundle

        bundle.CharacterAdded = runtime.Track(targetPlayer.CharacterAdded:Connect(function(char)
            runtime.BindHitboxCharacterLifecycle(char)
        end))

        bundle.CharacterRemoving = runtime.Track(targetPlayer.CharacterRemoving:Connect(function(char)

            runtime.CleanupHitboxCharacter(char)
            runtime.UnbindHitboxCharacterLifecycle(char)
        end))

        if targetPlayer.Character then
            runtime.BindHitboxCharacterLifecycle(targetPlayer.Character)
        end
    end

    for _, targetPlayer in ipairs(listaJugadores) do
        runtime.BindHitboxPlayerLifecycle(targetPlayer)
    end

    runtime.Track(Players.PlayerAdded:Connect(function(targetPlayer)
        runtime.BindHitboxPlayerLifecycle(targetPlayer)
    end))

    runtime.Track(Players.PlayerRemoving:Connect(function(targetPlayer)
        if targetPlayer and targetPlayer.Character then
            runtime.CleanupHitboxCharacter(targetPlayer.Character)
            runtime.UnbindHitboxCharacterLifecycle(targetPlayer.Character)
        end
        local bundle = targetPlayer and mState.hbLifePlayers[targetPlayer]
        if bundle then
            mState.hbLifePlayers[targetPlayer] = nil
            for _, connection in pairs(bundle) do
                if connection then pcall(function() connection:Disconnect() end) end
            end
        end
    end))

    runtime.HitboxCleanup = function()
        local seen = setmetatable({}, {__mode = "k"})

        local function destroyNow(hitbox)
            if not hitbox or seen[hitbox] then return end
            seen[hitbox] = true
            pcall(function()
                local box = mState.hbAdornment[hitbox] or hitbox:FindFirstChild("AstraHitboxBox")
                if box then box.Visible = false end
                if hitbox:IsA("BasePart") then
                    hitbox.CanTouch = false
                    hitbox.CanQuery = false
                    hitbox.CanCollide = false
                    hitbox.Transparency = 1
                end
                hitbox:Destroy()
            end)
        end

        for _, hitbox in pairs(mState.hbByChar) do
            destroyNow(hitbox)
        end
        for i = 1, #mState.hbCleanupQueue do
            destroyNow(mState.hbCleanupQueue[i])
        end

        for _, targetPlayer in ipairs(listaJugadores) do
            local char = targetPlayer ~= player and targetPlayer.Character or nil
            if char then
                for _, child in ipairs(char:GetChildren()) do
                    local isHitbox = false
                    pcall(function() isHitbox = child:GetAttribute("EsAstraHitbox") == true end)
                    if isHitbox then destroyNow(child) end
                end
            end
        end

        for char in pairs(mState.hbLifeChars) do
            runtime.UnbindHitboxCharacterLifecycle(char)
        end
        for targetPlayer, bundle in pairs(mState.hbLifePlayers) do
            mState.hbLifePlayers[targetPlayer] = nil
            for _, connection in pairs(bundle) do
                if connection then pcall(function() connection:Disconnect() end) end
            end
        end

        table.clear(mState.hbCreateQueue)
        table.clear(mState.hbCleanupQueue)
        table.clear(mState.hbByChar)
        table.clear(mState.hbAdornment)
        table.clear(mState.hbCreatePending)
        table.clear(mState.hbCleanupPending)
    end
end

installHitboxDeathCleanup(runtime, mState, Players, player, listaJugadores)
end

runtime.Track(RunService.Heartbeat:Connect(function(deltaTime)

    local masterFeatureActive = hitboxEnabled or espEnabled
        or autoShootEnabled or autoShootCuchilloEnabled
        or silentAimPistolaEnabled or silentAimCuchilloEnabled
        or runtime.QuickGunEquipEnabled
    local masterNeedsCleanup = mState.hbAct or mState.espAct or mState.asAct or mState.saAct or mState.quickGunAct
    if not masterFeatureActive and not masterNeedsCleanup then
        mState.tHB, mState.tESP, mState.tAS, mState.tSA, mState.tQuickGun = 0, 0, 0, 0, 0
        timerLobby = 1
        if aimHookState.Installed or aimHookState.Wanted or aimHookState.RoundActive then
            runtime.RefreshAimHooks(false)
        end
        return
    end

    mState.enemySnapshotReady = false
    mState.localCombatSnapshotReady = false
    local camera = workspace.CurrentCamera
    local deathEffectBusy = (runtime.DeathEffectBusyUntil or 0) > os.clock()
    timerLobby = timerLobby + deltaTime
    if timerLobby >= 0.25 then
        timerLobby = 0

        local okLobby, lobbyResult = pcall(estaEnLobby)
        enLobby = (not okLobby) or lobbyResult == true

        local okRound, inMatch = pcall(runtime.IsCombatRound)
        inMatch = okRound and inMatch == true or false
        if runtime.SyncTeamRoundState then runtime.SyncTeamRoundState(inMatch) end
        runtime.RefreshAimHooks(inMatch)
    end

    mState.autoShootHeavyDue = not deathEffectBusy
        and not enLobby
        and (autoShootEnabled or autoShootCuchilloEnabled)
        and (mState.tAS + deltaTime >= 0.15)

    if hitboxEnabled then
        mState.hbAct = true
        mState.tHB = mState.tHB + deltaTime
        if mState.tHB >= 0.15 and not mState.autoShootHeavyDue then
            mState.tHB = 0
            if not enLobby then
                local myChar = player.Character
                local myCore = myChar and getCharCore(myChar) or nil
                local myHead = myCore and myCore.Head
                local origin = camera.CFrame.Position
                local targetSize = Vector3_new(hitboxSize, hitboxSize, hitboxSize)
                mState.igHB[1] = myChar

                local enemies, enemyCount = runtime.GetEnemySnapshot()
                for i = 1, enemyCount do
                    local enemy = enemies[i]
                    local v = enemy.Player
                    local targetChar = enemy.Character
                    local targetCore = enemy.Core
                    local hrp = enemy.HRP
                    local targetPosition = enemy.Position
                    local targetHum = enemy.Humanoid

                    if enemy.Alive and enemy.Enemy then

                        local fakeHitbox = runtime.GetCachedHitbox(targetChar)
                        if not fakeHitbox then
                            runtime.QueueHitboxCreate(v, targetChar, hrp)
                            continue
                        end

                        if fakeHitbox.Size ~= targetSize then fakeHitbox.Size = targetSize end

                        local aLaVista = false
                        if myHead then
                            local rayDirection = targetPosition - origin
                            if rayDirection:Dot(rayDirection) < 62500 then
                                mState.igHB[2] = targetChar
                                mState.pHB.FilterDescendantsInstances = mState.igHB
                                local result = ws_Raycast(workspace, origin, rayDirection, mState.pHB)
                                aLaVista = not result
                            end
                        end

                        local targetColor = aLaVista and espColor or mState.hbBlockedColor

                        local currentTrans = hitboxTransparency or 0.6
                        local targetBoxTrans = hitboxInvisible and 1 or currentTrans

                        local box = mState.hbAdornment[fakeHitbox]
                        if not (box and box.Parent == fakeHitbox) then
                            box = fakeHitbox:FindFirstChild("AstraHitboxBox")
                            mState.hbAdornment[fakeHitbox] = box
                        end
                        if box then
                            if box.Size ~= fakeHitbox.Size then box.Size = fakeHitbox.Size end
                            if box.Color3 ~= targetColor then box.Color3 = targetColor end
                            if box.Transparency ~= targetBoxTrans then box.Transparency = targetBoxTrans end
                            if box.Visible ~= not hitboxInvisible then box.Visible = not hitboxInvisible end
                        end
                    elseif targetChar then

                        local cachedHitbox = runtime.GetCachedHitbox(targetChar)
                        if cachedHitbox then runtime.QueueHitboxDestroy(cachedHitbox) end
                        mState.hbByChar[targetChar] = nil
                    end
                end
            else

                for i = 1, #listaJugadores do
                    local v = listaJugadores[i]
                    if v ~= player and v.Character then
                        local cachedHitbox = runtime.GetCachedHitbox(v.Character)
                        if cachedHitbox then runtime.QueueHitboxDestroy(cachedHitbox) end
                        mState.hbByChar[v.Character] = nil
                    end
                end
            end
        end
    elseif mState.hbAct then
        mState.hbAct = false
        mState.tHB = 0

        for i = 1, #listaJugadores do
            local v = listaJugadores[i]
            if v ~= player and v.Character then
                local cachedHitbox = runtime.GetCachedHitbox(v.Character)
                if cachedHitbox then runtime.QueueHitboxDestroy(cachedHitbox) end
                mState.hbByChar[v.Character] = nil

                local hrp = v.Character:FindFirstChild("HumanoidRootPart")
                if hrp then
                    local box = hrp:FindFirstChild("AstraHitboxBox")
                    if box then box:Destroy() end
                    hrp.Transparency = 1
                end
            end
        end
    end

    if espEnabled then
        mState.espAct = true
    elseif mState.espAct then
        mState.espAct = false
        mState.tESP = 0
        runtime.HideAllESPGlow()
    end

    if autoShootEnabled or autoShootCuchilloEnabled then
        mState.asAct = true
        mState.tAS = mState.tAS + deltaTime
        if mState.tAS >= 0.15 and not deathEffectBusy and not mState.quickGunBusy then
            mState.tAS = 0
            if not enLobby then
                local localSnapshot = runtime.GetLocalCombatSnapshot()
                local char = localSnapshot.Character
                local localCore = localSnapshot.Core
                local hrp = localSnapshot.HRP
                if hrp then
                    local arma = localSnapshot.Tool

                    if arma and getWeaponHandleCached(arma) then
                        local esGun = esLaPistola(arma)
                        if (esGun and autoShootEnabled) or (not esGun and autoShootCuchilloEnabled) then
                            local myPos = localSnapshot.Position
                            local headPos = localSnapshot.HeadPosition or myPos

                            local closestTargetPart = nil
                            local closestTargetDistSq = math.huge
                            local visibilityNow = os.clock()

                            local enemies, enemyCount = runtime.GetEnemySnapshot()
                            for i = 1, enemyCount do
                                local enemy = enemies[i]
                                local enemyChar = enemy.Character
                                local enemyHrp = enemy.HRP
                                local enemyPosition = enemy.Position
                                if enemy.Alive and enemy.Enemy and enemyHrp and enemyPosition then
                                    local enemyDelta = enemyPosition - myPos
                                    if enemyDelta:Dot(enemyDelta) <= 640000 then
                                        local targetParts = runtime.CollectTargetParts(enemyChar, "AutoShoot")
                                        if targetParts then
                                            local aimParams = runtime.GetAimRayParams(char, enemyChar)
                                            local targetPartCount = #targetParts
                                            for j = 1, targetPartCount do
                                                local part = targetParts[j]
                                                local partPosition = part.Position
                                                local partDelta = partPosition - myPos
                                                local distSq = partDelta:Dot(partDelta)
                                                if distSq < closestTargetDistSq
                                                    and aimParams
                                                    and runtime.AimPartVisibleCached(part, enemyChar, char, headPos, partPosition, aimParams, visibilityNow) then
                                                    closestTargetDistSq = distSq
                                                    closestTargetPart = part
                                                end
                                            end
                                        end
                                    end
                                end
                            end

                            if closestTargetPart then
                                local aimReady = false
                                if esGun then

                                    aimHookState.Target = closestTargetPart

                                    aimReady = runtime.ApplyDirectGunTarget(arma, closestTargetPart)
                                else

                                    aimReady = runtime.EnsureAimHooksReady()
                                    if aimReady then aimHookState.Target = closestTargetPart end
                                end

                                if aimReady then
                                    pcall(function()
                                        arma:Activate()
                                        task_delay(0.02, function() if arma.Parent == char then arma:Deactivate() end end)
                                    end)
                                end
                            elseif not silentAimPistolaEnabled and not silentAimCuchilloEnabled then
                                aimHookState.Target = nil
                            end
                        elseif not silentAimPistolaEnabled and not silentAimCuchilloEnabled then aimHookState.Target = nil end
                    elseif not silentAimPistolaEnabled and not silentAimCuchilloEnabled then aimHookState.Target = nil end
                elseif not silentAimPistolaEnabled and not silentAimCuchilloEnabled then aimHookState.Target = nil end
            elseif not silentAimPistolaEnabled and not silentAimCuchilloEnabled then aimHookState.Target = nil end
        end
    elseif mState.asAct then
        mState.asAct = false
        mState.tAS = 0
        if not silentAimPistolaEnabled and not silentAimCuchilloEnabled then aimHookState.Target = nil end
    end

    if runtime.QuickGunEquipEnabled then
        mState.quickGunAct = true
        mState.tQuickGun = mState.tQuickGun + deltaTime

        if enLobby then
            if mState.quickGunBusy then runtime.CancelQuickGunEquip(true) end
        elseif mState.tQuickGun >= 0.08 and not deathEffectBusy
            and not runtime.MacroBusy and not mState.quickGunBusy
            and os.clock() >= (mState.quickGunNextAt or 0) then
            mState.tQuickGun = 0
            local quickGunTarget = runtime.QuickGunHasVisibleEnemy(camera)
            if quickGunTarget then
                runtime.StartQuickGunEquipPulse(quickGunTarget)
            end
        end
    elseif mState.quickGunAct then
        mState.quickGunAct = false
        runtime.CancelQuickGunEquip(true)
    end

    if silentAimPistolaEnabled or silentAimCuchilloEnabled then
        mState.saAct = true
        mState.tSA = mState.tSA + deltaTime

        if mState.tSA >= 0.03 and not deathEffectBusy and not mState.autoShootHeavyDue then
            mState.tSA = 0
            if not enLobby then
                local localSnapshot = runtime.GetLocalCombatSnapshot()
                local char = localSnapshot.Character
                local localCore = localSnapshot.Core
                local hrp = localSnapshot.HRP
                if hrp then
                    local arma = localSnapshot.Tool
                    local allowedWeapon = false
                    local esGun = false
                    if arma then
                        esGun = esLaPistola(arma)
                        if (esGun and silentAimPistolaEnabled) or (not esGun and silentAimCuchilloEnabled) then
                            allowedWeapon = true
                        end
                    end

                    if allowedWeapon then
                        local closestTargetPart = nil
                        local shortestDistToCenter = math.huge
                        local shortestDistanceFisica = math.huge
                        local myPos = localSnapshot.Position
                        local headPos = localSnapshot.HeadPosition or myPos

                        local centerX, centerY, fovSq, broadFovSq
                        if silentAimFovEnabled then
                            local viewport = camera.ViewportSize
                            if viewport.X ~= mState.vpX or viewport.Y ~= mState.vpY then
                                mState.vpX, mState.vpY = viewport.X, viewport.Y
                                mState.centerX, mState.centerY = viewport.X * 0.5, viewport.Y * 0.5
                            end
                            if mState.fovCacheRadius ~= fovRadius then
                                mState.fovCacheRadius = fovRadius
                                mState.fovSq = fovRadius * fovRadius
                                local broadFov = fovRadius + 150
                                mState.broadFovSq = broadFov * broadFov
                            end
                            centerX, centerY = mState.centerX, mState.centerY
                            fovSq, broadFovSq = mState.fovSq, mState.broadFovSq
                        end

                        local visibilityNow = os.clock()

                        local enemies, enemyCount = runtime.GetEnemySnapshot()
                        for i = 1, enemyCount do
                            local enemy = enemies[i]
                            local enemyChar = enemy.Character
                            local enemyHrp = enemy.HRP
                            local enemyPosition = enemy.Position
                            if enemy.Alive and enemy.Enemy and enemyHrp and enemyPosition then
                                local enemyDelta = enemyPosition - myPos
                                if enemyDelta:Dot(enemyDelta) <= 640000 then
                                    local enemyScreenPos, enemyOnScreen
                                    if silentAimFovEnabled then
                                        enemyScreenPos, enemyOnScreen = camera:WorldToViewportPoint(enemyPosition)
                                        local dx, dy = enemyScreenPos.X - centerX, enemyScreenPos.Y - centerY
                                        if not enemyOnScreen or (dx * dx + dy * dy) > broadFovSq then continue end
                                    end

                                    local targetParts = runtime.CollectTargetParts(enemyChar, "SilentAim")
                                    if targetParts then

                                        local aimParams = runtime.GetAimRayParams(char, enemyChar)
                                        local targetPartCount = #targetParts
                                        for j = 1, targetPartCount do
                                            local part = targetParts[j]
                                            local partPosition = part.Position
                                            local pasaFiltro = false
                                            local candidateDistance = math.huge

                                            if silentAimFovEnabled then

                                                local partPos2D, onScreen
                                                if part == enemyHrp then
                                                    partPos2D, onScreen = enemyScreenPos, enemyOnScreen
                                                else
                                                    partPos2D, onScreen = camera:WorldToViewportPoint(partPosition)
                                                end
                                                if onScreen then
                                                    local dx, dy = partPos2D.X - centerX, partPos2D.Y - centerY
                                                    candidateDistance = dx * dx + dy * dy
                                                    if candidateDistance <= fovSq and candidateDistance < shortestDistToCenter then pasaFiltro = true end
                                                end
                                            else
                                                local partDelta = partPosition - myPos
                                                candidateDistance = partDelta:Dot(partDelta)
                                                if candidateDistance < shortestDistanceFisica then pasaFiltro = true end
                                            end

                                            if pasaFiltro and aimParams
                                                and runtime.AimPartVisibleCached(part, enemyChar, char, headPos, partPosition, aimParams, visibilityNow) then
                                                if silentAimFovEnabled then shortestDistToCenter = candidateDistance else shortestDistanceFisica = candidateDistance end
                                                closestTargetPart = part
                                            end
                                        end
                                    end
                                end
                            end
                        end
                        if closestTargetPart then
                            if esGun then

                                aimHookState.Target = closestTargetPart
                                runtime.ApplyDirectGunTarget(arma, closestTargetPart)
                            else
                                if runtime.EnsureAimHooksReady() then
                                    aimHookState.Target = closestTargetPart
                                end
                            end
                        elseif not autoShootEnabled and not autoShootCuchilloEnabled then aimHookState.Target = nil end
                    elseif not autoShootEnabled and not autoShootCuchilloEnabled then aimHookState.Target = nil end
                elseif not autoShootEnabled and not autoShootCuchilloEnabled then aimHookState.Target = nil end
            end
        end
    elseif mState.saAct then
        mState.saAct = false
        mState.tSA = 0
        if not autoShootEnabled and not autoShootCuchilloEnabled then aimHookState.Target = nil end
    end
end))

UIElements.TogAutoShoot = Tabs.Aim:Toggle({
    Title = "Auto Shoot",
    Desc = "Dispara automáticamente a la parte del cuerpo seleccionada.",
    Value = false,
    Callback = function(Value)
        autoShootEnabled = Value
        runtime.RefreshAimHooks()
        if Value and mState.equippedTool and esLaPistola(mState.equippedTool) then
            task.defer(runtime.ResolveDirectGunShoot, mState.equippedTool)
        end
        if not autoShootEnabled and not silentAimPistolaEnabled then
            runtime.ClearDirectGunCache()
        end
        showBottomMessage(Value and "Auto Shoot: ACTIVADO" or "Auto Shoot: DESACTIVADO")

    end,
})

UIElements.TogAutoShootCuchillo = Tabs.Aim:Toggle({
    Title = "Auto Shoot (Cuchillo)",
    Desc = "Ataca o lanza el cuchillo automáticamente.",
    Value = false,
    Callback = function(Value)
        autoShootCuchilloEnabled = Value
        runtime.RefreshAimHooks()

    end,
})

Tabs.Aim:Button({
    Title = "Selector corporal · Auto Shoot",
