    Value = false,
    Callback = function(Value)
        silentAimPistolaEnabled = Value
        runtime.RefreshAimHooks()
        if Value and mState.equippedTool and esLaPistola(mState.equippedTool) then
            task.defer(runtime.ResolveDirectGunShoot, mState.equippedTool)
        end
        if not autoShootEnabled and not silentAimPistolaEnabled then
            runtime.ClearDirectGunCache()
        end
        showBottomMessage(Value and "Silent Aim Pistola: ACTIVADO" or "Silent Aim Pistola: DESACTIVADO")

