})

local silentAimKey = nil
Tabs.Aim:Section({Title = "Selección y controles"})
Tabs.Aim:Input({
    Title = "Tecla para Activar/Desactivar Silent Aim",
    Placeholder = "Escribe una letra (Ej: Q, E, R...)",
    Callback = function(Text)
        if Text and Text ~= "" then
            silentAimKey = string.upper(Text)
            showBottomMessage("Tecla Silent Aim asignada a: " .. silentAimKey)
        else
            silentAimKey = nil
        end
    end
})

runtime.Track(UserInputService.InputBegan:Connect(function(input, processed)

    if processed then return end

    if input.UserInputType == Enum.UserInputType.Keyboard and silentAimKey then
        if input.KeyCode.Name == silentAimKey then

            local newState = not silentAimPistolaEnabled

            silentAimPistolaEnabled = newState
            silentAimCuchilloEnabled = newState

            pcall(function() UIElements.TogSilentAimPistola:Set(newState) end)
            pcall(function() UIElements.TogSilentAimCuchillo:Set(newState) end)

            pcall(function()
                if saBtn then
                    if newState then
                        saBtn.Text = "Silent Aim: ON"
                        saBtn.TextColor3 = Color3.fromHex("#DCE0E5")
                        if saStroke then saStroke.Color = Color3.fromRGB(255, 255, 255) end
                    else
                        saBtn.Text = "Silent Aim: OFF"
                        saBtn.TextColor3 = Color3.fromHex("#F3F4F5")
                        if saStroke then saStroke.Color = Color3.fromHex("#464B52") end
                    end
                end
            end)

            showBottomMessage(newState and "Silent Aim: ACTIVADO ["..silentAimKey.."]" or "Silent Aim: DESACTIVADO ["..silentAimKey.."]")
        end
    end
end))

Tabs.Aim:Button({
    Title = "Selector corporal · Silent Aim",
    Desc = "Selecciona cabeza, torso, brazos y piernas con multiselección visual.",
    Callback = function() runtime.OpenBodySelector("SilentAim") end,
})

UIElements.TogSilentAimFOV = Tabs.Aim:Toggle({
    Title = "Filtro de círculo FOV",
    Desc = "Silent Aim solo considera objetivos dentro del círculo configurado.",
    Value = false,
    Callback = function(Value)
        silentAimFovEnabled = Value
        showBottomMessage(Value and "Filtro FOV: ACTIVADO" or "Filtro FOV: DESACTIVADO")
    end,
})

UIElements.TogShowFOV = Tabs.Aim:Toggle({
    Title = "Mostrar Círculo FOV",
    Desc = "Dibuja un círculo en pantalla para saber dónde funciona tu Silent Aim.",
    Value = false,
    Callback = function(Value)
        fovVisiblePreference = Value
        if runtime.UpdateESP2DRenderConnection then runtime.UpdateESP2DRenderConnection() end
    end,
})

Tabs.Aim:Section({Title = "Campo de visión"})
UIElements.SliFOVSize = Tabs.Aim:Slider({
    Title = "Tamaño del FOV",
    Step = 1,
    Value = {Min = 10, Max = 800, Default = 120},
    Callback = function(v) fovRadius = v end
})

Tabs.KillAll:Section({
    Title = "Kill All · En mantenimiento"
})

Tabs.KillAll:Paragraph({
    Title = "En mantenimiento",
    Desc = "Kill All está desactivado temporalmente mientras se mejora su estabilidad."
})

do
local KillRunService = game:GetService("RunService")

local killAllEnabled = false
local killAllBaseCFrame = nil
local killAllIdleFree = false
local killAllBaseCharacter = nil

local killAllResting = false
local killAllRestCharacter = nil

local killAllWasSafe = false

KILL_RANGE = 600
local KILL_RANGE_SQ = KILL_RANGE * KILL_RANGE

VULNERABLE_STABLE_TIME = 0.10

ATTACK_Y_OFFSET = -2.55

local ARRIVAL_TIMEOUT = 1.20

local HRP_READY_DISTANCE = 5.0
local HANDLE_READY_DISTANCE = 4.8

local HANDLE_STABLE_TIME = 0.05

local PRE_HIT_HOLD_TIME = 0.03

local KILL_CONFIRM_TIME = 1.15

local FAILED_RETRY_DELAY = 0.10

local failedTargets = {}

function freezeKillRoot(hrp)
    if not hrp or not hrp.Parent then
        return
    end

    hrp.AssemblyLinearVelocity = Vector3.zero
    hrp.AssemblyAngularVelocity = Vector3.zero
end

function estaEnZonaSeguraKillAll(
    char,
    targetPlayer
)
    if not char or not char.Parent then
        return true
    end

    if char:FindFirstChildOfClass(
        "ForceField"
    ) then
        return true
    end

    if targetPlayer
        and targetPlayer.Team
    then

        local teamName =
            string.lower(
                targetPlayer.Team.Name
            )

        if string.find(
            teamName,
            "lobby"
        )
            or string.find(
                teamName,
                "spectat"
            )
            or string.find(
                teamName,
                "espectador"
            )
            or string.find(
                teamName,
                "menu"
            )
            or string.find(
                teamName,
                "dead"
            )
        then
            return true
        end
    end

    local hrp =
        char:FindFirstChild(
            "HumanoidRootPart"
        )

    if hrp then

        local pos =
            hrp.Position

        for i = 1, #ZONAS_SEGURAS do

            local zona =
                ZONAS_SEGURAS[i]

            local delta = pos - zona.Centro
            if delta:Dot(delta) <= zona.RadioSq then
                return true
            end
        end
    end

    return false
end

local PROTECTION_ATTRIBUTES = {
    "Invulnerable",
    "Protected",
    "SpawnProtected",
    "SpawnProtection",
    "NoDamage",
    "DamageProtected"
}

local PROTECTION_VALUES = {
    "Invulnerable",
    "Protected",
    "SpawnProtected",
    "SpawnProtection",
    "NoDamage"
}

local function tieneProteccionKillAll(char)
    if not char or not char.Parent then
        return true
    end

    if char:FindFirstChildOfClass(
        "ForceField"
    ) then
        return true
    end

    for _, attributeName
        in ipairs(
            PROTECTION_ATTRIBUTES
        )
    do

        local value =
            char:GetAttribute(
                attributeName
            )

        if value == true then
            return true
        end
    end

    for _, valueName
        in ipairs(
            PROTECTION_VALUES
        )
    do

        local object =
            char:FindFirstChild(
                valueName,
                true
            )

        if object
            and object:IsA(
                "BoolValue"
            )
            and object.Value == true
        then
            return true
        end
    end

    return false
end

local function estaVulnerableKillAll(
    char,
    targetPlayer
)
    if not char or not char.Parent then
        return false
    end

    if estaEnZonaSeguraKillAll(
        char,
        targetPlayer
    ) then
        return false
    end

    local hum =
        char:FindFirstChildOfClass(
            "Humanoid"
        )

    local hrp =
        char:FindFirstChild(
            "HumanoidRootPart"
        )

    if not hum or not hrp then
        return false
    end

    if hum.Health <= 0 then
        return false
    end

    if tieneProteccionKillAll(
        char
    ) then
        return false
    end

    if hrp.Anchored then
        return false
    end

    if hum.WalkSpeed <= 0 then
        return false
    end

    return true
end

local function esperarVulnerabilidadKillAll(
    char,
    targetPlayer
)
    local stableSince = nil

    while runtime.Alive
        and killAllEnabled
        and char
        and char.Parent
    do

        local hum =
            char:FindFirstChildOfClass(
                "Humanoid"
            )

        if not hum
            or hum.Health <= 0
        then
            return false
        end

        if estaEnZonaSeguraKillAll(
            char,
            targetPlayer
        ) then
            return false
        end

        if estaVulnerableKillAll(
            char,
            targetPlayer
        ) then

            if not stableSince then

                stableSince =
                    os.clock()

            elseif (
                os.clock()
                - stableSince
            ) >= VULNERABLE_STABLE_TIME
            then

                return true
            end

        else

            stableSince =
                nil
        end

        task.wait(0.03)
    end

    return false
end

local KNIFE_WORDS = {
    "knife",
    "cuchillo",
    "blade",
    "dagger",
    "kunai"
}

local function esCuchilloKillAll(tool)
    if not tool
        or not tool:IsA(
            "Tool"
        )
    then
        return false
    end

    if tool:FindFirstChild(
        "KnifeClient",
        true
    )
        or tool:FindFirstChild(
            "KnifeServer",
            true
        )
        or tool:FindFirstChild(
            "Throw",
            true
        )
        or tool:FindFirstChild(
            "Kill",
            true
        )
    then
        return true
    end

    local nombre =
        string.lower(
            tool.Name
        )

    for _, word
        in ipairs(
            KNIFE_WORDS
        )
    do

        if string.find(
            nombre,
            word,
            1,
            true
        ) then
            return true
        end
    end

    return false
end

local function obtenerCuchilloKillAll(
    char,
    hum
)
    if not char or not hum then
        return nil
    end

    for _, tool
        in ipairs(
            char:GetChildren()
        )
    do

        if esCuchilloKillAll(
            tool
        ) then
            return tool
        end
    end

    local backpack =
        player:FindFirstChild(
            "Backpack"
        )

    if not backpack then
        return nil
    end

    local currentTool =
        char:FindFirstChildOfClass(
            "Tool"
        )

    if currentTool
        and not esCuchilloKillAll(
            currentTool
        )
    then

        pcall(function()
            hum:UnequipTools()
        end)

        KillRunService.
            Heartbeat:Wait()
    end

    for _, tool
        in ipairs(
            backpack:GetChildren()
        )
    do

        if esCuchilloKillAll(
            tool
        ) then

            pcall(function()
                hum:EquipTool(
                    tool
                )
            end)

            local deadline =
                os.clock() + 0.65

            while runtime.Alive
                and killAllEnabled
                and tool.Parent ~= char
                and os.clock() < deadline
            do

                KillRunService.
                    Heartbeat:Wait()
            end

            if tool.Parent == char then

                KillRunService.
                    Heartbeat:Wait()

                KillRunService.
                    Heartbeat:Wait()

                return tool
            end
        end
    end

    return nil
end

local function obtenerHandleKillAll(
    arma
)
    if not arma then
        return nil
    end

    local handle =
        arma:FindFirstChild(
            "Handle",
            true
        )

    if handle
        and handle:IsA(
            "BasePart"
        )
    then
        return handle
    end

    for _, object
        in ipairs(
            arma:GetDescendants()
        )
    do

        if object:IsA(
            "BasePart"
        ) then
            return object
        end
    end

    return nil
end

local function obtenerParteObjetivoKillAll(
    char
)
    if not char then
        return nil
    end

    local upperTorso =
        char:FindFirstChild(
            "UpperTorso"
        )

    if upperTorso
        and upperTorso:IsA(
            "BasePart"
        )
    then
        return upperTorso
    end

    local torso =
        char:FindFirstChild(
            "Torso"
        )

    if torso
        and torso:IsA(
            "BasePart"
        )
    then
        return torso
    end

    return char:FindFirstChild(
        "HumanoidRootPart"
    )
end

local function obtenerAttackCFKillAll(
    enemyHrp
)
    if not enemyHrp
        or not enemyHrp.Parent
    then
        return nil
    end

    return enemyHrp.CFrame
        * CFrame.new(
            0,
            ATTACK_Y_OFFSET,
            0
        )
        * CFrame.Angles(
           math.rad(90),
            0,
            0
        )
end

local function liberarReposoKillAll(
    hum,
    hrp
)
    if hum
        and hum.Parent
    then

        pcall(function()
            hum.PlatformStand =
                false

            hum.AutoRotate =
                true

            hum:ChangeState(
                Enum.HumanoidStateType.GettingUp
            )
        end)
    end

    freezeKillRoot(
        hrp
    )

    killAllResting =
        false

    killAllRestCharacter =
        nil
end

local function liberarMovimientoKillAll(
    myHum,
    myHrp
)
    if myHum
        and myHum.Parent
    then

        pcall(function()

            myHum.PlatformStand =
                false

            myHum.AutoRotate =
                true

            myHum:ChangeState(
                Enum.HumanoidStateType.GettingUp
            )
        end)
    end

    if myHrp
        and myHrp.Parent
    then

        freezeKillRoot(
            myHrp
        )
    end

    killAllResting =
        false

    killAllRestCharacter =
        nil

    killAllIdleFree =
        true
end

local function reposarEnBaseKillAll(
    myChar,
    myHum,
    myHrp
)
    if not myChar
        or not myChar.Parent
        or not myHum
        or not myHum.Parent
        or not myHrp
        or not myHrp.Parent
        or not killAllBaseCFrame
    then
        return
    end

    if killAllRestCharacter
        ~= myChar
    then

        killAllResting =
            false
    end

    if not killAllResting then

        local basePose =
            killAllBaseCFrame
            * CFrame.Angles(
                math.rad(90),
                0,
                0
            )

        pcall(function()
            myChar:PivotTo(
                basePose
            )
        end)

        freezeKillRoot(
            myHrp
        )

        pcall(function()

            myHum.AutoRotate =
                false

            myHum.PlatformStand =
                true

            myHum:ChangeState(
                Enum.HumanoidStateType.Physics
            )
        end)

        killAllResting =
            true

        killAllRestCharacter =
            myChar

    else

        freezeKillRoot(
            myHrp
        )
    end
end

local function contactoRealKillAll(
    myHrp,
    arma,
    enemyChar
)
    if not myHrp
        or not myHrp.Parent
        or not arma
        or not arma.Parent
        or not enemyChar
        or not enemyChar.Parent
    then
        return false
    end

    local targetPart =
        obtenerParteObjetivoKillAll(
            enemyChar
        )

    if not targetPart then
        return false
    end

    local hrpDistance =
        (
            myHrp.Position
            - targetPart.Position
        ).Magnitude

    local handle =
        obtenerHandleKillAll(
            arma
        )

    local handleDistance =
        math.huge

    if handle
        and handle.Parent
    then

        handleDistance =
            (
                handle.Position
                - targetPart.Position
            ).Magnitude

    else

        handleDistance =
            hrpDistance
    end

    return (
        hrpDistance
        <= HRP_READY_DISTANCE
    )
        and (
            handleDistance
            <= HANDLE_READY_DISTANCE
        )
end

local function seguirObjetivoKillAll(
    myChar,
    myHrp,
    enemyHrp
)
    if not myChar
        or not myChar.Parent
        or not myHrp
        or not myHrp.Parent
        or not enemyHrp
        or not enemyHrp.Parent
    then
        return false
    end

    local attackCF =
        obtenerAttackCFKillAll(
            enemyHrp
        )

    if not attackCF then
        return false
    end

    pcall(function()

        myChar:PivotTo(
            attackCF
        )
    end)

    freezeKillRoot(
        myHrp
    )

    return true
end

local function esperarContactoKillAll(
    myChar,
    myHrp,
    arma,
    targetPlayer,
    enemyChar,
    enemyHrp
)
    local deadline =
        os.clock()
        + ARRIVAL_TIMEOUT

    local stableSince =
        nil

    while runtime.Alive
        and killAllEnabled
        and myChar
        and myChar.Parent
        and myHrp
        and myHrp.Parent
        and arma
        and arma.Parent
        and enemyChar
        and enemyChar.Parent
        and enemyHrp
        and enemyHrp.Parent
        and os.clock() < deadline
    do

        local enemyHum =
            enemyChar:
                FindFirstChildOfClass(
                    "Humanoid"
                )

        if not enemyHum
            or enemyHum.Health <= 0
        then
            return false
        end

        if estaEnZonaSeguraKillAll(
            enemyChar,
            targetPlayer
        ) then
            return false
        end

        seguirObjetivoKillAll(
            myChar,
            myHrp,
            enemyHrp
        )

        KillRunService.
            Heartbeat:Wait()

        if contactoRealKillAll(
            myHrp,
            arma,
            enemyChar
        ) then

            if not stableSince then

                stableSince =
                    os.clock()

            elseif (
                os.clock()
                - stableSince
            ) >= HANDLE_STABLE_TIME
            then

                return true
            end

        else

            stableSince =
                nil
        end
    end

    return false
end

local function holdAntesGolpeKillAll(
    myChar,
    myHrp,
    arma,
    targetPlayer,
    enemyChar,
    enemyHrp
)
    local started =
        os.clock()

    while runtime.Alive
        and killAllEnabled
        and (
            os.clock()
            - started
        ) < PRE_HIT_HOLD_TIME
    do

        local enemyHum =
            enemyChar
            and enemyChar:
                FindFirstChildOfClass(
                    "Humanoid"
                )

        if not enemyHum
            or enemyHum.Health <= 0
        then
            return false
        end

        if estaEnZonaSeguraKillAll(
            enemyChar,
            targetPlayer
        ) then
            return false
        end

        if not estaVulnerableKillAll(
            enemyChar,
            targetPlayer
        ) then
            return false
        end

        seguirObjetivoKillAll(
            myChar,
            myHrp,
            enemyHrp
        )

        KillRunService.
            Heartbeat:Wait()

        if not contactoRealKillAll(
            myHrp,
            arma,
            enemyChar
        ) then
            return false
        end
    end

    return true
end

local function esperarMuerteKillAll(
    myChar,
    myHrp,
    targetPlayer,
    enemyChar,
    enemyHum,
    enemyHrp
)
    local murio =
        false

    local diedConnection =
        enemyHum.Died:Connect(
            function()

                murio =
                    true
            end
        )

    local deadline =
        os.clock()
        + KILL_CONFIRM_TIME

    while runtime.Alive
        and killAllEnabled
        and os.clock() < deadline
    do

        if murio
            or (
                enemyHum
                and enemyHum.Health <= 0
            )
        then

            murio =
                true

            break
        end

        if not enemyHum
            or not enemyHum.Parent
        then
            break
        end

        if estaEnZonaSeguraKillAll(
            enemyChar,
            targetPlayer
        ) then
            break
        end

        if enemyHrp
            and enemyHrp.Parent
        then

            seguirObjetivoKillAll(
                myChar,
                myHrp,
                enemyHrp
            )
        end

        KillRunService.
            Heartbeat:Wait()
    end

    if diedConnection then

        pcall(function()
            diedConnection:
                Disconnect()
        end)
    end

    if enemyHum
        and enemyHum.Parent
        and enemyHum.Health <= 0
    then

        murio =
            true
    end

    return murio
end

local function atacarUnaVezKillAll(
    targetPlayer,
    myChar,
    myHum,
    myHrp
)
    if not targetPlayer
        or targetPlayer == player
        or not targetPlayer.Character
    then
        return false
    end

    local enemyChar =
        targetPlayer.Character

    local enemyHum =
        enemyChar:
            FindFirstChildOfClass(
                "Humanoid"
            )

    local enemyHrp =
        enemyChar:
            FindFirstChild(
                "HumanoidRootPart"
            )

    if not enemyHum
        or not enemyHrp
        or enemyHum.Health <= 0
    then
        return false
    end

    if estaEnZonaSeguraKillAll(
        enemyChar,
        targetPlayer
    ) then
        return false
    end

    local retryAt =
        failedTargets[
            targetPlayer
        ]

    if retryAt
        and os.clock() < retryAt
    then
        return false
    end

    local referenceCF =
        killAllBaseCFrame
        or myHrp.CFrame

    local rangeDelta = referenceCF.Position - enemyHrp.Position
    if rangeDelta:Dot(rangeDelta) > KILL_RANGE_SQ then
        return false
    end

    local vulnerable =
        esperarVulnerabilidadKillAll(
            enemyChar,
            targetPlayer
        )

    if not vulnerable then
        return false
    end

    enemyChar =
        targetPlayer.Character

    if not enemyChar then
        return false
    end

    enemyHum =
        enemyChar:
            FindFirstChildOfClass(
                "Humanoid"
            )

    enemyHrp =
        enemyChar:
            FindFirstChild(
                "HumanoidRootPart"
            )

    if not enemyHum
        or not enemyHrp
        or enemyHum.Health <= 0
        or estaEnZonaSeguraKillAll(
            enemyChar,
            targetPlayer
        )
    then
        return false
    end

    liberarReposoKillAll(
        myHum,
        myHrp
    )

    local arma =
        obtenerCuchilloKillAll(
            myChar,
            myHum
        )

    if not arma then
        reposarEnBaseKillAll(myChar, myHum, myHrp)
        return false
    end

    pcall(function()
        if runtime.ArmNativeDeathTarget then
            runtime.ArmNativeDeathTarget(enemyChar, arma)
        end
    end)

    pcall(function()
        if arma and arma.Parent == myChar then
            arma:Activate()
        end
    end)

    task.wait(0.15)

    local contacto =
        esperarContactoKillAll(
            myChar,
            myHrp,
            arma,
            targetPlayer,
            enemyChar,
            enemyHrp
        )

    if not contacto then

        reposarEnBaseKillAll(
            myChar,
            myHum,
            myHrp
        )

        failedTargets[
            targetPlayer
        ] =
            os.clock()
            + FAILED_RETRY_DELAY

        return false
    end

    local holdOk =
        holdAntesGolpeKillAll(
            myChar,
            myHrp,
            arma,
            targetPlayer,
            enemyChar,
            enemyHrp
        )

    if not holdOk then

        contacto =
            esperarContactoKillAll(
                myChar,
                myHrp,
                arma,
                targetPlayer,
                enemyChar,
                enemyHrp
            )

        if contacto then

            holdOk =
                holdAntesGolpeKillAll(
                    myChar,
                    myHrp,
                    arma,
                    targetPlayer,
                    enemyChar,
                    enemyHrp
                )
        end
    end

    if not holdOk then

        reposarEnBaseKillAll(
            myChar,
            myHum,
            myHrp
        )

        failedTargets[
            targetPlayer
        ] =
            os.clock()
            + FAILED_RETRY_DELAY

        return false
    end

    seguirObjetivoKillAll(
        myChar,
        myHrp,
        enemyHrp
    )

    KillRunService.
        Heartbeat:Wait()

    if not contactoRealKillAll(
        myHrp,
        arma,
        enemyChar
    ) then

        contacto =
            esperarContactoKillAll(
                myChar,
                myHrp,
                arma,
                targetPlayer,
                enemyChar,
                enemyHrp
            )

        if not contacto then

            reposarEnBaseKillAll(
                myChar,
                myHum,
                myHrp
            )

            failedTargets[
                targetPlayer
            ] =
                os.clock()
                + FAILED_RETRY_DELAY

            return false
        end
    end

    if not estaVulnerableKillAll(
        enemyChar,
        targetPlayer
    ) then

        reposarEnBaseKillAll(
            myChar,
            myHum,
            myHrp
        )

        return false
    end

    local murio =
        esperarMuerteKillAll(
            myChar,
            myHrp,
            targetPlayer,
            enemyChar,
            enemyHum,
            enemyHrp
        )

    pcall(function()

        if arma
            and arma.Parent == myChar
        then

            arma:Deactivate()
        end
    end)

    reposarEnBaseKillAll(
        myChar,
        myHum,
        myHrp
    )

    if murio then

        failedTargets[
            targetPlayer
        ] =
            nil

    else

        failedTargets[
            targetPlayer
        ] =
            os.clock()
            + FAILED_RETRY_DELAY
    end

    return murio
end

end

