do
local isWorkspaceLooping = false
local originalData = setmetatable({}, {__mode = "k"})
runtime.VisualConnections = runtime.VisualConnections or {}
runtime.VisualTextConnections = runtime.VisualTextConnections or setmetatable({}, {__mode = "k"})
runtime.VisualInitialScanDone = false

local function isSpoofTextObject(v)
    return v and (v:IsA("TextLabel") or v:IsA("TextBox") or v:IsA("TextButton"))
end

local function isHubTextObject(v)
    local parentGui = v and v:FindFirstAncestorWhichIsA("ScreenGui")
    if not parentGui then return false end
    local guiName = tostring(parentGui.Name or "")
    return string.find(guiName, "WindUI", 1, true) ~= nil
        or string.find(guiName, "iLunX", 1, true) ~= nil
        or string.find(guiName, "Onyx", 1, true) ~= nil
        or string.find(guiName, "XeroHub", 1, true) ~= nil
end

local function safeReplace(str, find, replace)
    str, find, replace = tostring(str or ""), tostring(find or ""), tostring(replace or "")
    if find == "" then return str end
    local safeFind = find:gsub("[%-%^%$%(%)%%%.%[%]%*%+%?]", "%%%1")
    return (str:gsub(safeFind, replace))
end

local function restoreStrokeState(data)
    for stroke, strokeData in pairs((data and data.Strokes) or {}) do
        if stroke and stroke.Parent then
            stroke.Enabled = strokeData.Enabled
            stroke.Transparency = strokeData.Transp
            stroke.Thickness = strokeData.Thickness
        end
    end
end

local function restoreTextState(v, data)
    if not v or not v.Parent or not data then return end
    v.Text = data.Text
    v.TextColor3 = data.Color
    v.TextTransparency = data.TextTransp
    v.TextStrokeTransparency = data.StrokeTransp
    if data.RichText ~= nil then v.RichText = data.RichText end
    restoreStrokeState(data)
end

local function processText(v, myName, myDisp)
    if not isSpoofTextObject(v) or isHubTextObject(v) then return end

    local txt = tostring(v.Text or "")
    local hasName = txt ~= "" and (
        string.find(txt, myName, 1, true) ~= nil
        or string.find(txt, myDisp, 1, true) ~= nil
    )

    if hasName and not originalData[v] then
        local data = {
            Text = txt,
            Color = v.TextColor3,
            TextTransp = v.TextTransparency,
            StrokeTransp = v.TextStrokeTransparency,
            RichText = v.RichText,
            Strokes = {},
        }
        for _, obj in ipairs(v:GetChildren()) do
            if obj:IsA("UIStroke") then
                data.Strokes[obj] = {
                    Enabled = obj.Enabled,
                    Transp = obj.Transparency,
                    Thickness = obj.Thickness,
                }
            end
        end
        originalData[v] = data
    end

    local data = originalData[v]
    if not data then return end

    if hideNameEnabled then
        v.Text = " "
        v.TextTransparency = 1
        v.TextStrokeTransparency = 1
        for _, obj in ipairs(v:GetChildren()) do
            if obj:IsA("UIStroke") then
                obj.Enabled = false
                obj.Transparency = 1
                obj.Thickness = 0
            end
        end
        return
    end

    if fakeNameEnabled or creatorTagEnabled then
        local newText = data.Text
        local baseName = fakeNameEnabled and spoofNameText or myDisp
        newText = string.gsub(newText, "%[VIP%] ", "")
        newText = string.gsub(newText, "%[VIP%]", "")
        newText = string.gsub(newText, '<font color="#bee1e7">%[Content Creator%]</font> ', "")
        newText = string.gsub(newText, "%[Content Creator%] ", "")
        newText = string.gsub(newText, "%[Content Creator%]", "")

        local isOverheadTag = false
        if player.Character then
            if v:IsDescendantOf(player.Character) then
                isOverheadTag = true
            else
                local parentGui = v:FindFirstAncestorWhichIsA("BillboardGui")
                if parentGui and parentGui.Adornee and parentGui.Adornee:IsDescendantOf(player.Character) then
                    isOverheadTag = true
                end
            end
        end

        local finalName = baseName
        if creatorTagEnabled and isOverheadTag then
            v.RichText = true
            finalName = '<font color="#bee1e7">[Content Creator]</font> ' .. baseName
        else
            v.RichText = data.RichText
        end

        newText = safeReplace(newText, myName, finalName)
        newText = safeReplace(newText, myDisp, finalName)
        v.Text = newText
        v.TextTransparency = data.TextTransp
        v.TextStrokeTransparency = data.StrokeTransp
        restoreStrokeState(data)
        v.TextColor3 = rainbowEnabled and Color3.fromHSV(tick() % 4 / 4, 1, 1) or data.Color
        return
    end

    restoreTextState(v, data)
    if rainbowEnabled then
        v.TextColor3 = Color3.fromHSV(tick() % 4 / 4, 1, 1)
    end
end

local function disconnectVisualTextConnections()
    for v, connection in pairs(runtime.VisualTextConnections) do
        if connection then pcall(function() connection:Disconnect() end) end
        if v then
            pcall(function() v:SetAttribute("AstraInfectado", nil) end)
            runtime.InfectedTexts[v] = nil
        end
        runtime.VisualTextConnections[v] = nil
    end
end

local function infectarTextoSeguro(v)
    if not isWorkspaceLooping or not isSpoofTextObject(v) or isHubTextObject(v) then return end

    local myName = player.Name
    local myDisp = player.DisplayName
    processText(v, myName, myDisp)

    if runtime.VisualTextConnections[v] then return end
    pcall(function() v:SetAttribute("AstraInfectado", true) end)
    runtime.TrackInfectedText(v)

    local connection
    connection = runtime.Track(v:GetPropertyChangedSignal("Text"):Connect(function()
        if not isWorkspaceLooping or not v.Parent then return end
        local currentText = tostring(v.Text or "")
        if currentText == " " or currentText == spoofNameText
            or string.find(currentText, spoofNameText, 1, true)
            or string.find(currentText, "[Content Creator]", 1, true) then
            return
        end

        local currentName = player.Name
        local currentDisplay = player.DisplayName
        if string.find(currentText, currentName, 1, true)
            or string.find(currentText, currentDisplay, 1, true) then

            originalData[v] = nil
            processText(v, currentName, currentDisplay)
        end
    end))
    runtime.VisualTextConnections[v] = connection
end

local function scanExistingSpoofTexts()
    task.spawn(function()
        for _, p in ipairs(listaJugadores) do
            if not isWorkspaceLooping then return end
            local character = p.Character
            if character then
                for _, v in ipairs(character:GetDescendants()) do
                    if isSpoofTextObject(v) then infectarTextoSeguro(v) end
                end
            end
        end

        if not isWorkspaceLooping then return end
        local pGui = player:FindFirstChild("PlayerGui")
        if pGui then
            for _, v in ipairs(pGui:GetDescendants()) do
                if isSpoofTextObject(v) then infectarTextoSeguro(v) end
            end
        end
    end)
end

local function startVisualWatchers()
    if isWorkspaceLooping then return end
    isWorkspaceLooping = true
    runtime.VisualInitialScanDone = true

    local pGui = player:FindFirstChild("PlayerGui")
    if pGui then
        table.insert(runtime.VisualConnections, runtime.Track(pGui.DescendantAdded:Connect(function(nuevoObjeto)
            if isWorkspaceLooping and isSpoofTextObject(nuevoObjeto) then
                infectarTextoSeguro(nuevoObjeto)
            end
        end)))
    end

    local successCore, coreGui = pcall(function() return game:GetService("CoreGui") end)
    if successCore and coreGui then
        table.insert(runtime.VisualConnections, runtime.Track(coreGui.DescendantAdded:Connect(function(nuevoObjeto)
            if isWorkspaceLooping and isSpoofTextObject(nuevoObjeto) then
                infectarTextoSeguro(nuevoObjeto)
            end
        end)))
    end

    scanExistingSpoofTexts()
end

local function stopVisualWatchersAndRestore()

    isWorkspaceLooping = false
    runtime.VisualInitialScanDone = false

    for _, conn in ipairs(runtime.VisualConnections) do
        pcall(function() conn:Disconnect() end)
    end
    table.clear(runtime.VisualConnections)
    disconnectVisualTextConnections()

    for v, data in pairs(originalData) do
        restoreTextState(v, data)
        originalData[v] = nil
    end

    originalData = setmetatable({}, {__mode = "k"})
    runtime.PruneConnections()

    local char = player.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function() hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.Viewer end)
    end
end

function updateSystem()
    local visualActive = hideNameEnabled or fakeNameEnabled or rainbowEnabled or creatorTagEnabled

    if not visualActive then
        stopVisualWatchersAndRestore()
        return
    end

    if not isWorkspaceLooping then
        startVisualWatchers()
        return
    end

    local myName = player.Name
    local myDisp = player.DisplayName
    for v in pairs(originalData) do
        if v and v.Parent then
            processText(v, myName, myDisp)
        else
            originalData[v] = nil
        end
    end
end

runtime.VisualSpoofCleanup = function()
    hideNameEnabled = false
    fakeNameEnabled = false
    rainbowEnabled = false
    creatorTagEnabled = false
    stopVisualWatchersAndRestore()
end
end

