do
local FOVCircle = runtime.TrackDrawing(Drawing.new("Circle"))
FOVCircle.Filled = false
FOVCircle.Color = Color3.fromRGB(255, 255, 255)
FOVCircle.Visible = false
FOVCircle.Thickness = 2.6
FOVCircle.NumSides = 96
local lastFOVDrawX, lastFOVDrawY = nil, nil
local lastFOVDrawRadius = nil
local lastFOVDrawColor = nil

local tracerLines = {}
local tracersLimpios = true
local espRenderAccumulator = 0
local espLabelFollowAccumulator = 0
local espTargetRefreshAccumulator = 999

local espDistanceTextAccumulator = 999

local ESP_RENDER_FAST_INTERVAL = 1 / 30

local ESP_RENDER_LABEL_INTERVAL = 1 / 20
local ESP_LABEL_FOLLOW_INTERVAL = 1 / 60
local ESP_RENDER_GLOW_INTERVAL = 1 / 8
local ESP_TARGET_REFRESH_INTERVAL = 0.12
local ESP_DISTANCE_TEXT_INTERVAL = 0.10
local ESP_PIXEL_EPSILON = 0.25
local MAX_ESP_DISTANCE_SQ = MAX_ESP_DISTANCE * MAX_ESP_DISTANCE
local lastESPLabelCameraCFrame = nil

local function espPixelChanged(oldValue, newValue)
    return oldValue == nil or math.abs(oldValue - newValue) >= ESP_PIXEL_EPSILON
end

local cachedViewportX, cachedViewportY = -1, -1
local centroVector = Vector2_new(0, 0)
local tracerOrigin = Vector2_new(0, 0)
local fovIdleColor = Color3_fromRGB(255, 255, 255)
local fovTargetColor = Color3_fromRGB(0, 255, 0)
local esp2dClean = true

runtime.ESP2D = {}
runtime.ESPTargetCache = {}
runtime.ESPTargetCount = 0

local function getESPVisualInterval()
    if fovVisiblePreference or espLinesEnabled
        or (espEnabled and (espSettings.Box or espSettings.HealthBar)) then
        return ESP_RENDER_FAST_INTERVAL
    end
    if espEnabled and (espSettings.Name or espSettings.Distance) then
        return ESP_RENDER_LABEL_INTERVAL
    end
    return ESP_RENDER_GLOW_INTERVAL
end

function runtime.HideESP2DEntry(entry)
    if not entry then return end
    if entry.Box and entry.Box.Visible then entry.Box.Visible = false end
    if entry.HealthBg and entry.HealthBg.Visible then entry.HealthBg.Visible = false end
    if entry.Health and entry.Health.Visible then entry.Health.Visible = false end
    if entry.NameText and entry.NameText.Visible then entry.NameText.Visible = false end
    if entry.DistanceText and entry.DistanceText.Visible then entry.DistanceText.Visible = false end

    entry.LastBoxX, entry.LastBoxY, entry.LastBoxW, entry.LastBoxH = nil, nil, nil, nil
    entry.LastHealthBgX, entry.LastHealthBgTop, entry.LastHealthBgBottom = nil, nil, nil
    entry.LastHealthX, entry.LastHealthBottom, entry.LastHealthTop = nil, nil, nil
end

function runtime.HideAllESP2D()
    if esp2dClean then return end
    for _, entry in pairs(runtime.ESP2D) do
        runtime.HideESP2DEntry(entry)
    end
    esp2dClean = true
end

function runtime.GetESP2DEntry(p)
    local entry = runtime.ESP2D[p]
    if entry then return entry end
    entry = {
        LastBoxColor = nil,
        LastNameText = nil,
        LastNameColor = nil,
        LastDistanceText = nil,
        LastHealth = nil,
        LastMaxHealth = nil,

        LastBoxX = nil, LastBoxY = nil, LastBoxW = nil, LastBoxH = nil,
        LastHealthBgX = nil, LastHealthBgTop = nil, LastHealthBgBottom = nil,
        LastHealthX = nil, LastHealthBottom = nil, LastHealthTop = nil,
    }

    local okBox, box = pcall(function() return Drawing.new("Square") end)
    if okBox and box then
        box.Filled = false
        box.Thickness = 1.5
        box.Transparency = 1
        box.Visible = false
        runtime.TrackDrawing(box)
        entry.Box = box
    end

    local healthBg = runtime.TrackDrawing(Drawing.new("Line"))
    healthBg.Thickness = 4
    healthBg.Transparency = 0.65
    healthBg.Color = Color3.fromRGB(0, 0, 0)
    healthBg.Visible = false
    entry.HealthBg = healthBg

    local health = runtime.TrackDrawing(Drawing.new("Line"))
    health.Thickness = 2
    health.Transparency = 1
    health.Visible = false
    entry.Health = health

    local nameText = runtime.TrackDrawing(Drawing.new("Text"))
    nameText.Center = true
    nameText.Outline = true
    nameText.OutlineColor = Color3.fromRGB(0, 0, 0)
    nameText.Size = 14
    nameText.Transparency = 1
    nameText.Visible = false
    entry.NameText = nameText

    local distanceText = runtime.TrackDrawing(Drawing.new("Text"))
    distanceText.Center = true
    distanceText.Outline = true
    distanceText.OutlineColor = Color3.fromRGB(0, 0, 0)
    distanceText.Size = 12
    distanceText.Transparency = 0.95
    distanceText.Color = Color3.fromRGB(189, 195, 199)
    distanceText.Visible = false
    entry.DistanceText = distanceText

    runtime.ESP2D[p] = entry
    return entry
end

local function hideTracersOnce()
    if tracersLimpios then return end
    for _, tLine in pairs(tracerLines) do
        if tLine.Visible then tLine.Visible = false end
    end
    tracersLimpios = true
end

function runtime.RefreshESPTargetCache()
    local cache = runtime.ESPTargetCache
    local previousCount = runtime.ESPTargetCount or 0
    local count = 0

    if not espEnabled or enLobby then
        for i = 1, previousCount do cache[i] = nil end
        runtime.ESPTargetCount = 0
        runtime.HideAllESPGlow()
        return
    end

    local myChar = player.Character
    local myCore = myChar and getCharCore(myChar) or nil
    local myRoot = myCore and myCore.HRP
    local myPos = myRoot and myRoot.Position or workspace.CurrentCamera.CFrame.Position
    local queryContext = runtime.PrepareEnemyQueryContext()

    for i = 1, #listaJugadores do
        local p = listaJugadores[i]
        if p ~= player then
            count = count + 1
            local entry = cache[count]
            if not entry then
                entry = {}
                cache[count] = entry
            end

            local char = p.Character
            local core = char and getCharCore(char) or nil
            local hrp = core and core.HRP or nil
            local hum = core and core.Humanoid or nil
            local alive = hrp ~= nil and hum ~= nil and hum.Health > 0
            local eligible = false

            if entry.Player ~= p or entry.Character ~= char then
                entry.LabelProjectionReady = false
                entry.LabelOnScreen = false
                entry.LastLabelWorldPosition = nil
                entry.LabelScreenX = nil
                entry.LabelBaseY = nil
                entry.RootProjectionReady = false
                entry.LastRootCameraCFrame = nil
                entry.LastRootWorldPosition = nil
                entry.LastRootScreen = nil
                entry.LastRootOnScreen = false
            end

            if alive and isEnemy(p, queryContext) and not enemigoEnLobby(char, hrp, core) then
                local delta = myPos - hrp.Position
                eligible = delta:Dot(delta) <= MAX_ESP_DISTANCE_SQ
            end

            entry.Player = p
            entry.Character = char
            entry.Core = core
            entry.HRP = hrp
            entry.Humanoid = hum
            entry.Head = core and core.Head or nil
            entry.Eligible = eligible

            if espSettings.Glow then
                runtime.SyncESPGlow(p, char, eligible)
            elseif activeESPs[p] then
                hideESP(p)
            end
        end
    end

    for i = count + 1, previousCount do
        cache[i] = nil
    end
    runtime.ESPTargetCount = count
end

function runtime.UpdateESPLabelPositions(camera)
    if not espEnabled or enLobby or not (espSettings.Name or espSettings.Distance) then return end

    local cache = runtime.ESPTargetCache
    local targetCount = runtime.ESPTargetCount or 0
    local cameraCFrame = camera.CFrame
    local cameraUnchanged = lastESPLabelCameraCFrame ~= nil and lastESPLabelCameraCFrame == cameraCFrame

    for i = 1, targetCount do
        local target = cache[i]
        local p = target and target.Player
        local entry = p and runtime.ESP2D[p] or nil

        if target and target.Eligible then
            local char = target.Character
            local hrp = target.HRP
            local hum = target.Humanoid
            local refsValid = p and p.Parent == Players
                and char and char.Parent
                and hrp and hrp.Parent == char
                and hum and hum.Parent == char and hum.Health > 0

            if refsValid then
                local anchor = target.Head
                if not anchor or anchor.Parent ~= char then
                    local core = target.Core
                    anchor = core and core.Head or nil
                    target.Head = anchor
                end

                local worldPos = anchor and anchor.Position or hrp.Position
                local projectionReused = cameraUnchanged
                    and target.LabelProjectionReady == true
                    and target.LastLabelWorldPosition == worldPos

                local onScreen = target.LabelOnScreen == true
                local screenX = target.LabelScreenX
                local baseY = target.LabelBaseY

                if not projectionReused then
                    local screenPos, projectedOnScreen = camera:WorldToViewportPoint(worldPos)
                    onScreen = projectedOnScreen and screenPos.Z > 0.05
                    screenX = screenPos.X
                    baseY = screenPos.Y - (anchor and 18 or 34)

                    target.LabelProjectionReady = true
                    target.LastLabelWorldPosition = worldPos
                    target.LabelOnScreen = onScreen
                    target.LabelScreenX = screenX
                    target.LabelBaseY = baseY
                end

                if onScreen then
                    local y = baseY
                    if entry and espSettings.Name and entry.NameText then
                        if espPixelChanged(entry.LastNameX, screenX) or espPixelChanged(entry.LastNameY, y) then
                            entry.NameText.Position = Vector2_new(screenX, y)
                            entry.LastNameX, entry.LastNameY = screenX, y
                        end
                        y = y + 15
                    elseif espSettings.Name then
                        y = y + 15
                    end
                    if entry and espSettings.Distance and entry.DistanceText then
                        if espPixelChanged(entry.LastDistanceX, screenX) or espPixelChanged(entry.LastDistanceY, y) then
                            entry.DistanceText.Position = Vector2_new(screenX, y)
                            entry.LastDistanceX, entry.LastDistanceY = screenX, y
                        end
                    end
                elseif entry then
                    if entry.NameText and entry.NameText.Visible then entry.NameText.Visible = false end
                    if entry.DistanceText and entry.DistanceText.Visible then entry.DistanceText.Visible = false end
                end
            else
                target.LabelProjectionReady = false
                target.LabelOnScreen = false
            end
        end
    end

    lastESPLabelCameraCFrame = cameraCFrame
end

function runtime.RenderESP2D(deltaTime)
    espRenderAccumulator = espRenderAccumulator + deltaTime
    espLabelFollowAccumulator = espLabelFollowAccumulator + deltaTime
    espTargetRefreshAccumulator = espTargetRefreshAccumulator + deltaTime
    espDistanceTextAccumulator = espDistanceTextAccumulator + deltaTime

    local camera = workspace.CurrentCamera
    local interval = getESPVisualInterval()
    local renderDue = espRenderAccumulator >= interval

    if espLabelFollowAccumulator >= ESP_LABEL_FOLLOW_INTERVAL then
        espLabelFollowAccumulator = 0

        runtime.UpdateESPLabelPositions(camera)
    end

    if not renderDue then return end

    espRenderAccumulator = 0

    local distanceTextDue = espSettings.Distance and espDistanceTextAccumulator >= ESP_DISTANCE_TEXT_INTERVAL
    if distanceTextDue then espDistanceTextAccumulator = 0 end

    local wantsESPVisuals = espEnabled and (
        espSettings.Glow or espSettings.Name or espSettings.Distance
        or espSettings.Box or espSettings.HealthBar
    )

    if not fovVisiblePreference and not espLinesEnabled and not wantsESPVisuals then
        if FOVCircle.Visible then FOVCircle.Visible = false end
        hideTracersOnce()
        runtime.HideAllESP2D()
        runtime.HideAllESPGlow()
        return
    end

    local viewport = camera.ViewportSize
    if viewport.X ~= cachedViewportX or viewport.Y ~= cachedViewportY then
        cachedViewportX, cachedViewportY = viewport.X, viewport.Y
        centroVector = Vector2_new(viewport.X * 0.5, viewport.Y * 0.5)
        tracerOrigin = Vector2_new(centroVector.X, viewport.Y - 2)
    end

    if fovVisiblePreference then
        if lastFOVDrawX ~= centroVector.X or lastFOVDrawY ~= centroVector.Y then
            FOVCircle.Position = centroVector
            lastFOVDrawX, lastFOVDrawY = centroVector.X, centroVector.Y
        end
        if lastFOVDrawRadius ~= fovRadius then
            FOVCircle.Radius = fovRadius
            lastFOVDrawRadius = fovRadius
        end
        local wantedFOVColor = aimHookState.Target and fovTargetColor or fovIdleColor
        if lastFOVDrawColor ~= wantedFOVColor then
            FOVCircle.Color = wantedFOVColor
            lastFOVDrawColor = wantedFOVColor
        end
        if not FOVCircle.Visible then FOVCircle.Visible = true end
    elseif FOVCircle.Visible then
        FOVCircle.Visible = false
    end

    if not espEnabled or enLobby then
        hideTracersOnce()
        runtime.HideAllESP2D()
        runtime.HideAllESPGlow()
        return
    end

    if espTargetRefreshAccumulator >= ESP_TARGET_REFRESH_INTERVAL then
        espTargetRefreshAccumulator = 0
        runtime.RefreshESPTargetCache()
    end

    local wantsLabels = espSettings.Name or espSettings.Distance
    local wantsBodyGeometry = espSettings.Box or espSettings.HealthBar
    local wantsAny2D = wantsLabels or wantsBodyGeometry
    local labelsOnly = wantsLabels and not wantsBodyGeometry and not espLinesEnabled

    tracersLimpios = not espLinesEnabled

    if not espLinesEnabled and not wantsAny2D then
        hideTracersOnce()
        runtime.HideAllESP2D()
        return
    end

    local myPos = nil
    local cameraCFrame = camera.CFrame

    local cache = runtime.ESPTargetCache
    local targetCount = runtime.ESPTargetCount or 0

    for i = 1, targetCount do
        local target = cache[i]
        local p = target.Player
        local char = target.Character
        local core = target.Core
        local hrp = target.HRP
        local hum = target.Humanoid

        local eligible = target.Eligible
            and p and p.Parent == Players
            and char and char.Parent
            and hrp and hrp.Parent == char
            and hum and hum.Parent == char and hum.Health > 0

        local valid = false
        local rootScreen
        if eligible then
            if labelsOnly and target.LabelProjectionReady then
                valid = target.LabelOnScreen == true
            else
                local rootPosition = hrp.Position
                if target.RootProjectionReady
                    and target.LastRootCameraCFrame == cameraCFrame
                    and target.LastRootWorldPosition == rootPosition then
                    rootScreen = target.LastRootScreen
                    valid = target.LastRootOnScreen == true
                else
                    local onScreen
                    rootScreen, onScreen = camera:WorldToViewportPoint(rootPosition)
                    valid = onScreen and rootScreen.Z > 0
                    target.RootProjectionReady = true
                    target.LastRootCameraCFrame = cameraCFrame
                    target.LastRootWorldPosition = rootPosition
                    target.LastRootScreen = rootScreen
                    target.LastRootOnScreen = valid
                end
            end
        elseif p and activeESPs[p] then

            hideESP(p)
        end

        local tLine = p and tracerLines[p] or nil
        if espLinesEnabled and valid then
            if not tLine then
                tLine = runtime.TrackDrawing(Drawing.new("Line"))
                tLine.Thickness = 1.35
                tLine.Transparency = 0.92
                tLine.Visible = false
                tracerLines[p] = tLine
            end
            tLine.From = tracerOrigin
            tLine.To = Vector2_new(rootScreen.X, rootScreen.Y)
            if tLine.Color ~= espColor then tLine.Color = espColor end
            tLine.Visible = true
        elseif tLine and tLine.Visible then
            tLine.Visible = false
        end

        local entry = p and runtime.ESP2D[p] or nil
        if wantsAny2D and valid then
            esp2dClean = false
            entry = entry or runtime.GetESP2DEntry(p)

            local labelX = labelsOnly and target.LabelScreenX or rootScreen.X
            local labelY = labelsOnly and target.LabelBaseY or (rootScreen.Y - 34)
            local bodyGeometryValid = false
            local boxX, boxY, boxW, boxH

            if wantsBodyGeometry then
                local head = target.Head
                if (not head or head.Parent ~= char) and core then
                    head = core.Head
                    target.Head = head
                end

                local up = hrp.CFrame.UpVector
                local topWorld = head and (head.Position + up * (head.Size.Y * 0.55))
                    or (hrp.Position + up * 2.8)

                local leftFoot = core and core.LeftFoot
                local rightFoot = core and core.RightFoot
                local bottomWorld
                if leftFoot or rightFoot then
                    local lfPoint = leftFoot and (leftFoot.Position - up * (leftFoot.Size.Y * 0.5)) or nil
                    local rfPoint = rightFoot and (rightFoot.Position - up * (rightFoot.Size.Y * 0.5)) or nil
                    if lfPoint and rfPoint then
                        bottomWorld = ((lfPoint - hrp.Position):Dot(up) < (rfPoint - hrp.Position):Dot(up)) and lfPoint or rfPoint
                    else
                        bottomWorld = lfPoint or rfPoint
                    end
                else
                    bottomWorld = hrp.Position - up * ((hum.HipHeight or 2) + hrp.Size.Y * 0.5)
                end

                local topScreen = camera:WorldToViewportPoint(topWorld)
                local bottomScreen = camera:WorldToViewportPoint(bottomWorld)
                bodyGeometryValid = topScreen.Z > 0.05 and bottomScreen.Z > 0.05

                if bodyGeometryValid then
                    local rawH = math.abs(bottomScreen.Y - topScreen.Y)
                    local maxH = math.max(8, viewport.Y * 0.92)
                    boxH = math.clamp(rawH, 8, maxH)
                    local ratioW = hum.RigType == Enum.HumanoidRigType.R6 and 0.62 or 0.55
                    boxW = math.clamp(boxH * ratioW, 6, math.max(6, viewport.X * 0.62))
                    boxX = rootScreen.X - boxW * 0.5
                    boxY = math.min(topScreen.Y, bottomScreen.Y)
                    labelY = boxY - 18
                end
            elseif wantsLabels and not labelsOnly then

                local head = target.Head
                if head and head.Parent == char then
                    local headScreen = camera:WorldToViewportPoint(head.Position)
                    if headScreen.Z > 0.05 then
                        labelY = headScreen.Y - 18
                    end
                end
            end

            if entry.Box then
                if espSettings.Box and bodyGeometryValid then
                    if espPixelChanged(entry.LastBoxX, boxX) or espPixelChanged(entry.LastBoxY, boxY) then
                        entry.Box.Position = Vector2_new(boxX, boxY)
                        entry.LastBoxX, entry.LastBoxY = boxX, boxY
                    end
                    if espPixelChanged(entry.LastBoxW, boxW) or espPixelChanged(entry.LastBoxH, boxH) then
                        entry.Box.Size = Vector2_new(boxW, boxH)
                        entry.LastBoxW, entry.LastBoxH = boxW, boxH
                    end
                    if entry.LastBoxColor ~= espColor then
                        entry.Box.Color = espColor
                        entry.LastBoxColor = espColor
                    end
                    if not entry.Box.Visible then entry.Box.Visible = true end
                elseif entry.Box.Visible then
                    entry.Box.Visible = false
                end
            end

            if espSettings.HealthBar and bodyGeometryValid then
                local healthValue = hum.Health
                local maxHealth = math.max(hum.MaxHealth, 1)
                local ratio = math.clamp(healthValue / maxHealth, 0, 1)
                local bx = boxX - 5
                local byBottom = boxY + boxH
                local byHealth = byBottom - (boxH * ratio)

                local healthBgXChanged = espPixelChanged(entry.LastHealthBgX, bx)
                local healthXChanged = espPixelChanged(entry.LastHealthX, bx)
                if healthBgXChanged or espPixelChanged(entry.LastHealthBgTop, boxY) then
                    entry.HealthBg.From = Vector2_new(bx, boxY)
                    entry.LastHealthBgTop = boxY
                end
                if healthBgXChanged or espPixelChanged(entry.LastHealthBgBottom, byBottom) then
                    entry.HealthBg.To = Vector2_new(bx, byBottom)
                    entry.LastHealthBgBottom = byBottom
                end
                entry.LastHealthBgX = bx
                if not entry.HealthBg.Visible then entry.HealthBg.Visible = true end

                if healthXChanged or espPixelChanged(entry.LastHealthBottom, byBottom) then
                    entry.Health.From = Vector2_new(bx, byBottom)
                    entry.LastHealthBottom = byBottom
                end
                if healthXChanged or espPixelChanged(entry.LastHealthTop, byHealth) then
                    entry.Health.To = Vector2_new(bx, byHealth)
                    entry.LastHealthTop = byHealth
                end
                entry.LastHealthX = bx
                if entry.LastHealth ~= healthValue or entry.LastMaxHealth ~= maxHealth then
                    entry.Health.Color = Color3.fromHSV(ratio * 0.33, 0.92, 1)
                    entry.LastHealth = healthValue
                    entry.LastMaxHealth = maxHealth
                end
                if not entry.Health.Visible then entry.Health.Visible = true end
            else
                if entry.HealthBg.Visible then entry.HealthBg.Visible = false end
                if entry.Health.Visible then entry.Health.Visible = false end
            end

            if not wantsBodyGeometry and wantsLabels then
                if espSettings.Name and entry.NameText then
                    if espPixelChanged(entry.LastNameX, labelX) or espPixelChanged(entry.LastNameY, labelY) then
                        entry.NameText.Position = Vector2_new(labelX, labelY)
                        entry.LastNameX, entry.LastNameY = labelX, labelY
                    end
                    labelY = labelY + 15
                end
                if espSettings.Distance and entry.DistanceText then
                    if espPixelChanged(entry.LastDistanceX, labelX) or espPixelChanged(entry.LastDistanceY, labelY) then
                        entry.DistanceText.Position = Vector2_new(labelX, labelY)
                        entry.LastDistanceX, entry.LastDistanceY = labelX, labelY
                    end
                end

                labelY = (target.Head and target.Head.Parent == char) and labelY or labelY
            end

            if espSettings.Name and entry.NameText then
                local currentName = p.Name
                if entry.LastNameText ~= currentName then
                    entry.NameText.Text = currentName
                    entry.LastNameText = currentName
                end
                if entry.LastNameColor ~= espColor then
                    entry.NameText.Color = espColor
                    entry.LastNameColor = espColor
                end
                if not entry.NameText.Visible then entry.NameText.Visible = true end
                if wantsBodyGeometry then labelY = labelY + 15 end
            elseif entry.NameText and entry.NameText.Visible then
                entry.NameText.Visible = false
            end

            if espSettings.Distance and entry.DistanceText then
                if distanceTextDue or entry.LastDistanceText == nil then
                    if not myPos then
                        local myChar = player.Character
                        local myCore = myChar and getCharCore(myChar) or nil
                        local myRoot = myCore and myCore.HRP
                        myPos = myRoot and myRoot.Position or cameraCFrame.Position
                    end
                    local delta = myPos - hrp.Position
                    local distanceInt = math_floor(math.sqrt(delta:Dot(delta)))
                    local distanceString = tostring(distanceInt) .. "m"
                    if entry.LastDistanceText ~= distanceString then
                        entry.DistanceText.Text = distanceString
                        entry.LastDistanceText = distanceString
                    end
                end
                if not entry.DistanceText.Visible then entry.DistanceText.Visible = true end
            elseif entry.DistanceText and entry.DistanceText.Visible then
                entry.DistanceText.Visible = false
            end
        elseif entry then
            runtime.HideESP2DEntry(entry)
        end
    end
end

runtime.ESP2DRenderConnection = nil
function runtime.UpdateESP2DRenderConnection()
    local wantsESP2D = fovVisiblePreference
        or (espEnabled and (
            espLinesEnabled or espSettings.Glow or espSettings.Name
            or espSettings.Distance or espSettings.Box or espSettings.HealthBar
        ))
    local connection = runtime.ESP2DRenderConnection

    if wantsESP2D then
        local connected = false
        if connection then
            pcall(function() connected = connection.Connected == true end)
        end

        espTargetRefreshAccumulator = 999
        espDistanceTextAccumulator = 999
        lastESPLabelCameraCFrame = nil
        if not connected then
            runtime.ESP2DRenderConnection = runtime.Track(RunService.RenderStepped:Connect(runtime.RenderESP2D))
        end
        return
    end

    if connection then
        pcall(function() connection:Disconnect() end)
        runtime.ESP2DRenderConnection = nil
        runtime.PruneConnections()
    end
    espRenderAccumulator = 0
    espLabelFollowAccumulator = 0
    espTargetRefreshAccumulator = 999
    espDistanceTextAccumulator = 999
    lastESPLabelCameraCFrame = nil
    if FOVCircle.Visible then FOVCircle.Visible = false end
    hideTracersOnce()
    runtime.HideAllESP2D()
    runtime.HideAllESPGlow()
end
runtime.UpdateESP2DRenderConnection()

runtime.Track(Players.PlayerRemoving:Connect(function(p)
    if tracerLines[p] then
        runtime.RemoveDrawing(tracerLines[p])
        tracerLines[p] = nil
    end
    local entry = runtime.ESP2D[p]
    if entry then
        runtime.RemoveDrawing(entry.Box)
        runtime.RemoveDrawing(entry.HealthBg)
        runtime.RemoveDrawing(entry.Health)
        runtime.RemoveDrawing(entry.NameText)
        runtime.RemoveDrawing(entry.DistanceText)
        runtime.ESP2D[p] = nil
    end
    cleanESP(p)
    espTargetRefreshAccumulator = 999
end))

end

