autoLoadToggle = Tabs.Config:Toggle({
    Title = "Auto Load Config",
    Desc = "Carga automáticamente la configuración seleccionada al ejecutar XeroHub.",
    Value = autoLoadEnabled,
    Callback = function(Value)
        if autoLoadSyncing then return end

        if Value then
            if selectedConfig == "" or selectedConfig == "Ninguna" then
                autoLoadEnabled = false
                autoLoadConfigName = nil
                saveAutoLoadState()
                showBottomMessage("Selecciona una configuración antes de activar Auto Load.", {
                    title = "XeroHub · Config",
                    key = "config:autoload",
                })

                task.defer(function()
                    if not autoLoadToggle then return end
                    local wasSuppressed = runtime.SuppressNotifications
                    runtime.SuppressNotifications = true
                    autoLoadSyncing = true
                    pcall(function() autoLoadToggle:Set(false) end)
                    autoLoadSyncing = false
                    runtime.SuppressNotifications = wasSuppressed
                end)
                return
            end

            autoLoadEnabled = true
            autoLoadConfigName = selectedConfig
            saveAutoLoadState()
            showBottomMessage("Auto Load: " .. selectedConfig, {
                title = "XeroHub · Config",
                key = "config:autoload",
            })
        else
            autoLoadEnabled = false
            saveAutoLoadState()
            showBottomMessage("Auto Load desactivado.", {
                title = "XeroHub · Config",
                key = "config:autoload",
            })
        end
    end
})
UIElements.ToggleAutoLoadConfig = autoLoadToggle

function refreshConfigs()
    local list = {}
    local seen = {}
    configPaths = {}
    if listfiles then
        pcall(function()

            for _, folder in ipairs({configFolder, legacyConfigFolder}) do
                if not isfolder or isfolder(folder) then
                    for _, file in ipairs(listfiles(folder)) do
                        if file:match("%.json$") then
                            local name = file:match("([^/\\]+)%.json$")
                            if name and not seen[name] then
                                seen[name] = true
                                configPaths[name] = file
                                table.insert(list, name)
                            end
                        end
                    end
                end
            end
        end)
    end
    if #list == 0 then table.insert(list, "Ninguna") end

    pcall(function()
        configDropdown:Refresh(list)

        local desiredConfig = selectedConfig
        if autoLoadEnabled and autoLoadConfigName and table.find(list, autoLoadConfigName) then
            desiredConfig = autoLoadConfigName
        end
        if not table.find(list, desiredConfig) then
            desiredConfig = list[1]
        end

        configDropdownSyncing = true
        configDropdown:Select(desiredConfig)
        configDropdownSyncing = false
        selectedConfig = desiredConfig
    end)
end

