function secureLoadToggle(element, val)
    if not element or val == nil then return end

    local wasSuppressed = runtime.SuppressNotifications
    runtime.SuppressNotifications = true
    pcall(function() element:Set(val) end)
    runtime.SuppressNotifications = wasSuppressed
end

local function loadConfigByName(configName, loadMode)
    selectedConfig = tostring(configName or selectedConfig or "Ninguna")
    if selectedConfig == "Ninguna" or selectedConfig == "" then
        showBottomMessage("No hay ninguna configuración seleccionada.")
        return
    end

    local path = configPaths[selectedConfig] or (configFolder .. "/" .. selectedConfig .. ".json")
    if isfile and isfile(path) then
        local success, decoded = pcall(function() return HttpService:JSONDecode(readfile(path)) end)
        if success and type(decoded) == "table" then

             if decoded.Toggles then

                if decoded.Toggles["Auto Shoot"] ~= nil then autoShootEnabled = decoded.Toggles["Auto Shoot"] secureLoadToggle(UIElements.TogAutoShoot, autoShootEnabled) end
                if decoded.Toggles["Equipo rápido de gun"] ~= nil then
                    runtime.QuickGunEquipEnabled = decoded.Toggles["Equipo rápido de gun"] == true
                    secureLoadToggle(UIElements.TogQuickGunEquip, runtime.QuickGunEquipEnabled)
                end

                if decoded.Toggles["AutoShoot Cuchillo"] ~= nil then
                    autoShootCuchilloEnabled = decoded.Toggles["AutoShoot Cuchillo"]
                    secureLoadToggle(UIElements.TogAutoShootCuchillo, autoShootCuchilloEnabled)
                end

                if decoded.Toggles["Silent Aim (Pistola)"] ~= nil then
                    silentAimPistolaEnabled = decoded.Toggles["Silent Aim (Pistola)"]
                    secureLoadToggle(UIElements.TogSilentAimPistola, silentAimPistolaEnabled)
                elseif decoded.Toggles["Silent Aim (Manual)"] ~= nil then
                    silentAimPistolaEnabled = decoded.Toggles["Silent Aim (Manual)"]
                    secureLoadToggle(UIElements.TogSilentAimPistola, silentAimPistolaEnabled)
                end

                if decoded.Toggles["Silent Aim (Cuchillo)"] ~= nil then
                    silentAimCuchilloEnabled = decoded.Toggles["Silent Aim (Cuchillo)"]
                    secureLoadToggle(UIElements.TogSilentAimCuchillo, silentAimCuchilloEnabled)
                end

                if decoded.Toggles["Silent Aim (FOV)"] ~= nil then silentAimFovEnabled = decoded.Toggles["Silent Aim (FOV)"] secureLoadToggle(UIElements.TogSilentAimFOV, silentAimFovEnabled) end

                if decoded.Toggles["Mostrar Círculo FOV"] ~= nil then fovVisiblePreference = decoded.Toggles["Mostrar Círculo FOV"] secureLoadToggle(UIElements.TogShowFOV, fovVisiblePreference) end
                if decoded.Toggles["ESP Lineas"] ~= nil then espLinesEnabled = decoded.Toggles["ESP Lineas"] secureLoadToggle(UIElements.TogEspLines, espLinesEnabled) end
                if decoded.Toggles["ESP Box 2D"] ~= nil then espSettings.Box = decoded.Toggles["ESP Box 2D"] secureLoadToggle(UIElements.TogEspBox, espSettings.Box) end
                if decoded.Toggles["ESP Barra Vida"] ~= nil then espSettings.HealthBar = decoded.Toggles["ESP Barra Vida"] secureLoadToggle(UIElements.TogEspHealth, espSettings.HealthBar) end

                if decoded.Toggles["Btn Flotante AutoShoot"] ~= nil then secureLoadToggle(UIElements.ToggleAsBtn, decoded.Toggles["Btn Flotante AutoShoot"]) end
                if decoded.Toggles["Btn Flotante SilentAim"] ~= nil then secureLoadToggle(UIElements.ToggleSaBtn, decoded.Toggles["Btn Flotante SilentAim"]) end
                if decoded.Toggles["Btn Flotante Fantasma"] ~= nil then secureLoadToggle(UIElements.ToggleGhost, decoded.Toggles["Btn Flotante Fantasma"]) end

                if decoded.Toggles["Aumentar Hitbox"] ~= nil then hitboxEnabled = decoded.Toggles["Aumentar Hitbox"] secureLoadToggle(UIElements.TogHitbox, hitboxEnabled) end
                if decoded.Toggles["Hitbox Invisible"] ~= nil then hitboxInvisible = decoded.Toggles["Hitbox Invisible"] secureLoadToggle(UIElements.TogHbInv, hitboxInvisible) end
                if decoded.Toggles["ESP Jugadores"] ~= nil then espEnabled = decoded.Toggles["ESP Jugadores"] secureLoadToggle(UIElements.TogEsp, espEnabled) end
                if decoded.Toggles["Mostrar Resplandor (Glow)"] ~= nil then espSettings.Glow = decoded.Toggles["Mostrar Resplandor (Glow)"] secureLoadToggle(UIElements.TogEspGl, espSettings.Glow) end
                if decoded.Toggles["Mostrar Nombre"] ~= nil then espSettings.Name = decoded.Toggles["Mostrar Nombre"] secureLoadToggle(UIElements.TogEspNm, espSettings.Name) end
                if decoded.Toggles["Mostrar Distancia"] ~= nil then espSettings.Distance = decoded.Toggles["Mostrar Distancia"] secureLoadToggle(UIElements.TogEspDs, espSettings.Distance) end
                if decoded.Toggles["Ocultar mi Nombre (Local)"] ~= nil then hideNameEnabled = decoded.Toggles["Ocultar mi Nombre (Local)"] secureLoadToggle(UIElements.TogHideName, hideNameEnabled) end
                if decoded.Toggles["FPS Boost"] ~= nil then fpsBoostEnabled = decoded.Toggles["FPS Boost"] secureLoadToggle(UIElements.ToggleFPS, fpsBoostEnabled) end
                if decoded.Toggles["FOV Changer"] ~= nil then cameraFovEnabled = decoded.Toggles["FOV Changer"] secureLoadToggle(UIElements.TogCameraFOV, cameraFovEnabled) end
                if runtime.UpdateESP2DRenderConnection then runtime.UpdateESP2DRenderConnection() end
            end

            if decoded.Sliders then
                if decoded.Sliders["Transparencia Hitbox"] ~= nil then hitboxTransparency = decoded.Sliders["Transparencia Hitbox"] secureLoadToggle(UIElements.SliHitboxTrans, hitboxTransparency) end
                if decoded.Sliders["Tamaño del FOV"] ~= nil then fovRadius = decoded.Sliders["Tamaño del FOV"] secureLoadToggle(UIElements.SliFOVSize, fovRadius) end
                if decoded.Sliders["FOV de Cámara"] ~= nil then cameraFovValue = math.clamp(tonumber(decoded.Sliders["FOV de Cámara"]) or cameraFovValue or 70, 1, 120) secureLoadToggle(UIElements.SliCameraFOV, cameraFovValue) end
                if decoded.Sliders["Tamaño de Hitbox"] ~= nil then hitboxSize = decoded.Sliders["Tamaño de Hitbox"] secureLoadToggle(UIElements.SliHitbox, hitboxSize) end
                if decoded.Sliders["Delay Equipar Macro"] ~= nil then macroEquipDelay = decoded.Sliders["Delay Equipar Macro"] secureLoadToggle(UIElements.SliMacroEquip, macroEquipDelay) end
                if decoded.Sliders["Delay Disparo Macro"] ~= nil then macroShootDelay = decoded.Sliders["Delay Disparo Macro"] secureLoadToggle(UIElements.SliMacroShoot, macroShootDelay) end
            end

            if decoded.Colors then
                if decoded.Colors["Color de Hitbox"] then
                    local cHitbox = Color3.new(decoded.Colors["Color de Hitbox"].R, decoded.Colors["Color de Hitbox"].G, decoded.Colors["Color de Hitbox"].B)
                    hitboxColor = cHitbox secureLoadToggle(UIElements.ColHitbox, cHitbox)
                end
                if decoded.Colors["Color del ESP"] then
                    local cEsp = Color3.new(decoded.Colors["Color del ESP"].R, decoded.Colors["Color del ESP"].G, decoded.Colors["Color del ESP"].B)
                    espColor = cEsp secureLoadToggle(UIElements.ColEsp, cEsp)
                end
            end

            if decoded.Extras then
                if decoded.Extras["Partes Aimbot"] then
                    runtime.SetTargetSelection("SilentAim", decoded.Extras["Partes Aimbot"])
                elseif decoded.Extras["Parte Aimbot"] then
                    runtime.SetTargetSelection("SilentAim", decoded.Extras["Parte Aimbot"])
                end

                if decoded.Extras["Partes AutoShoot"] then
                    runtime.SetTargetSelection("AutoShoot", decoded.Extras["Partes AutoShoot"])
                elseif decoded.Extras["Parte AutoShoot"] then
                    runtime.SetTargetSelection("AutoShoot", decoded.Extras["Parte AutoShoot"])
                end
            end

            local savedTheme = decoded.Interfaz and decoded.Interfaz.Tema
            if not savedTheme and decoded.Extras then
                savedTheme = decoded.Extras["Tema Interfaz"]
            end
            if savedTheme then
                local normalizedTheme = (tostring(savedTheme) == "Blanco" or tostring(savedTheme) == "White" or tostring(savedTheme) == "Claro") and "Blanco" or "Xero"
                runtime.InterfaceTheme = normalizedTheme
                if Window and Window.SetTheme then
                    Window:SetTheme(normalizedTheme, true)
                elseif WindUI and WindUI.SetTheme then
                    WindUI:SetTheme(normalizedTheme)
                end
                if UIElements.ThemeDropdown then
                    secureLoadToggle(UIElements.ThemeDropdown, normalizedTheme == "Blanco" and "Blanco" or "Oscuro")
                end
                xeroRefreshKnownColorpickers()
            end

            if decoded.Personalizacion then
                xeroLoadPersonalization(decoded.Personalizacion)
            end

            if decoded.Apariencia then
                runtime.LoadAppearanceConfig(decoded.Apariencia)
            end

            if decoded.Efectos and runtime.LoadDeathEffectsConfig then
                runtime.LoadDeathEffectsConfig(decoded.Efectos)
            end
            if decoded.Sonidos and runtime.LoadSoundConfig then
                runtime.LoadSoundConfig(decoded.Sonidos)
            end

            if decoded.Texturas and runtime.LoadTextureConfig then
                runtime.LoadTextureConfig(decoded.Texturas)
            end

            if decoded.Animaciones then
                task.spawn(function()

                    task.wait(1)

                    if decoded.Animaciones.Paquete and decoded.Animaciones.Paquete ~= "Ninguno" then
                        selectedBundleCompleto = decoded.Animaciones.Paquete

                        animacionActualActiva = animationData[selectedBundleCompleto]
                        applyCustomAnims(animacionActualActiva)

                    elseif decoded.Animaciones.Mix then
                        mixParts = decoded.Animaciones.Mix
                        local customMix = {}

                        if mixParts.Idle ~= "Ninguno" then
                            customMix.Idle = animationData[mixParts.Idle].Idle
                            customMix.Idle2 = animationData[mixParts.Idle].Idle2
                        end
                        if mixParts.Walk ~= "Ninguno" then customMix.Walk = animationData[mixParts.Walk].Walk end
                        if mixParts.Run ~= "Ninguno" then customMix.Run = animationData[mixParts.Run].Run end
                        if mixParts.Jump ~= "Ninguno" then customMix.Jump = animationData[mixParts.Jump].Jump end
                        if mixParts.Fall ~= "Ninguno" then customMix.Fall = animationData[mixParts.Fall].Fall end
                        if mixParts.Climb ~= "Ninguno" then customMix.Climb = animationData[mixParts.Climb].Climb end

                        local hasValues = false
                        for _, v in pairs(customMix) do if v then hasValues = true break end end

                        if hasValues then

                            animacionActualActiva = customMix
                            applyCustomAnims(animacionActualActiva)
                        end
                    end
                end)
            end

            if loadMode == "auto" then
                showBottomMessage("Auto Load: '" .. selectedConfig .. "' cargada.", {
                    title = "XeroHub · Config",
                    key = "config:autoload:loaded",
                })
            else
                showBottomMessage("'" .. selectedConfig .. "' cargada con éxito.")
            end
        else
            showBottomMessage("Error al leer el archivo.")
        end
    else
        showBottomMessage("La configuración no existe.")
    end
end

Tabs.Config:Button({
    Title = "Cargar Configuración",
    Callback = function()
        loadConfigByName(selectedConfig, "manual")
    end
})

task.spawn(function()
    task.wait(1)
    refreshConfigs()

    if autoLoadToggle then
        local wasSuppressed = runtime.SuppressNotifications
        runtime.SuppressNotifications = true
        autoLoadSyncing = true
        pcall(function() autoLoadToggle:Set(autoLoadEnabled) end)
        autoLoadSyncing = false
        runtime.SuppressNotifications = wasSuppressed
    end

    if autoLoadEnabled and autoLoadConfigName then
        local path = configPaths[autoLoadConfigName] or (configFolder .. "/" .. autoLoadConfigName .. ".json")
        if type(isfile) == "function" and isfile(path) then
            selectedConfig = autoLoadConfigName

            configDropdownSyncing = true
            pcall(function() configDropdown:Select(autoLoadConfigName) end)
            configDropdownSyncing = false

            task.wait(0.10)
            loadConfigByName(autoLoadConfigName, "auto")
        else
            showBottomMessage("Auto Load: no se encontró '" .. tostring(autoLoadConfigName) .. "'.", {
                title = "XeroHub · Config",
                key = "config:autoload:error",
            })
        end
    end
end)

assert(loadstring([====[
return function(runtime, player, Players, HttpService, workspace, RunService, isHairAccessory, manualAttachAppearanceAccessory, KORBLOX_UPPER_MESH, KORBLOX_TEXTURE)
-- ============================================================
-- XERO APPEARANCE SYNC · usuarios del hub en el mismo JobId
-- ============================================================
-- El backend sólo intercambia DESCRIPCIONES visuales. Posición/pose siguen
-- viniendo de la replicación normal de Roblox; nunca enviamos CFrames por HTTP.
do
    local syncState = {
        Endpoint = "https://hub.onyx-scripts.com/appearance_sync",
        Entries = {},
        RenderEntries = {},
        RenderConnection = nil,
        TemplateCache = {},
        TemplateCacheLimit = 8,
        HiddenEnforceInterval = 0.10,
        Revision = 0,
        LastSerialized = nil,
        LastPublishAt = 0,
        Alive = true,
    }
    runtime.AppearanceSync = syncState


    local syncRequest = (syn and syn.request) or (http and http.request) or http_request or request

    local function numberOr(value, fallback)
        value = tonumber(value)
        if value == nil or value ~= value or value == math.huge or value == -math.huge then
            return fallback
        end
        return value
    end

    local function vecToArray(v)
        return {
            numberOr(v and v.X, 0),
            numberOr(v and v.Y, 0),
            numberOr(v and v.Z, 0),
        }
    end

    local function arrayToVector(value)
        if type(value) ~= "table" then return Vector3.zero end
        return Vector3.new(
            numberOr(value[1], 0),
            numberOr(value[2], 0),
            numberOr(value[3], 0)
        )
    end

    local function buildLocalAppearanceState()
        local enabled = {}
        local offsets = {}

        for _, key in ipairs(runtime.AppearanceOrder) do
            local asset = runtime.AppearanceCatalog[key]
            if asset and runtime.Appearance.Enabled[key] == true
                and asset.Kind ~= "Headless" and asset.Kind ~= "Korblox"
                and asset.Kind ~= "HairToggle" then

                enabled[#enabled + 1] = key

                if asset.Kind == "Accessory" then
                    local offset = runtime.Appearance.AccessoryOffsets[key]
                    if offset then
                        offsets[key] = {
                            p = vecToArray(offset.Position),
                            r = vecToArray(offset.Rotation),
                            s = math.clamp(numberOr(offset.Scale, 1), 0.25, 3),
                        }
                    end
                end
            end
        end

        local cloneState = runtime.Appearance.AvatarClone
        local baseUserId = player.UserId
        if cloneState and cloneState.Active and tonumber(cloneState.TargetUserId) then
            baseUserId = tonumber(cloneState.TargetUserId)
        end

        return {
            baseUserId = baseUserId,
            outfitId = cloneState and cloneState.Active and tonumber(cloneState.TargetOutfitId) or nil,
            headless = runtime.Appearance.Enabled.Headless == true,
            korblox = runtime.Appearance.Enabled.Korblox == true,
            hideHair = runtime.Appearance.Enabled.HideHair == true,
            enabled = enabled,
            offsets = offsets,
        }
    end

    local function httpPostState(state, revision)
        if not syncRequest or not runtime.Alive or not syncState.Alive then return false end
        local payload = HttpService:JSONEncode({
            userId = player.UserId,
            username = player.Name,
            jobId = tostring(game.JobId),
            revision = revision,
            state = state,
        })

        local ok, response = pcall(function()
            return syncRequest({
                Url = syncState.Endpoint,
                Method = "POST",
                Headers = {
                    ["Astra-Auth"] = "OnyxHub!",
                    ["User-Agent"] = "Roblox/XeroHub-AppearanceSync",
                    ["Content-Type"] = "application/json",
                },
                Body = payload,
            })
        end)
        return ok and response and tonumber(response.StatusCode or response.Status or 0) >= 200
            and tonumber(response.StatusCode or response.Status or 0) < 300
    end

    local function httpGetStates()
        if not syncRequest or not runtime.Alive or not syncState.Alive then return nil end
        local url = syncState.Endpoint .. "?jobid=" .. HttpService:UrlEncode(tostring(game.JobId))
        local ok, response = pcall(function()
            return syncRequest({
                Url = url,
                Method = "GET",
                Headers = {
                    ["Astra-Auth"] = "OnyxHub!",
                    ["User-Agent"] = "Roblox/XeroHub-AppearanceSync",
                    ["Accept"] = "application/json",
                },
            })
        end)
        if not ok or not response then return nil end
        local status = tonumber(response.StatusCode or response.Status or 0) or 0
        if status < 200 or status >= 300 or type(response.Body) ~= "string" then return nil end
        local decodedOk, decoded = pcall(function() return HttpService:JSONDecode(response.Body) end)
        if not decodedOk or type(decoded) ~= "table" or decoded.success ~= true then return nil end
        return type(decoded.users) == "table" and decoded.users or {}
    end

    local function getSyncFolder()
        local folder = workspace:FindFirstChild("XeroHub_RemoteAppearances")
        if not folder then
            folder = Instance.new("Folder")
            folder.Name = "XeroHub_RemoteAppearances"
            folder.Parent = workspace
        end
        return folder
    end

    local removeRenderEntry

    local function disconnectRenderConnectionIfIdle()
        if #syncState.RenderEntries > 0 then return end
        local connection = syncState.RenderConnection
        if connection then
            pcall(function() connection:Disconnect() end)
            syncState.RenderConnection = nil
        end
    end

    local function renderRemoteEntries()
        if not runtime.Alive or not syncState.Alive then return end
        local now = os.clock()
        local list = syncState.RenderEntries
        local index = 1
        while index <= #list do
            local entry = list[index]
            local syncPose = entry and entry.SyncPose
            if not entry or not syncPose or not entry.Overlay or not entry.Overlay.Parent then
                if entry then
                    removeRenderEntry(entry)
                else
                    local last = list[#list]
                    list[index] = last
                    list[#list] = nil
                    if last then last.RenderIndex = index end
                end
            elseif syncPose(now, false) == false then
                removeRenderEntry(entry)
            else
                index += 1
            end
        end
        disconnectRenderConnectionIfIdle()
    end

    local function ensureRenderConnection()
        if syncState.RenderConnection or #syncState.RenderEntries == 0
            or not runtime.Alive or not syncState.Alive then return end
        syncState.RenderConnection = RunService.RenderStepped:Connect(renderRemoteEntries)
    end

    local function addRenderEntry(entry)
        if not entry or entry.RenderIndex then return end
        local list = syncState.RenderEntries
        local index = #list + 1
        list[index] = entry
        entry.RenderIndex = index
        ensureRenderConnection()
    end

    removeRenderEntry = function(entry)
        if not entry then return end
        local index = entry.RenderIndex
        if not index then return end
        local list = syncState.RenderEntries
        local last = list[#list]
        list[index] = last
        list[#list] = nil
        if last and last ~= entry then last.RenderIndex = index end
        entry.RenderIndex = nil
        disconnectRenderConnectionIfIdle()
    end

    local function disconnectEntry(entry)
        if not entry then return end
        entry.Generation = (entry.Generation or 0) + 1
        removeRenderEntry(entry)
        entry.SyncPose = nil
        entry.NextHiddenEnforceAt = nil

        for _, connection in ipairs(entry.Connections or {}) do
            pcall(function() connection:Disconnect() end)
        end
        entry.Connections = {}

        local hiddenList = entry.HiddenList or {}
        for index = 1, #hiddenList do
            local object = hiddenList[index]
            local oldValue = entry.Hidden and entry.Hidden[object]
            if oldValue ~= nil and object and object.Parent and object:IsA("BasePart") then
                pcall(function() object.LocalTransparencyModifier = oldValue end)
            end
        end
        entry.Hidden = setmetatable({}, {__mode = "k"})
        entry.HiddenList = {}
        entry.HiddenIndex = setmetatable({}, {__mode = "k"})
        entry.ToolGuards = setmetatable({}, {__mode = "k"})

        if entry.Overlay then
            pcall(function() entry.Overlay:Destroy() end)
            entry.Overlay = nil
        end
        entry.RemoteFace = nil
        entry.MotorPairs = nil
    end

    local function destroyEntry(userId)
        local entry = syncState.Entries[userId]
        if not entry then return end
        disconnectEntry(entry)
        syncState.Entries[userId] = nil
    end

    -- Mismo filtro de armas que usa el clonador local. El Character remoto puede
    -- recibir/reparentar Handles, MeshParts y efectos DESPUÉS de que ocultamos su
    -- avatar base; cualquier cosa que termine dentro de un Tool se libera al instante.
    local function isToolVisual(object, char)
        if not object then return false end
        local tool = object:IsA("Tool") and object or object:FindFirstAncestorWhichIsA("Tool")
        return tool ~= nil and (not char or tool:IsDescendantOf(char))
    end

    local function untrackRemoteHiddenObject(entry, object)
        if not entry or not object then return end
        local index = entry.HiddenIndex and entry.HiddenIndex[object]
        if index then
            local list = entry.HiddenList
            local lastIndex = #list
            local last = list[lastIndex]
            list[index] = last
            list[lastIndex] = nil
            if last and last ~= object then
                entry.HiddenIndex[last] = index
            end
            entry.HiddenIndex[object] = nil
        end
        if entry.Hidden then entry.Hidden[object] = nil end
    end

    local function restoreRemoteHiddenObject(entry, object)
        if not entry or not object then return end
        local oldValue = entry.Hidden and entry.Hidden[object]
        if oldValue == nil then return end
        if object.Parent and object:IsA("BasePart") then
            pcall(function() object.LocalTransparencyModifier = oldValue end)
        end
        untrackRemoteHiddenObject(entry, object)
    end

    local function enforceRemoteHidden(entry, char, now, force)
        if not entry or not char then return end
        now = now or os.clock()
        if not force and now < (entry.NextHiddenEnforceAt or 0) then return end
        entry.NextHiddenEnforceAt = now + syncState.HiddenEnforceInterval

        local list = entry.HiddenList or {}
        local index = 1
        while index <= #list do
            local object = list[index]
            if not object or not object.Parent then
                untrackRemoteHiddenObject(entry, object)
            elseif isToolVisual(object, char) then
                restoreRemoteHiddenObject(entry, object)
            else
                if object.LocalTransparencyModifier ~= 1 then
                    object.LocalTransparencyModifier = 1
                end
                index = index + 1
            end
        end
    end

    local function releaseRemoteToolVisuals(entry, char, tool)
        if not entry or not char or not tool or not tool:IsA("Tool")
            or not tool:IsDescendantOf(char) then return end

        restoreRemoteHiddenObject(entry, tool)
        for _, object in ipairs(tool:GetDescendants()) do
            restoreRemoteHiddenObject(entry, object)
        end
    end

    local function bindRemoteToolGuard(entry, char, tool)
        if not entry or not char or not tool or not tool:IsA("Tool")
            or not tool:IsDescendantOf(char) then return end

        entry.ToolGuards = entry.ToolGuards or setmetatable({}, {__mode = "k"})
        if entry.ToolGuards[tool] then return end

        local bundle = {}
        entry.ToolGuards[tool] = bundle
        releaseRemoteToolVisuals(entry, char, tool)

        bundle.DescendantAdded = tool.DescendantAdded:Connect(function(object)
            if entry.Character ~= char then return end
            restoreRemoteHiddenObject(entry, object)
        end)
        table.insert(entry.Connections, bundle.DescendantAdded)

        bundle.AncestryChanged = tool.AncestryChanged:Connect(function()
            if tool:IsDescendantOf(char) then
                releaseRemoteToolVisuals(entry, char, tool)
                return
            end
            if entry.ToolGuards and entry.ToolGuards[tool] == bundle then
                entry.ToolGuards[tool] = nil
            end
        end)
        table.insert(entry.Connections, bundle.AncestryChanged)
    end

    local function hideRemoteBaseObject(entry, object, char)
        if not object or not object.Parent then return end

        -- Si algo que ya estaba cacheado como cuerpo terminó siendo parte de un arma,
        -- restauramos su LTM en vez de dejarlo invisible.
        if isToolVisual(object, char) then
            restoreRemoteHiddenObject(entry, object)
            local tool = object:IsA("Tool") and object or object:FindFirstAncestorWhichIsA("Tool")
            if tool then bindRemoteToolGuard(entry, char, tool) end
            return
        end

        if object:IsA("BasePart") and object.Name ~= "HumanoidRootPart" and object:IsDescendantOf(char) then
            if entry.Hidden[object] == nil then
                entry.Hidden[object] = object.LocalTransparencyModifier
                local list = entry.HiddenList
                local index = #list + 1
                list[index] = object
                entry.HiddenIndex[object] = index
            end
            if object.LocalTransparencyModifier ~= 1 then
                object.LocalTransparencyModifier = 1
            end
        end
    end

    local function bindRemoteBaseHidden(entry, char)
        entry.ToolGuards = setmetatable({}, {__mode = "k"})
        entry.HiddenList = entry.HiddenList or {}
        entry.HiddenIndex = entry.HiddenIndex or setmetatable({}, {__mode = "k"})

        -- Primero registramos armas ya equipadas para que jamás entren al hide inicial.
        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Tool") then bindRemoteToolGuard(entry, char, child) end
        end

        for _, object in ipairs(char:GetDescendants()) do
            hideRemoteBaseObject(entry, object, char)
        end

        local descendantConnection = char.DescendantAdded:Connect(function(object)
            if entry.Character ~= char then return end
            task.defer(function()
                if not object or not object.Parent or entry.Character ~= char then return end
                local tool = object:IsA("Tool") and object or object:FindFirstAncestorWhichIsA("Tool")
                if tool and tool:IsDescendantOf(char) then
                    -- First bind scans the weapon once; subsequent descendant
                    -- events only need to restore that exact newly added object.
                    bindRemoteToolGuard(entry, char, tool)
                    restoreRemoteHiddenObject(entry, object)
                else
                    hideRemoteBaseObject(entry, object, char)
                end
            end)
        end)
        table.insert(entry.Connections, descendantConnection)

        local childConnection = char.ChildAdded:Connect(function(child)
            if entry.Character ~= char or not child:IsA("Tool") then return end
            bindRemoteToolGuard(entry, char, child)
        end)
        table.insert(entry.Connections, childConnection)
    end

    local function findAccessoryWeld(accessory)
        local handle = accessory and accessory:FindFirstChild("Handle")
        if not handle then return nil end
        local preferred = handle:FindFirstChild("AccessoryWeld") or handle:FindFirstChild("iLunXAppearanceWeld")
        if preferred and preferred:IsA("Weld") then return preferred end
        for _, object in ipairs(handle:GetChildren()) do
            if object:IsA("Weld") then return object end
        end
        return nil
    end

    local function scaleRemoteAccessory(accessory, scale)
        scale = math.clamp(numberOr(scale, 1), 0.25, 3)
        if math.abs(scale - 1) < 0.0001 then return end
        for _, object in ipairs(accessory:GetDescendants()) do
            if object:IsA("SpecialMesh") then
                object.Scale = object.Scale * scale
            elseif object:IsA("BasePart") and not object:FindFirstChildOfClass("SpecialMesh") then
                object.Size = object.Size * scale
            end
        end
    end

    local function attachRemoteAccessory(overlay, key, offsetData)
        local template = runtime.GetAppearanceTemplate(key)
        local humanoid = overlay and overlay:FindFirstChildOfClass("Humanoid")
        if not template or not humanoid then return end

        local accessory = template:Clone()
        accessory:SetAttribute("XeroHubRemoteAppearanceKey", key)
        local ok = pcall(function() humanoid:AddAccessory(accessory) end)
        if not ok or accessory.Parent ~= overlay then
            accessory.Parent = overlay
            pcall(function() manualAttachAppearanceAccessory(overlay, accessory) end)
        end

        if accessory.Parent ~= overlay then
            pcall(function() accessory:Destroy() end)
            return
        end

        local data = type(offsetData) == "table" and offsetData or {}
        scaleRemoteAccessory(accessory, data.s)

        local weld = findAccessoryWeld(accessory)
        if not weld then
            pcall(function() manualAttachAppearanceAccessory(overlay, accessory) end)
            weld = findAccessoryWeld(accessory)
        end
        if weld then
            local p = arrayToVector(data.p)
            local r = arrayToVector(data.r)
            local baseC1 = weld.C1
            weld.C1 = baseC1
                * CFrame.new(p.X, p.Y, p.Z)
                * CFrame.Angles(math.rad(r.X), math.rad(r.Y), math.rad(r.Z))
        end
    end

    local function getRemoteHeadScale(overlay)
        local humanoid = overlay and overlay:FindFirstChildOfClass("Humanoid")
        if not humanoid then return 1 end
        local value = humanoid:FindFirstChild("HeadScale")
        if value and value:IsA("NumberValue") then
            return math.clamp(numberOr(value.Value, 1), 0.5, 2)
        end
        local ok, description = pcall(function() return humanoid:GetAppliedDescription() end)
        if ok and description then
            local result = math.clamp(numberOr(description.HeadScale, 1), 0.5, 2)
            pcall(function() description:Destroy() end)
            return result
        end
        return 1
    end

    local function applyRemoteFace(entry, overlay, key, headless)
        local texture = runtime.GetFaceTexture(key)
        local head = overlay and overlay:FindFirstChild("Head")
        if not texture or not head or not head:IsA("BasePart") then return end

        -- Dynamic/custom heads do not share the UV layout of classic Roblox faces.
        -- Reuse the same idea as the local face layer: hide only the visual head and
        -- render a classic head mesh on top, while keeping the original Head alive so
        -- hats/attachments continue following the cloned avatar correctly.
        local needsClassic = false
        pcall(function() needsClassic = runtime.FaceNeedsClassicVisual(overlay) == true end)

        if needsClassic then
            head.Transparency = 1
            head.LocalTransparencyModifier = 1
            local originalDecal = head:FindFirstChildWhichIsA("Decal")
            if originalDecal then originalDecal.Transparency = 1 end

            local part = Instance.new("Part")
            part.Name = "XeroRemoteClassicFace"
            part.Size = Vector3.new(2, 1, 1)
            part.CFrame = head.CFrame
            part.Color = head.Color
            part.Material = Enum.Material.SmoothPlastic
            part.Transparency = headless and 1 or 0
            part.LocalTransparencyModifier = 0
            part.CanCollide = false
            part.CanTouch = false
            part.CanQuery = false
            part.Massless = true
            part.CastShadow = head.CastShadow
            part.TopSurface = Enum.SurfaceType.Smooth
            part.BottomSurface = Enum.SurfaceType.Smooth
            part.Anchored = true

            local mesh = Instance.new("SpecialMesh")
            mesh.Name = "XeroRemoteClassicHeadMesh"
            mesh.MeshType = Enum.MeshType.Head
            mesh.Scale = Vector3.new(1.25, 1.25, 1.25) * getRemoteHeadScale(overlay)
            mesh.Parent = part

            local decal = Instance.new("Decal")
            decal.Name = "face"
            decal.Face = Enum.NormalId.Front
            decal.Texture = texture
            decal.Transparency = headless and 1 or 0
            decal.Parent = part

            part.Parent = overlay
            entry.RemoteFace = {Part = part, Head = head, Decal = decal}
            return
        end

        local decal = head:FindFirstChildWhichIsA("Decal")
        if not decal then
            decal = Instance.new("Decal")
            decal.Name = "face"
            decal.Face = Enum.NormalId.Front
            decal.Parent = head
        end
        decal.Texture = texture
        decal.Transparency = headless and 1 or 0
    end

    local function applyRemoteLayers(entry, overlay, state)
        if not overlay or type(state) ~= "table" then return end

        local enabledSet = {}
        for _, key in ipairs(type(state.enabled) == "table" and state.enabled or {}) do
            if type(key) == "string" and runtime.AppearanceCatalog[key] then
                enabledSet[key] = true
            end
        end

        -- Una sola cara puede estar activa visualmente.
        for _, key in ipairs(runtime.AppearanceOrder) do
            local asset = runtime.AppearanceCatalog[key]
            if enabledSet[key] and asset and asset.Kind == "Face" then
                applyRemoteFace(entry, overlay, key, state.headless == true)
                break
            end
        end

        -- Limiteds/accesorios propios de XeroHub.
        for _, key in ipairs(runtime.AppearanceOrder) do
            local asset = runtime.AppearanceCatalog[key]
            if enabledSet[key] and asset and asset.Kind == "Accessory" then
                attachRemoteAccessory(overlay, key, state.offsets and state.offsets[key])
            end
        end

        if state.hideHair == true then
            for _, object in ipairs(overlay:GetChildren()) do
                if object:IsA("Accoutrement") and isHairAccessory(object) then
                    for _, visual in ipairs(object:GetDescendants()) do
                        if visual:IsA("BasePart") then visual.LocalTransparencyModifier = 1 end
                    end
                end
            end
        end

        if state.korblox == true then
            local humanoid = overlay:FindFirstChildOfClass("Humanoid")
            if humanoid and humanoid.RigType == Enum.HumanoidRigType.R15 then
                local upper = overlay:FindFirstChild("RightUpperLeg")
                local lower = overlay:FindFirstChild("RightLowerLeg")
                local foot = overlay:FindFirstChild("RightFoot")
                if upper then
                    pcall(function() upper.MeshId = KORBLOX_UPPER_MESH end)
                    pcall(function() upper.TextureID = KORBLOX_TEXTURE end)
                    upper.LocalTransparencyModifier = 0
                end
                if lower then lower.LocalTransparencyModifier = 1 end
                if foot then foot.LocalTransparencyModifier = 1 end
            end
        end

        if state.headless == true then
            if entry.RemoteFace and entry.RemoteFace.Part then
                entry.RemoteFace.Part.Transparency = 1
                if entry.RemoteFace.Decal then entry.RemoteFace.Decal.Transparency = 1 end
            end
            local head = overlay:FindFirstChild("Head")
            if head and head:IsA("BasePart") then
                head.LocalTransparencyModifier = 1
                for _, object in ipairs(head:GetDescendants()) do
                    if object:IsA("Decal") or object:IsA("Texture") then
                        object.Transparency = 1
                    end
                end
            end
        end
    end

    local function prepareRemoteOverlayPhysics(overlay)
        for _, object in ipairs(overlay:GetDescendants()) do
            if object:IsA("BasePart") then
                object.CanCollide = false
                object.CanTouch = false
                object.CanQuery = false
                object.Massless = true
                if object.Parent == overlay then
                    object.Anchored = true
                end
            elseif object:IsA("Motor6D") then
                pcall(function() object.Enabled = false end)
            end
        end
        local humanoid = overlay:FindFirstChildOfClass("Humanoid")
        if humanoid then
            pcall(function() humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None end)
            pcall(function() humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff end)
            pcall(function() humanoid.AutoRotate = false end)
            pcall(function() humanoid.PlatformStand = true end)
        end
    end

    local R15_REMOTE_JOINTS = {
        {"HumanoidRootPart", "LowerTorso"},
        {"LowerTorso", "UpperTorso"},
        {"UpperTorso", "Head"},
        {"UpperTorso", "LeftUpperArm"},
        {"LeftUpperArm", "LeftLowerArm"},
        {"LeftLowerArm", "LeftHand"},
        {"UpperTorso", "RightUpperArm"},
        {"RightUpperArm", "RightLowerArm"},
        {"RightLowerArm", "RightHand"},
        {"LowerTorso", "LeftUpperLeg"},
        {"LeftUpperLeg", "LeftLowerLeg"},
        {"LeftLowerLeg", "LeftFoot"},
        {"LowerTorso", "RightUpperLeg"},
        {"RightUpperLeg", "RightLowerLeg"},
        {"RightLowerLeg", "RightFoot"},
    }
    local R6_REMOTE_JOINTS = {
        {"HumanoidRootPart", "Torso"},
        {"Torso", "Head"},
        {"Torso", "Left Arm"},
        {"Torso", "Right Arm"},
        {"Torso", "Left Leg"},
        {"Torso", "Right Leg"},
    }

    local function findSharedRigAttachment(part0, part1)
        if not part0 or not part1 then return nil, nil end
        for _, object in ipairs(part0:GetChildren()) do
            if object:IsA("Attachment") and string.find(object.Name, "RigAttachment", 1, true) then
                local other = part1:FindFirstChild(object.Name)
                if other and other:IsA("Attachment") then
                    return object, other
                end
            end
        end
        return nil, nil
    end

    local function bindRemotePose(entry, targetPlayer, char, overlay)
        local humanoid = char:FindFirstChildOfClass("Humanoid")
        local realRoot = char:FindFirstChild("HumanoidRootPart")
        local overlayRoot = overlay:FindFirstChild("HumanoidRootPart")
        if not humanoid or not realRoot or not overlayRoot then return false end

        local realParts = {}
        local cloneParts = {}
        for _, object in ipairs(char:GetChildren()) do
            if object:IsA("BasePart") then realParts[object.Name] = object end
        end
        for _, object in ipairs(overlay:GetChildren()) do
            if object:IsA("BasePart") and object.Name ~= "XeroRemoteClassicFace" then
                cloneParts[object.Name] = object
            end
        end

        -- IMPORTANTE PARA JUGADORES REMOTOS:
        -- Motor6D.Transform es excelente para el jugador LOCAL porque Animator lo escribe
        -- directamente en nuestro cliente. En otros jugadores ese Transform puede llegar
        -- tarde, incompleto o con un estado distinto al que finalmente Roblox dibuja.
        -- Sus BasePart.CFrame, en cambio, ya contienen la pose replicada FINAL.
        --
        -- Por eso aquí NO copiamos Transform. Recuperamos la pose relativa a partir de
        -- CFrame + pivotes neutrales del rig real y luego la aplicamos sobre LOS pivotes
        -- del avatar clonado. Así animación y proporciones quedan completamente separadas.
        local liveMotorMap = {}
        for _, object in ipairs(char:GetDescendants()) do
            if object:IsA("Motor6D") and object.Part0 and object.Part1 then
                liveMotorMap[object.Part0.Name .. ">" .. object.Part1.Name] = object
            end
        end

        local specs = humanoid.RigType == Enum.HumanoidRigType.R15 and R15_REMOTE_JOINTS or R6_REMOTE_JOINTS
        local pairsList = {}

        for _, spec in ipairs(specs) do
            local parentName, childName = spec[1], spec[2]
            local realParent, realChild = realParts[parentName], realParts[childName]
            local cloneParent, cloneChild = cloneParts[parentName], cloneParts[childName]

            if realParent and realChild and cloneParent and cloneChild then
                local motor = liveMotorMap[parentName .. ">" .. childName]
                if motor and (motor.Part0 ~= realParent or motor.Part1 ~= realChild) then
                    motor = nil
                end

                local cloneA0, cloneA1 = findSharedRigAttachment(cloneParent, cloneChild)
                local realA0, realA1 = findSharedRigAttachment(realParent, realChild)

                -- Los RigAttachment son la mejor representación del pivote neutral.
                -- Si Duels los reemplazó, C0/C1 del Motor6D actual sirven de respaldo.
                local realC0 = realA0 and realA0.CFrame or (motor and motor.C0 or nil)
                local realC1 = realA1 and realA1.CFrame or (motor and motor.C1 or nil)

                if cloneA0 and cloneA1 and realC0 and realC1 then
                    pairsList[#pairsList + 1] = {
                        RealParent = realParent,
                        RealChild = realChild,
                        CloneParent = cloneParent,
                        CloneChild = cloneChild,
                        RealC0 = realC0,
                        RealC1 = realC1,
                        CloneC0 = cloneA0.CFrame,
                        CloneC1Inverse = cloneA1.CFrame:Inverse(),
                        PoseFromReplicatedParts = true,
                    }
                else
                    -- R6/custom fallback: conserva la geometría neutral del clon y sólo
                    -- aplica el delta observado en el rig remoto.
                    local realRelative = realParent.CFrame:ToObjectSpace(realChild.CFrame)
                    pairsList[#pairsList + 1] = {
                        RealParent = realParent,
                        RealChild = realChild,
                        CloneParent = cloneParent,
                        CloneChild = cloneChild,
                        InitialRealRelativeInverse = realRelative:Inverse(),
                        InitialCloneRelative = cloneParent.CFrame:ToObjectSpace(cloneChild.CFrame),
                        RelativeFallback = true,
                    }
                end
            end
        end

        if #pairsList == 0 then return false end
        entry.MotorPairs = pairsList

        local function syncPose(now, forceHidden)
            if not runtime.Alive or not syncState.Alive or entry.Overlay ~= overlay
                or entry.Character ~= char or targetPlayer.Character ~= char
                or not overlay.Parent or not char.Parent then
                return false
            end

            -- Movimiento global del jugador sí se copia directamente.
            overlayRoot.CFrame = realRoot.CFrame

            pcall(function()
                -- Orden raíz -> extremidades: cada cloneParent ya quedó colocado antes
                -- de calcular su hijo. Eso evita que Head/brazos usen el frame anterior.
                for i = 1, #pairsList do
                    local pair = pairsList[i]
                    local realParent = pair.RealParent
                    local realChild = pair.RealChild
                    local cloneParent = pair.CloneParent
                    local cloneChild = pair.CloneChild

                    if realParent and realParent.Parent
                        and realChild and realChild.Parent
                        and cloneParent and cloneParent.Parent
                        and cloneChild and cloneChild.Parent then

                        if pair.PoseFromReplicatedParts then
                            -- Recupera ÚNICAMENTE la pose animada del rig remoto:
                            --      pose = (Parent * neutralC0)^-1 * (Child * neutralC1)
                            -- Al aplicarla con los pivotes DEL CLON, sus escalas/bundles
                            -- nunca contaminan cuello, brazos, piernas ni torso.
                            local parentJointWorld = realParent.CFrame * pair.RealC0
                            local childJointWorld = realChild.CFrame * pair.RealC1
                            local poseTransform = parentJointWorld:ToObjectSpace(childJointWorld)

                            cloneChild.CFrame = cloneParent.CFrame
                                * pair.CloneC0
                                * poseTransform
                                * pair.CloneC1Inverse
                        else
                            local currentRelative = realParent.CFrame:ToObjectSpace(realChild.CFrame)
                            local delta = pair.InitialRealRelativeInverse * currentRelative
                            cloneChild.CFrame = cloneParent.CFrame * pair.InitialCloneRelative * delta
                        end
                    end
                end
            end)

            -- La cara clásica se pega DESPUÉS de resolver Neck/Head este mismo frame.
            -- Así nunca puede quedarse una actualización atrás respecto a la cabeza.
            local remoteFace = entry.RemoteFace
            if remoteFace and remoteFace.Part and remoteFace.Part.Parent
                and remoteFace.Head and remoteFace.Head.Parent then
                remoteFace.Part.CFrame = remoteFace.Head.CFrame
                remoteFace.Part.Color = remoteFace.Head.Color
                remoteFace.Part.CastShadow = remoteFace.Head.CastShadow
            end

            -- La invisibilidad del avatar base ya no se recorre 60 veces/segundo.
            -- Los cambios de Tool siguen siendo event-driven y este guard sólo
            -- reafirma LTM unas pocas veces por segundo por si otro sistema lo toca.
            enforceRemoteHidden(entry, char, now, forceHidden)
            return true
        end

        entry.SyncPose = syncPose
        addRenderEntry(entry)
        syncPose(os.clock(), true)
        return true
    end

    local function cloneRemoteTemplate(baseUserId, rigType, outfitId)
        outfitId = tonumber(outfitId)
        local sourceKey = outfitId and ("outfit:" .. tostring(outfitId)) or ("user:" .. tostring(baseUserId))
        local key = sourceKey .. "|" .. tostring(rigType)
        local cached = syncState.TemplateCache[key]
        if cached and cached.Model then
            local ok, clone = pcall(function() return cached.Model:Clone() end)
            if ok and clone then
                cached.LastUsed = os.clock()
                return clone
            end
            pcall(function() cached.Model:Destroy() end)
            syncState.TemplateCache[key] = nil
        end

        local template, err
        if outfitId then
            local okDescription, description = pcall(function()
                return Players:GetHumanoidDescriptionFromOutfitIdAsync(outfitId)
            end)
            if not okDescription or not description then
                okDescription, description = pcall(function()
                    return Players:GetHumanoidDescriptionFromOutfitId(outfitId)
                end)
            end
            if okDescription and description then
                template, err = runtime.CreateAvatarCloneTemplateFromDescription(description, rigType)
                pcall(function() description:Destroy() end)
            else
                err = "No se pudo cargar el outfit remoto"
            end
        else
            template, err = runtime.CreateAvatarCloneTemplateFromUserId(baseUserId, rigType)
        end
        if not template then return nil, err end
        template.Parent = nil
        syncState.TemplateCache[key] = {Model = template, LastUsed = os.clock()}

        local count = 0
        local oldestKey, oldestAt = nil, math.huge
        for cacheKey, item in pairs(syncState.TemplateCache) do
            count = count + 1
            local used = numberOr(item and item.LastUsed, 0)
            if cacheKey ~= key and used < oldestAt then
                oldestAt = used
                oldestKey = cacheKey
            end
        end
        if count > syncState.TemplateCacheLimit and oldestKey then
            local oldest = syncState.TemplateCache[oldestKey]
            syncState.TemplateCache[oldestKey] = nil
            if oldest and oldest.Model then
                pcall(function() oldest.Model:Destroy() end)
            end
        end

        local ok, clone = pcall(function() return template:Clone() end)
        if ok and clone then return clone end
        return nil, "No se pudo clonar el template cacheado"
    end

    local function rebuildRemoteEntry(userData)
        local userId = tonumber(userData and userData.userId)
        if not userId or userId == player.UserId then return end

        local targetPlayer = Players:GetPlayerByUserId(userId)
        if not targetPlayer then
            destroyEntry(userId)
            return
        end

        local state = type(userData.state) == "table" and userData.state or {}
        local revision = userData.revision
        local entry = syncState.Entries[userId]
        if not entry then
            entry = {
                UserId = userId,
                Revision = nil,
                Generation = 0,
                Connections = {},
                Hidden = setmetatable({}, {__mode = "k"}),
                HiddenList = {},
                HiddenIndex = setmetatable({}, {__mode = "k"}),
                ToolGuards = setmetatable({}, {__mode = "k"}),
            }
            syncState.Entries[userId] = entry
        end

        if entry.Revision == revision and entry.Character == targetPlayer.Character
            and entry.Overlay and entry.Overlay.Parent then
            return
        end

        entry.Generation = (entry.Generation or 0) + 1
        local generation = entry.Generation
        disconnectEntry(entry)
        -- disconnectEntry incrementa otra vez para invalidar trabajos anteriores.
        entry.Generation = generation + 1
        generation = entry.Generation
        entry.Revision = revision

        task.spawn(function()
            local char = targetPlayer.Character
            local humanoid = char and char:FindFirstChildOfClass("Humanoid")
            if not humanoid then
                char = targetPlayer.CharacterAdded:Wait()
                humanoid = char and char:WaitForChild("Humanoid", 3)
            end
            if not runtime.Alive or not syncState.Alive or not char or not humanoid
                or syncState.Entries[userId] ~= entry or entry.Generation ~= generation then
                return
            end

            local baseUserId = tonumber(state.baseUserId) or userId
            local overlay, err = cloneRemoteTemplate(baseUserId, humanoid.RigType, state.outfitId)
            if not overlay then
                warn("[XeroHub AppearanceSync] No se pudo crear overlay de " .. tostring(userId) .. ": " .. tostring(err))
                return
            end

            if syncState.Entries[userId] ~= entry or entry.Generation ~= generation then
                overlay:Destroy()
                return
            end

            overlay.Name = "XeroRemoteAppearance_" .. tostring(userId)
            prepareRemoteOverlayPhysics(overlay)
            overlay.Parent = getSyncFolder()
            entry.Overlay = overlay
            entry.Character = char

            local layersOk, layersErr = pcall(function()
                applyRemoteLayers(entry, overlay, state)
                prepareRemoteOverlayPhysics(overlay)
            end)
            if not layersOk then
                warn("[XeroHub AppearanceSync] Capa remota parcial para " .. tostring(userId) .. ": " .. tostring(layersErr))
            end

            -- IMPORTANTE: primero demostramos que el overlay puede seguir la pose.
            -- El Character real se oculta SOLAMENTE después. Si cualquier dependencia
            -- del renderer falla, el jugador continúa visible con su avatar normal.
            if not bindRemotePose(entry, targetPlayer, char, overlay) then
                warn("[XeroHub AppearanceSync] No se pudo enlazar la pose de " .. tostring(userId) .. "; se conserva su avatar normal.")
                entry.Overlay = nil
                pcall(function() overlay:Destroy() end)
                return
            end
            bindRemoteBaseHidden(entry, char)

            local charConnection = targetPlayer.CharacterAdded:Connect(function()
                if syncState.Entries[userId] ~= entry then return end
                -- El siguiente fetch reconstruirá con el Character nuevo.
                entry.Character = nil
            end)
            table.insert(entry.Connections, charConnection)
        end)
    end

    local function reconcileRemoteStates(users)
        local seen = {}
        for _, userData in ipairs(users or {}) do
            local userId = tonumber(userData and userData.userId)
            if userId and userId ~= player.UserId then
                seen[userId] = true


                rebuildRemoteEntry(userData)
            end
        end

        for userId in pairs(syncState.Entries) do
            if not seen[userId] then destroyEntry(userId) end
        end

    end

    -- PERF: RenderStepped se conecta sólo mientras existe al menos un overlay remoto.
    -- addRenderEntry/removeRenderEntry administran su ciclo de vida.

    runtime.AppearanceSyncCleanup = function()
        if not syncState.Alive then return end
        syncState.Alive = false
        if syncState.RenderConnection then
            pcall(function() syncState.RenderConnection:Disconnect() end)
            syncState.RenderConnection = nil
        end
        for userId in pairs(syncState.Entries) do
            destroyEntry(userId)
        end
        table.clear(syncState.RenderEntries)
        for key, cached in pairs(syncState.TemplateCache) do
            if cached and cached.Model then
                pcall(function() cached.Model:Destroy() end)
            end
            syncState.TemplateCache[key] = nil
        end
        local folder = workspace:FindFirstChild("XeroHub_RemoteAppearances")
        if folder then pcall(function() folder:Destroy() end) end
    end

    -- Publicador: sólo incrementa Revision cuando el aspecto realmente cambia.
    task.spawn(function()
        while runtime.Alive and syncState.Alive do
            if syncRequest and tostring(game.JobId) ~= "" then
                local state = buildLocalAppearanceState()
                local encoded = HttpService:JSONEncode(state)
                if encoded ~= syncState.LastSerialized then
                    syncState.LastSerialized = encoded
                    syncState.Revision += 1
                end

                local now = os.clock()
                if now - syncState.LastPublishAt >= 6 or syncState.LastPublishedRevision == nil then
                    if httpPostState(state, syncState.Revision) then
                        syncState.LastPublishedRevision = syncState.Revision
                        syncState.LastPublishAt = now
                    end
                elseif encoded ~= nil and syncState.LastPublishedRevision ~= syncState.Revision then
                    if httpPostState(state, syncState.Revision) then
                        syncState.LastPublishedRevision = syncState.Revision
                        syncState.LastPublishAt = now
                    end
                end
            end
            task.wait(1.0)
        end
    end)

    -- Receptor: consulta ligera. Las revisiones sin cambios no reconstruyen nada.
    task.spawn(function()
        while runtime.Alive and syncState.Alive do
            local users = httpGetStates()
            if users then reconcileRemoteStates(users) end
            task.wait(1.5)
        end
    end)

    runtime.Track(Players.PlayerRemoving:Connect(function(leaving)
        if leaving and leaving.UserId ~= player.UserId then
            destroyEntry(leaving.UserId)
        end
    end))
end
end
]====]))()(runtime, player, Players, HttpService, workspace, RunService, isHairAccessory, manualAttachAppearanceAccessory, KORBLOX_UPPER_MESH, KORBLOX_TEXTURE)

startupSplashState.Finish()
runtime.NotificationsReady = true
